window.SB_STUDY = {
  quiz: [
    { d: "Spring_Boot_Roadmap", n: "partA", q: "Which part of the roadmap is the vocabulary you need before anything else, and what does it tell you to do with chapter 3?", opts: ["Foundations (ch 1-4) - read chapter 3 twice, because DI is the concept the whole book leans on", "Boot Basics (ch 5-9) - start.spring.io and your first runnable app", "Advanced (ch 22-28) - AOP, security, auto-configuration and caching", "Practice (ch 29-34) - unit tests, slices, integration tests and Docker"], a: 0, e: "Dependency injection is the load-bearing idea, so the roadmap explicitly says to read it twice. Boot Basics is about getting a first app running, Advanced is about being a good citizen in someone else's application, and Practice is about shipping - all of them come after the vocabulary." },
    { d: "Spring_Boot_Roadmap", n: "partC", q: "Which roadmap part owns @RestController, @Valid and status codes, and what has to come first in that part?", opts: ["Web and REST (ch 10-15); Boot Basics comes first because HTTP only means something once an app actually runs", "Foundations (ch 1-4); Web and REST comes first because annotations are hard without a JVM", "Data (ch 16-21); Web and REST comes first because the browser is the only data client", "Advanced (ch 22-28); Web and REST comes first because security sits in front of every endpoint"], a: 0, e: "The web part is where DispatcherServlet and the filter chain finally make sense, and that requires something to dispatch to. The other parts reorder it: the browser is not the only client, security is only one chapter of Advanced, and annotations do not need a running app to be understandable." },
    { d: "Spring_Boot_Roadmap", n: "partD", q: "Which part contains the N+1 trap and the transaction model, and where does the roadmap say the real performance wins live?", opts: ["Data (ch 16-21); the real wins are in the persistence layer, not in the web layer", "Advanced (ch 22-28); performance work is really a profiler exercise", "Web and REST (ch 10-15); serializing DTOs is where latency is won", "Practice (ch 29-34); only integration tests reveal real performance"], a: 0, e: "The Data part exists to prevent the N+1 trap and to get the transaction model right, and it says the real performance wins are there. Turning on a profiler is part of Advanced, DTO shape is only a small slice of latency, and tests are not where you find performance." },
    { d: "Spring_Boot_Roadmap", n: "partF", q: "Which part is the one where the roadmap tells you to stop reading docs and start reading source?", opts: ["Practice (ch 29-34): unit tests, slices, integration tests, Docker packaging and deployment", "Advanced (ch 22-28): caching and auto-configuration internals", "Data (ch 16-21): reading Hibernate's source for fetch strategies", "Foundations (ch 1-4): reading the IoC container source"], a: 0, e: "The Practice part is explicitly the point where you read source instead of docs, because that is where you own the whole pipeline: tests, packaging and deployment. Advanced and Data still have documentation that answers most questions, and Foundations is learnable from any Spring book." },
    { d: "Spring_Boot_Roadmap", n: "partB", q: "A colleague starts the book and asks what chapters 5-9 are supposed to give them. Which description matches the roadmap's Boot Basics part?", opts: ["Comfort with start.spring.io, @SpringBootApplication, application.properties and what auto-configuration does for you - ending with the first app you can actually curl", "A full tour of @RestController, DTOs and @Valid before any database code exists", "Deep study of the IoC container source so nothing is magic", "Docker packaging, CI pipelines and a production rollout checklist"], a: 0, e: "Boot Basics is explicitly about getting one application running - start.spring.io, @SpringBootApplication, application.properties and the auto-configuration magic - and it ends with the first app you can actually curl. Web annotations belong to Web and REST, container source belongs to Foundations or Practice, and shipping belongs to Practice at the very end." },
    { d: "Spring_Boot_Roadmap", n: "partE", q: "Your app must behave differently in dev, staging and prod, and you also need caching and profiling. Which part of the roadmap owns that material, and how does it frame the part?", opts: ["Foundations (ch 1-4), because profiles are vocabulary you need before anything else", "Advanced (ch 22-28): AOP, security, auto-configuration, caching, profiles and profiling - what changes when other people depend on your code", "Web and REST (ch 10-15), because profiles mostly switch endpoints on and off", "Practice (ch 29-34), because deployment is where profiles finally matter"], a: 1, e: "Advanced is defined as the part for when other people depend on your code, and profiles, caching, AOP and profiling all sit there. Foundations is framework-free vocabulary, the web part is about endpoints and status codes, and Practice is tests and shipping rather than configuration strategy." },
    { d: "Spring_Boot_Roadmap", n: "partC", q: "A stakeholder asks which chapters to read to learn how a JSON body gets validated and how error status codes are chosen. Which answer matches the roadmap?", opts: ["Data (ch 16-21), because validation runs against the entity before it is saved", "Foundations (ch 1-4), because annotations like @Valid are core vocabulary", "Web and REST (ch 10-15) - @RestController, DTOs, @Valid, status codes and error handling, after Boot Basics", "Advanced (ch 22-28), because error handling is a cross-cutting concern like security"], a: 2, e: "The web part owns request and response shapes, @Valid and status codes, and the roadmap insists Boot Basics comes first because HTTP only means something once an app actually runs. Entities are the business of the Data part, @Valid is not a Foundations topic, and exception handling in the web tier is not the AOP and security chapter." },
    { d: "Spring_Boot_Roadmap", n: "partA", q: "A friend refuses to start the book because they have never written a Spring Boot app. Which roadmap answer is correct?", opts: ["Start with Practice (ch 29-34), because tests define what the vocabulary has to do", "Skip straight to Boot Basics (ch 5-9), because you need a running app before vocabulary means anything", "Start with the Data part (ch 16-21), because persistence is where the vocabulary shows up", "Start with Foundations (ch 1-4) anyway: annotations, IoC, dependency injection and what a bean actually is - nothing there needs Spring Boot specifically"], a: 3, e: "Foundations is deliberately framework-free: annotations, IoC, dependency injection and what a bean is, with no Boot required, which is exactly why it can come first. Boot Basics follows it rather than replacing it, and both Data and Practice assume the earlier parts are already in place." },
    { d: "Spring_Boot_Roadmap", n: "partD", q: "Your service keeps introducing bugs that only appear under concurrent writes. Which part does the roadmap flag as the most bug-prone area of the book, and what makes it so?", opts: ["Data (ch 16-21): @Transactional, propagation and rollback rules, where one wrong annotation silently commits a partial update", "Web and REST (ch 10-15): status codes and error handling are easy to get wrong", "Advanced (ch 22-28): AOP proxies break in ways that are hard to see", "Practice (ch 29-34): integration tests are the only place such bugs surface"], a: 0, e: "The roadmap names @Transactional, propagation and rollback inside the Data part as the most bug-prone material, because a wrong propagation or missing rollbackFor quietly changes what gets committed. Web mistakes show up as wrong status codes rather than corrupted data, self-invocation is real but is not what the roadmap singles out, and tests detect these bugs rather than defining where the risky material lives." },
    { d: "Spring_Boot_Roadmap", n: "partF", q: "You can already build features end to end. Which part tells you what to do next, and what does it tell you to stop doing?", opts: ["Advanced (ch 22-28): stop writing your own configuration and let auto-configuration do it", "Practice (ch 29-34): unit tests, slices, integration tests, Docker packaging and deployment - the point where you read source instead of docs", "Boot Basics (ch 5-9): stop copying tutorial snippets and always start from start.spring.io", "Foundations (ch 1-4): stop reading blog posts and read the reference docs"], a: 1, e: "Practice is the part about building, testing and shipping, and the roadmap explicitly makes it the point where you switch from docs to reading source because you now own the whole pipeline. Auto-configuration internals are Advanced material, and neither Boot Basics nor Foundations tells you to stop reading anything." },
    { d: "Spring_Boot_Roadmap", n: "partE", q: "Your team publishes a shared library that other applications will embed as a starter. Which roadmap part best prepares you for that job?", opts: ["Foundations (ch 1-4), because a library still needs IoC and dependency injection vocabulary", "Web and REST (ch 10-15), because your library exposes endpoints", "Advanced (ch 22-28), because it covers auto-configuration and profiles - how to be a good citizen in someone else's app", "Practice (ch 29-34), because you must test the starter before publishing it"], a: 2, e: "Being a good citizen in someone else's application is stated as the purpose of Advanced, and auto-configuration plus profiles are precisely how a shared library behaves politely inside a host app. Foundations is generic vocabulary, exposing endpoints is not the point of an embedded library, and testing is Practice but is not the framing the roadmap gives this part." },
    { d: "Spring_Boot_Roadmap", n: "partB", q: "The roadmap tags one part 'first app'. Which part is explicitly about learning what auto-configuration does for you before you learn to replace it?", opts: ["Foundations (ch 1-4), where the exit criterion is explaining what a bean is", "Web and REST (ch 10-15), where the exit criterion is a working validated endpoint", "Advanced (ch 22-28), where the exit criterion is writing your own starter", "Boot Basics (ch 5-9), where you meet auto-configuration before replacing it and leave with the first app you can actually curl"], a: 3, e: "Boot Basics is defined as the place where you see what auto-configuration does for you before you learn to override it, ending in a runnable app you can curl. Foundations stops at vocabulary, the web part is about endpoints, and writing your own auto-configuration is Advanced material that comes much later." },
    { d: "Spring_Boot_Roadmap", n: "partA", q: "Three chapters in, the roadmap tells you to read chapter 3 a second time. What is in that part, and why can you read it before writing any Boot code?", opts: ["Foundations (ch 1-4): annotations, IoC, dependency injection and what a bean is - nothing there needs Spring Boot specifically", "Boot Basics (ch 5-9): you need a running app before annotations make sense", "Data (ch 16-21): dependency injection only matters once a repository exists", "Practice (ch 29-34): tests are what teach you the vocabulary"], a: 0, e: "Foundations covers annotations, IoC, dependency injection and what a bean actually is, and the roadmap stresses that none of it requires Spring Boot - which is why chapter 3 on DI gets read twice. Boot Basics, Data and Practice all build on that vocabulary rather than supplying it." },
    { d: "Spring_Boot_Roadmap", n: "partC", q: "A teammate asks when the filter chain and DispatcherServlet will finally make sense. What does the roadmap say has to happen first?", opts: ["You must finish Foundations, because IoC explains how the front controller is registered", "You must be through Boot Basics, because Web and REST only makes sense once you have a running app to send requests to", "You must finish the Data part, because requests only matter once they reach a repository", "You must finish Practice, because only an end-to-end test reveals the request path"], a: 1, e: "The roadmap puts the filter chain and DispatcherServlet in Web and REST and requires Boot Basics first, because HTTP only means something once there is an app that answers it. Foundations gives vocabulary but no running app, the Data part sits after the web part, and Practice comes last of all." },
    { d: "Spring_Boot_Roadmap", n: "partD", q: "A teammate claims the N+1 trap is a web-layer problem because the controller walks the collection. Which part of the roadmap contradicts this, and what does it teach instead?", opts: ["Web and REST (ch 10-15), because serialization is where the extra queries come from", "Advanced (ch 22-28), because you fix it with caching", "Data (ch 16-21), the part that exists to prevent the N+1 trap, where the fix belongs to persistence: entities, repositories and fetch strategy", "Practice (ch 29-34), because you only discover it by counting queries in an integration test"], a: 2, e: "The N+1 trap is defined in the Data part as a persistence problem solved by fetch strategy at the repository level, not by the controller that happens to trigger it. Caching in Advanced can hide the symptom but is not the roadmap's answer, and the web part only serializes whatever was already loaded." },
    { d: "Spring_Boot_Startup", n: "main", q: "You write main() calling SpringApplication.run(App.class, args). Which statement about that call is correct?", opts: ["It returns a fully refreshed ApplicationContext whose web server is already bound and listening", "It returns a plain context object with no beans registered yet", "main() returns null and the container starts lazily on the first HTTP request", "refresh() only registers bean definitions; singleton instantiation happens later"], a: 0, e: "By the time run() returns, the environment is prepared, the context is refreshed - which is the step that instantiates and wires singletons - and the embedded server is accepting traffic, which is why the last two options are wrong. main() also has to return void, so there is nothing for it to return." },
    { d: "Spring_Boot_Startup", n: "run", q: "Put the SpringApplication.run() phases in the correct order.", opts: ["banner and environment -> create context and load bean definitions -> run auto-configuration -> instantiate and wire beans (refresh) -> start web server -> ApplicationReadyEvent", "create context -> prepare environment -> auto-configure -> banner -> refresh", "refresh -> auto-configure -> environment -> banner -> server", "environment -> auto-configure -> refresh -> banner -> server"], a: 0, e: "Environment and banner come first because listeners and profile-specific config read the environment; refresh instantiates the singletons, which is where @Bean methods and auto-configurations meet; the server is up before ApplicationReadyEvent, which is the documented 'ready for requests and runners' signal. Every other ordering breaks a dependency - you cannot condition on properties before the environment exists, and you cannot log a banner from a bean that was never created." },
    { d: "Spring_Boot_Startup", n: "autoconfig", q: "Where does Spring Boot 3 read its list of auto-configuration candidates from, and what is the decisive criterion for inclusion?", opts: ["META-INF/spring/org.springframework.boot.autoconfigure.AutoConfiguration.imports; only the classes named by the jars actually on your classpath are candidates", "spring.factories, which Boot 3 still reads before the imports file", "A classpath scan for every @Configuration class in every jar", "The imports file plus spring.factories, merged in alphabetical order"], a: 0, e: "The imports file is the Boot 2.7+/3.x mechanism, and auto-configuration registration from spring.factories was removed in 3.0, so options 2 and 4 describe a world that no longer exists. A component scan does not pick up auto-configurations from other jars - it only finds @Configuration classes under your base package - so a missing bean is usually a missing dependency or a missing property, not a missing scan." },
    { d: "Spring_Boot_Startup", n: "conditional", q: "Startup fails with 'Failed to configure a DataSource: 'url' attribute is not specified and no embedded datasource could be configured.' Which checks, in order, are most likely to find the cause?", opts: ["Is a JDBC starter on the classpath, and is spring.datasource.url set to a reachable value", "Is @SpringBootApplication in a package above your repositories", "Is port 8080 free", "Do your entities have @Entity"], a: 0, e: "DataSourceAutoConfiguration is @ConditionalOnClass(DataSource) and @ConditionalOnMissingBean, and DataSourceProperties binds spring.datasource.url - so a missing starter plus a missing url produces exactly this message. Package placement causes a component-scan miss reported as a missing bean, the port problem surfaces later as 'Port already in use', and @Entity only matters once a DataSource exists." },
    { d: "Spring_Boot_Startup", n: "conditional", q: "An auto-configuration is annotated @Bean @ConditionalOnMissingBean(DataSource.class). What does that condition actually promise?", opts: ["The auto-config backs off and declares no bean if the application has already defined a DataSource - it is a back-off, not a guarantee", "The bean is always created and any application bean of that type is replaced by it", "The bean is created only if the application defines a DataSource", "The condition is evaluated on every method call at runtime"], a: 0, e: "@ConditionalOnMissingBean is a back-off: your bean wins and the auto-config quietly steps aside, which is exactly what lets you override auto-configuration without excluding anything. It is a bean-definition-time condition, not a per-call runtime check, and it is order-sensitive - conditions are evaluated during configuration class parsing, so auto-configurations that depend on each other use @AutoConfigureBefore/After rather than relying on scan order." },
    { d: "Spring_Boot_Startup", n: "conflict", q: "Startup dies with NoUniqueBeanDefinitionException: 'expected single matching bean but found 2: emailSenderSmtp, emailSenderSes'. Which fix is the least surprising?", opts: ["Mark the preferred implementation @Primary, or name it at the injection point with @Qualifier(\"emailSenderSmtp\")", "Add @Autowired(required = false) to both fields", "Delete one of the two @Bean methods", "Set spring.main.allow-bean-definition-overriding=true"], a: 0, e: "@Primary and @Qualifier both express intent: here is the one I mean. required = false turns a startup-time error into a null at runtime, which is worse; deleting a bean method deletes a feature; and allow-bean-definition-overriding controls definition overriding, not ambiguity - it will not fix this and it silently breaks ordering-sensitive auto-configurations." },
    { d: "Spring_Boot_Startup", n: "nobean", q: "Constructor injection fails with 'Parameter 0 of constructor in OrderService required a bean of type PaymentClient that could not be found'. Order the checks from most to least likely.", opts: ["(1) is PaymentClient implemented by a class annotated @Component/@Service, (2) is that class inside or below your @SpringBootApplication package, (3) is the @Bean method that creates it conditional or in another profile, (4) is the client library itself on the classpath", "Check the heap size, the free port and the database first, because a missing bean message is usually a resource problem", "Re-run with --debug and read the Condition Evaluation Report, which will name the failing condition", "Delete the constructor and use field injection so the context starts even when the dependency is absent"], a: 0, e: "Missing-bean errors are structural, not environmental: a missing stereotype, a package outside the component-scan root, a bean disabled by a condition or profile, and only then a missing dependency. Heap, port, database and cache problems produce completely different messages. The condition evaluation report from --debug is a great tool, but it reports on conditions - a bean that is simply not registered as a component will not appear there as a failed condition." },
    { d: "Spring_Boot_Startup", n: "wire", q: "Which injection style lets the container use constructor arguments to satisfy dependencies and fail fast at startup if a dependency is missing?", opts: ["Constructor injection - dependencies become final fields and the context refuses to start when one is unsatisfied", "Field injection with @Autowired - missing fields stay null until first use", "Setter injection - the object is created first and wired afterwards, so gaps are invisible", "Field injection plus a null check in every method"], a: 0, e: "Constructor injection makes the dependency a required part of the object's identity: final fields, no partially constructed object, and a fail-fast context. Field and setter injection defer the problem to runtime, where you get a NullPointerException in production rather than a clear startup error." },
    { d: "Spring_Boot_Startup", n: "portbusy", q: "The log ends with 'Web server failed to start. Port 8080 was already in use.' What actually happened, and what are your real options?", opts: ["Another process holds the socket; change server.port, or find and stop the holder, or use server.port=0 for a random free port in tests", "Spring Boot never starts on a busy port - it retries forever until it succeeds", "Tomcat bound to IPv6 only, so the port is 'reserved'", "The context failed to refresh, which is why the server could not bind"], a: 0, e: "The connector fails fast and kills the context - there is no retry loop and it is not an IPv6 quirk. In tests, port 0 is the idiomatic fix because it lets the OS pick a free port and lets you inject server.port into the test. In production you want either a fixed port from configuration or a service-level port assignment, not a random one." },
    { d: "Spring_Boot_Startup", n: "ready", q: "The log shows 'Tomcat started on port(s): 8080 (http)' followed by 'Started App in 4.231 seconds'. What do those two lines prove - and what do they not prove?", opts: ["The context refreshed and the connector is bound, so traffic is accepted; they say nothing about Actuator readiness or health indicators, which can still be DOWN", "The JVM started; the port may still be unbound", "The database connection pool is warm and all migrations ran", "Scheduled tasks and ApplicationRunner runners have completed"], a: 0, e: "Those two lines are about the servlet container and the refresh, nothing more. Database connectivity shows up in health indicators and in the Hikari pool log, migration status comes from Flyway or Liquibase, and runners run before the ready event but their failures would have killed startup. Under Kubernetes the thing that decides traffic is the readiness probe, which can be DOWN while these lines look perfectly healthy." },
    { d: "Spring_Boot_Startup", n: "context", q: "A developer asks whether they can just call refresh() again to pick up new bean definitions without restarting the app. What does the diagram say happens?", opts: ["Every singleton is constructed again, producing duplicates of each bean and duplicate side effects", "Component scanning runs again and silently replaces every existing bean definition", "The embedded Tomcat restarts on the same port, so startup fails with a port conflict", "Refresh is the phase that instantiates singletons and is meant to run once per context - a second refresh reuses the singletons already cached"], a: 3, e: "The context holds bean definitions first and singleton instances second, and refresh is the one-shot phase that fills the second from the first, so a repeat refresh works off the cached singletons. Rebuilding everything, re-scanning, and restarting Tomcat all describe machinery the container does not run twice - the server starts once, late in the first refresh." },
    { d: "Spring_Boot_Startup", n: "bean", q: "You declare one bean with @Component, another with a @Bean method, and a @ConfigurationProperties record. Which statement about their creation is true?", opts: ["All three become bean definitions, @ConfigurationProperties binding happens at this point, and dependency resolution - not declaration order - decides when each object is actually created", "@Component classes are created first in classpath scan order, then @Bean methods, then configuration properties records", "Configuration properties records are bound before any bean definition exists, because they come straight from the environment", "The order they appear in your source files is the order the container uses"], a: 0, e: "Both stereotypes and @Bean methods are just different routes to a bean definition, binding happens while those definitions are being instantiated during refresh, and the container sorts creation by dependency need. Source order and classpath scan order never decide creation order, and although the environment is prepared early, binding to a bean still waits for that bean to exist." },
    { d: "Spring_Boot_Startup", n: "server", q: "A developer asks why Tomcat starts so late in startup, right before the 'Started App in ...' line. What does the diagram say?", opts: ["Tomcat starts first so health endpoints can answer while beans are still being created", "The embedded server is started late, once everything is already registered - it only binds a port, because there is no WAR and no external servlet container", "The container must wait for an external application server to hand over the servlet context before it can scan for beans", "Spring Boot downloads the Tomcat artifacts from the network during this step, which is why it takes time"], a: 1, e: "Server startup is deliberately last: beans, auto-configuration and the filter chain must be registered before anything accepts traffic, and Boot runs an embedded Tomcat instead of packaging a WAR. Opening the port early would advertise an app whose beans do not exist yet, and no external container or artifact download is involved." },
    { d: "Spring_Boot_Startup", n: "run", q: "A listener needs to react as early as possible to application startup, before the environment exists. Which statement about SpringApplication.run() and events is correct?", opts: ["run() publishes only ApplicationReadyEvent, at the very end of startup", "Events are published by the beans themselves, so any bean can hear ApplicationStartingEvent", "run() publishes the lifecycle events in order, and ApplicationStartingEvent goes out before any context exists - so an early listener must be registered on the SpringApplication before run() is called", "Lifecycle events are only published when an Actuator dependency is on the classpath"], a: 2, e: "SpringApplication.run() is what drives the whole event sequence, and the earliest events fire before a context - and therefore before any bean - exists, so an early listener has to be added on the SpringApplication before run() rather than declared as a bean. Beans cannot hear events that fire before they are created, and the single-event and Actuator-gated stories are simply not how the boot sequence works." },
    { d: "Spring_Boot_Startup", n: "ready", q: "Kubernetes reports the readiness probe failing even though the log says 'Started App in 4.231 seconds'. Which explanation fits the diagram?", opts: ["Startup and readiness are different states: the app finished starting while a health indicator such as a DataSource is still DOWN, so the probe keeps the pod out of rotation", "'Started' only means the JVM booted, so the context never refreshed and no filter chain exists", "The port was never bound, so every probe connection is refused", "Readiness probes are answered by Tomcat before the filter chain exists, so they always fail"], a: 0, e: "The ready node says ApplicationReadyEvent fires after the web server is listening and that readiness probes report on that state, so a DOWN health indicator keeps the pod out of rotation while the startup log looks perfect. If the context had not refreshed or the port were unbound you would never see 'Started App in ...' at all, and probes are answered through the normal filter chain once the server is up." },
    { d: "Spring_Boot_Bean_Lifecycle", n: "populate", q: "A bean's @PostConstruct method calls a @Autowired repository. Why is that guaranteed to work?", opts: ["Because populateBean (dependency injection) completes before any initialization callback, so the injected field is already set", "Because @PostConstruct runs before the constructor", "Because the repository is created lazily on first method call", "Because @PostConstruct is invoked by the container after the whole context is refreshed"], a: 0, e: "The order is instantiate (constructor) -> populate (injection) -> initialize (@PostConstruct, afterPropertiesSet, init method), so injected fields are ready. @PostConstruct is called by a BeanPostProcessor during initialization of that specific bean, not after the whole context refreshes, which is why the other two orderings are wrong - and why calling a bean from another bean's constructor is still unsafe." },
    { d: "Spring_Boot_Bean_Lifecycle", n: "postconstruct", q: "Which callback runs FIRST among @PostConstruct, InitializingBean.afterPropertiesSet() and a custom init method declared with @Bean(initMethod = \"init\")?", opts: ["@PostConstruct", "InitializingBean.afterPropertiesSet()", "The custom init method", "They all run at the same point in a defined order only if the bean implements Ordered"], a: 0, e: "CommonAnnotationBeanPostProcessor invokes @PostConstruct in its postProcessBeforeInitialization; the container then calls afterPropertiesSet on InitializingBean, and only then the custom init method. That ordering matters in practice: an @PostConstruct method that assumes the custom init method already ran is a bug waiting to happen." },
    { d: "Spring_Boot_Bean_Lifecycle", n: "afterinit", q: "What is the documented execution order of the initialization callbacks on a bean?", opts: ["@PostConstruct -> BeanNameAware and other Aware callbacks' post-processing -> InitializingBean.afterPropertiesSet -> custom init-method", "BeanNameAware -> @PostConstruct -> custom init-method -> afterPropertiesSet", "custom init-method -> afterPropertiesSet -> @PostConstruct", "All callbacks run in parallel if the bean is lazy"], a: 0, e: "Aware callbacks (BeanNameAware, BeanClassLoaderAware, ApplicationContextAware and friends) are invoked by the container before the initialization callbacks, @PostConstruct is first among those, InitializingBean comes next, and the custom init method is last. Laziness changes when the lifecycle runs, not its order." },
    { d: "Spring_Boot_Bean_Lifecycle", n: "aware", q: "A bean wants a reference to the ApplicationContext so it can look up beans dynamically. Which callback gives it that, and what is the main smell?", opts: ["ApplicationContextAware; holding the context in a field is a service locator that hides dependencies and is hard to test", "BeanNameAware; it exposes the context, not the name", "@PostConstruct; the context is passed as a parameter there", "DisposableBean; it is a shutdown callback, not an injection point"], a: 0, e: "ApplicationContextAware is the documented hook for a context reference, and using it for dynamic lookup is the classic service-locator anti-pattern: the class now secretly depends on the whole container. Inject the specific collaborator instead, and if you truly need programmatic lookup, inject ApplicationContext deliberately and narrowly rather than hiding it behind business methods." },
    { d: "Spring_Boot_Bean_Lifecycle", n: "destroyed", q: "On shutdown, which order do the destruction callbacks fire in?", opts: ["@PreDestroy -> DisposableBean.destroy() -> custom destroy-method", "custom destroy-method -> DisposableBean.destroy() -> @PreDestroy", "DisposableBean.destroy() -> @PreDestroy -> custom destroy-method", "Only DisposableBean is called if the bean implements it"], a: 0, e: "The container calls @PreDestroy first, then DisposableBean, then the custom destroy method, in that order, on the way down. If a bean implements DisposableBean, that callback still runs alongside the annotation - the options that make them mutually exclusive are wrong - and beans are destroyed in reverse dependency order, so your dependencies outlive the beans that use them." },
    { d: "Spring_Boot_Bean_Lifecycle", n: "ready", q: "Which event tells you the context is fully refreshed, the server is up, and CommandLineRunner/ApplicationRunner beans have finished?", opts: ["ApplicationReadyEvent", "ApplicationStartingEvent", "ContextRefreshedEvent", "ApplicationFailedEvent"], a: 0, e: "ApplicationReadyEvent is the last lifecycle event of a successful startup - context refreshed, runners executed, server listening. ApplicationStartingEvent is the very first, before anything is prepared; ContextRefreshedEvent fires when the context finishes refreshing but before runners run and before the server is fully announced; ApplicationFailedEvent means startup broke." },
    { d: "Spring_Boot_Bean_Lifecycle", n: "defined", q: "Right after component scanning finishes, what does the container actually hold?", opts: ["Fully constructed singleton objects with null dependencies, waiting for populate", "BeanDefinitions - names, class names and property values with no instantiated objects, which getBean() will walk later", "Bytecode-enhanced proxies for every scanned class, ready for AOP", "An empty BeanFactory, because scanning is deferred until the first getBean call"], a: 1, e: "Scanning and @Bean methods only register metadata: a definition says how to build the object, and nothing is allocated until refresh asks for it. Half-built singletons describe instantiate rather than define, proxies are created much later by a BeanPostProcessor, and scanning is not deferred - the definitions are all there before any instance is." },
    { d: "Spring_Boot_Bean_Lifecycle", n: "instantiate", q: "A constructor of a scanned bean throws IllegalArgumentException during startup. What is the consequence?", opts: ["Only that bean is marked failed; the rest of the app starts and the error surfaces on the first request that needs it", "The container retries construction up to three times, then falls back to field injection", "The whole refresh fails and the application never starts, because instantiation happens inside refresh and an exception here aborts it", "The bean is silently dropped, and autowiring reports a missing bean later"], a: 2, e: "Instantiation happens inside refresh, so an exception thrown by a constructor aborts the refresh and the context never comes up - that is the fail-fast behaviour the diagram calls out. Retry-with-fallback and silent dropping are not something the container does, and a missing bean error is reported at injection time, not as a swallowed constructor failure." },
    { d: "Spring_Boot_Bean_Lifecycle", n: "beforeinit", q: "A library's BeanPostProcessor modifies your bean in postProcessBeforeInitialization. What state is the bean in when that hook runs?", opts: ["The object exists but no dependencies have been injected yet, because the hook runs right after construction", "It is fully initialized, including @PostConstruct and any custom init method", "It is already an AOP proxy, because proxies are created in the before-init hook", "Dependencies are already injected but @PostConstruct has not run yet - the hook sits between populate and initialize"], a: 3, e: "The before-init hook runs after injection and before any initialization callback, so fields are set while @PostConstruct is still pending - that ordering is exactly what the diagram shows. Construction-only state describes instantiate, completed initialization describes after-init, and proxies are created in postProcessAfterInitialization rather than here." },
    { d: "Spring_Boot_Bean_Lifecycle", n: "populate", q: "OrderService and InventoryService inject each other with field @Autowired and startup fails with a circular reference error. At which step was the loop detected, and why?", opts: ["Populate: both objects exist but their fields are still null, and neither can finish wiring until the other is available", "Instantiate: the second constructor calls back into the first constructor", "Before-init: a BeanPostProcessor rejected the half-wired bean", "Ready: publishing the singleton would have created two copies of the same bean"], a: 0, e: "Field injection happens in populate, so a loop means the container cannot complete wiring for either bean and gives up there. By instantiate time no collaborator arguments are involved because the injection is on fields, no BeanPostProcessor has run yet, and the singleton cache is only touched once the bean is finished." },
    { d: "Spring_Boot_Bean_Lifecycle", n: "defined", q: "A service is annotated @Lazy and the application starts without ever creating it. What did component scanning produce?", opts: ["A partially constructed instance with its fields left null", "A BeanDefinition carrying the lazy flag - a record of how to create the bean later, with no object allocated yet", "A JDK dynamic proxy stub that defers construction until the first method call", "No definition at all, because lazy beans are skipped during scanning"], a: 1, e: "A definition is metadata including flags such as lazy, so a lazy singleton legitimately starts with no object in existence and getBean() creates it on demand later. A half-built instance and a proxy stub confuse a definition with an instance, and if scanning had produced no definition at all then getBean would fail instead of creating anything." },
    { d: "Spring_Boot_Bean_Lifecycle", n: "instantiate", q: "A bean has two constructors, one no-arg and one annotated @Autowired. Which one does the container pick during instantiate?", opts: ["The no-arg constructor always, because field injection is the container's default strategy", "Whichever constructor appears first in the source file", "The @Autowired constructor, because constructor selection happens here and a single autowired constructor is marked as the required one", "Neither; startup fails with NoUniqueBeanDefinitionException until you add @Qualifier to the class"], a: 2, e: "Constructor selection is explicitly part of instantiate: one @Autowired constructor is required, none means the no-arg or sole public constructor with field or setter injection to follow, and two unmarked candidates are an error. Source order is never consulted, and the failure for ambiguous constructors is about construction, not about a missing bean definition." },
    { d: "Spring_Boot_Bean_Lifecycle", n: "beforeinit", q: "A monitoring library says it hooks into beans 'before initialization'. Which of these can it legitimately do there?", opts: ["Wrap the bean in an AOP proxy, because proxy creation happens in the before-init hook", "Read the results of @PostConstruct, because initialization has already happened", "Satisfy a missing @Autowired field, because injection has not run yet", "Adjust the bean's state before @PostConstruct validates it - injection is done and initialization has not started"], a: 3, e: "The before-init window opens right after populate and closes before the first initialization callback, so the library can mutate a fully injected object before @PostConstruct validates it. Proxies are created in after-init, @PostConstruct output does not exist yet at that point, and injection is already finished - there are no missing fields left to satisfy." },
    { d: "Spring_Boot_Bean_Lifecycle", n: "postconstruct", q: "You write new OrderService() inside another component's method and expect its @PostConstruct to initialise it. What actually happens?", opts: ["Nothing - @PostConstruct only runs for beans the container created, so the hand-made object is never initialised and is wired only as much as you wired it yourself", "It runs immediately after the constructor returns, because the annotation does not care who constructed the object", "It runs at the next refresh, once the object has been registered as a bean", "It throws IllegalStateException, because two objects of the same class would exist"], a: 0, e: "The diagram is explicit that @PostConstruct runs only for managed beans, and a manually new-ed object bypasses the container entirely so no callback is ever scheduled for it. The annotation does not attach itself to constructors, unregistered objects are invisible to a refresh, and duplicate instances of a class are perfectly legal." },
    { d: "Spring_Boot_Bean_Lifecycle", n: "aware", q: "A bean needs its own bean name so it can register itself under that name in an external map. Which callback provides it, and when does it run?", opts: ["ApplicationContextAware, but only after @PostConstruct has finished", "BeanNameAware.setBeanName(), invoked after injection and before @PostConstruct - so the name is available while the bean initialises", "@Value, which reads the name from a property called bean.name", "BeanFactoryAware, which returns this bean's definition rather than its name"], a: 1, e: "BeanNameAware is one of the Aware interfaces the container calls in the Aware stage, which sits after populate and before the initialization callbacks, so the name is ready by the time @PostConstruct runs. ApplicationContextAware hands over the context instead, @Value reads application properties rather than container metadata, and BeanFactoryAware gives you the factory for looking other beans up." },
    { d: "Spring_Boot_Layers", n: "dto", q: "Should a @RestController return a JPA entity directly? Give the best reason.", opts: ["No - map to a DTO, because entities leak lazy-loading and persistence concerns into your API contract and force a DB change to become an API change", "No - return a Map so the shape can change freely", "Yes - entities are already plain POJOs with getters and setters", "Yes, as long as the entity is annotated @JsonIgnoreProperties(ignoreUnknown = true)"], a: 0, e: "Entities are a persistence model with lazy proxies, bidirectional back-references and a schema that has no business changing your public API. A DTO is the boundary that lets the schema evolve independently, keeps validation and OpenAPI annotations where they belong, and avoids serializing anything you did not intend. Returning a Map just moves the problem to untyped JSON with no compiler help." },
    { d: "Spring_Boot_Layers", n: "tx", q: "Which layer should own the @Transactional annotation, and why there?", opts: ["The service layer, because the transaction boundary is a business use-case decision and only the service knows the unit of work", "The repository, because the database is what actually commits", "The controller, because it is the only place that knows when the request ends", "Whichever layer is called first, since the boundary is where the proxy sits"], a: 0, e: "The service method is the use case, so it is the natural unit of work; the repository is a mechanism inside it, and the controller is an adapter that must not own atomicity across multiple service calls. Note the fourth option is a trap: the boundary is the annotation on a proxied public method, not the first method that happens to run." },
    { d: "Spring_Boot_Layers", n: "controller", q: "What does @RestController change compared to @Controller?", opts: ["Every handler return value is written to the response body as JSON instead of being resolved as a view name", "It enables bean validation on the parameters", "It makes the class a singleton instead of a request-scoped bean", "It bypasses the DispatcherServlet and handles the request directly"], a: 0, e: "@RestController is @Controller plus @ResponseBody at class level, so return values are serialized (usually by Jackson) rather than treated as view names. Validation comes from @Valid or @Validated, request scope comes from @Scope, and the request still goes through the DispatcherServlet - the other three options describe unrelated features." },
    { d: "Spring_Boot_Layers", n: "repository", q: "You declare interface OrderRepository extends JpaRepository<Order, Long> with no implementation class. How do calls on it work?", opts: ["Spring Data generates a runtime proxy that implements your interface and derives queries from method names or @Query", "The compiler synthesizes an implementation class at build time", "JpaRepository has a static factory you must call manually", "Spring injects a raw EntityManager, so your method names are irrelevant"], a: 0, e: "Spring Data repositories are runtime proxies (JDK dynamic proxies, because the interface is proxied) with a query-dispatch strategy per method family - findBy, deleteBy, @Query, @Modifying. Nothing is generated at compile time, no manual factory is involved, and a raw EntityManager is what the proxy uses under the hood rather than what you use." },
    { d: "Spring_Boot_Layers", n: "aop", q: "In a layered design, where does the AOP proxy for a service bean sit?", opts: ["Outside the service bean, between the caller and the target - so the caller holds a proxy reference, never the raw target", "Inside the service, wrapping its repository calls", "In the controller, wrapping the service field", "In the DispatcherServlet, wrapping every handler invocation"], a: 0, e: "Spring AOP is proxy-based and outside-in: the container registers the proxy, and injecting into clients gives them the proxy. That single fact explains self-invocation problems, why @Transactional must sit on a public method, and why advice is not applied to internal private calls. Filters and interceptors are the place for cross-cutting web concerns; the AOP proxy is for beans." },
    { d: "Spring_Boot_Layers", n: "browser", q: "A frontend developer asks why your API answers 404 with a JSON body instead of throwing the Java exception at them. What does the client layer of the diagram say?", opts: ["Errors cross a network boundary as status codes and payloads, never as Java exceptions - the client sees your contract, not your stack trace", "Exceptions are serialized automatically and the client deserializes them back into the same class", "Client and server share a JVM in this architecture, so exceptions propagate unchanged", "Status codes are optional; a 200 with an error field is equivalent because clients can read both"], a: 0, e: "The client layer states that everything crosses a network boundary and errors come back as status codes, which is why the server must translate failures into HTTP responses deliberately. Serializable exceptions, a shared JVM and ignoring status codes all pretend the boundary does not exist, and a 200 for a missing resource breaks caching, monitors and client error handling alike." },
    { d: "Spring_Boot_Layers", n: "security", q: "A JWT filter must run before CORS handling, and both are registered as Filter beans for /*. What does the diagram tell you to control?", opts: ["The service layer's @Transactional order, because security and transactions share one proxy", "Filter order - the chain runs outside the DispatcherServlet where no controller exists yet, so @Order or a FilterRegistrationBean decides who sees the request first", "Controller method order, because the DispatcherServlet invokes filters after handler mapping", "Nothing - all filters for /* run simultaneously and the container interleaves them"], a: 1, e: "Filters are an ordered pipeline in front of the DispatcherServlet, so precedence is set on the filters themselves through @Order, Ordered or FilterRegistrationBean.setOrder. Transactions are AOP around beans rather than filters, controllers are not involved until after the chain, and the container runs the chain sequentially in defined order, never in parallel." },
    { d: "Spring_Boot_Layers", n: "dispatcher", q: "You add a @RestControllerAdvice with an @ExceptionHandler method. Where does that handler actually get applied?", opts: ["In a servlet filter, because advice must run before handler mapping", "In the service layer, closest to where the exception is thrown", "In the DispatcherServlet, which centralises exception handling - the exception is resolved to a handler there after your controller method throws", "In the JPA layer, because most exceptions are persistence exceptions"], a: 2, e: "The diagram says exception handling is centralised in the front controller: the HandlerAdapter invokes your method, the exception travels back to the DispatcherServlet, and @ControllerAdvice resolves it to an @ExceptionHandler that builds the response. Filters run before mapping and know nothing of handler methods, and services and repositories throw exceptions rather than mapping them to HTTP." },
    { d: "Spring_Boot_Layers", n: "service", q: "You find HttpServletRequest injected into a @Service method. Which rule from the diagram does this break?", opts: ["The service must own persistence details, so HttpServletRequest is fine but repository calls are not", "One transaction per service class rather than per method, so a web object in the signature breaks the boundary", "Nothing; only repository interfaces may not reference HTTP types", "The service must not know about HTTP - it should take plain business parameters from the controller so it stays testable outside a web app"], a: 3, e: "The service layer is defined as business rules plus the transaction boundary, explicitly with no knowledge of HTTP or persistence details, and HttpServletRequest is an HTTP type that belongs in the controller. A service does reach for persistence through repositories, the unit of work is one public method rather than one class, and the restriction is not limited to repositories." },
    { d: "Spring_Boot_Layers", n: "jpa", q: "You change a field on a managed entity inside a transaction and never call save(). Where does the UPDATE come from?", opts: ["Dirty checking - Hibernate compares the entity against its snapshot in the persistence context and flushes the change automatically at commit", "@Transactional makes the repository proxy save every entity at the end of the method", "Spring Data JPA schedules a background flush every few seconds", "It does not; without save() the change is lost, because JPA only tracks ids"], a: 0, e: "The diagram states that dirty checking flushes your changes for you at commit, because Hibernate keeps a snapshot of each managed entity in the persistence context and diffs it when flushing. The transactional proxy does not walk your objects looking for changes, no background flush exists, and losing the update without save() would make managed entities useless." },
    { d: "Spring_Boot_Layers", n: "security", q: "A public /health endpoint must skip authentication, but your filter is registered for /*. Where does the diagram say the exclusion belongs?", opts: ["In the controller, because filters cannot inspect the request URL", "Inside the chain, through an ignore or ordering rule in your security configuration - filters run before any controller exists and apply to every request", "On the controller method with @SkipFilter, which the DispatcherServlet honours", "On a second DispatcherServlet that bypasses the filter mapping"], a: 1, e: "The chain wraps every request in front of the DispatcherServlet, so exclusions have to be expressed within that chain - ignore rules, security configuration or filter ordering - because no controller has been selected yet when filters run. Filters can absolutely read the URL, @SkipFilter does not exist, and a second dispatcher would still sit behind the same servlet filter mapping." },
    { d: "Spring_Boot_Layers", n: "service", q: "One @Service method now places an order, reserves stock, charges a card and sends an email, and it has grown past 300 lines. Which criticism matches the diagram?", opts: ["It is fine as long as the class is annotated @Service, because the diagram only constrains controllers", "The only problem is that the method is public; making it private fixes the transaction boundary", "It violates 'one public method, one transaction, one job' - one all-or-nothing unit should not span a payment gateway call and a notification", "It should move into the repository layer, where long database workflows belong"], a: 2, e: "The diagram's rule is one public method, one transaction, one job, and a payment call plus an email inside a single transactional method holds a database transaction open across network calls so rollback becomes meaningless. Length alone is not the issue, @Service grants no exemption, and making the method private would only stop the advice from applying at all." },
    { d: "Spring_Boot_Layers", n: "db", q: "Everything passes against the H2 database your tests use, then fails in production on Postgres. Which statement from the diagram explains it?", opts: ["H2 is a relational database and Postgres is not, so the entity mappings must be rewritten", "Your tests never hit a real database, so no SQL ever ran in them", "Production runs a migration-generated schema while tests run an entity-generated schema, and those two are always identical anyway", "The dialect differs between environments - H2 is not Postgres - so what H2 tolerates is not portable"], a: 3, e: "The diagram is blunt that the dialect differs between environments, which is why SQL, sequences and type behaviour that H2 accepts can still fail on Postgres - the standard fix is testing against the real engine with Testcontainers. Both are relational databases so mappings do not change, the tests did execute SQL against H2, and the claim that two schemas are always identical is exactly the assumption that breaks." },
    { d: "Spring_Boot_Layers", n: "controller", q: "A controller method calls repository.findAll() and then applies a discount rule in Java. Which two rules does it break?", opts: ["Stay thin - no repository calls and no business rules in the controller; both belong behind the service layer that owns the use case", "None, as long as the response is a DTO - the diagram only forbids returning entities", "Only the repository rule, because a discount rule is presentation logic and belongs here", "Only the business-rule rule, because calling findAll() directly is the fastest path"], a: 0, e: "The controller layer is explicitly thin: DTOs in and out, no repository calls and no business rules, with validation and response shaping as its only jobs. Returning a DTO does not license the other two violations, and neither a discount rule nor a findAll() belongs in presentation code - both are the service layer's use case." },
    { d: "Spring_Boot_Layers", n: "jpa", q: "A service hands an entity with a lazy collection to the controller, and serialization fails after the transaction has closed. What does the jpa node say is really going on?", opts: ["Hibernate forgot to flush, so no SELECT was issued for the collection", "The persistence context is closed - lazy loading can bite you exactly when an object outlives its session", "The collection was eagerly loaded, and Jackson cannot serialize the proxy type", "Dirty checking rolled the collection back because the transaction ended before serialization"], a: 1, e: "The diagram attributes this to the persistence context: lazy loading only works while that context is open, and a detached entity handed across the transaction boundary has nowhere to load from. A missing flush would leave stale rows rather than a detached collection, an eagerly loaded collection would serialize or fail differently, and dirty checking concerns updates rather than loading." },
    { d: "Spring_Boot_Request_Path", n: "filter", q: "Where does a servlet Filter run relative to the DispatcherServlet, and can a Filter rewrite a request before Spring MVC sees it?", opts: ["Before the DispatcherServlet, in the servlet container's chain - it can wrap the request and change the URI before any handler mapping runs", "After the DispatcherServlet, just before the response is written", "Inside handler execution, between the argument resolvers and the controller method", "Only after the response has been committed"], a: 0, e: "Filters are the outermost layer: the container builds the filter chain, the DispatcherServlet sits at the end of it, and only then does Spring MVC map and invoke a handler. That ordering is why filters can read or wrap the HttpServletRequest and add MDC or security context, and why a HandlerInterceptor - which runs inside the DispatcherServlet - is too late to rewrite the request path." },
    { d: "Spring_Boot_Request_Path", n: "dispatcher", q: "Which component turns an HttpServletRequest into a call to your annotated controller method?", opts: ["DispatcherServlet, via HandlerMapping, HandlerAdapter and argument resolvers", "The embedded Tomcat connector", "A servlet Filter, by reflection", "The @RestController itself, via a proxy"], a: 0, e: "DispatcherServlet is the front controller: HandlerMapping finds the handler, HandlerAdapter invokes it, HandlerMethodArgumentResolver supplies the parameters, and return value handlers serialize the result. The connector only reads bytes off the socket, a Filter runs earlier in the chain, and the controller class is just the handler that gets found." },
    { d: "Spring_Boot_Request_Path", n: "service", q: "A GET /orders request arrives. Put the hops in order, naming what happens at the transaction boundary.", opts: ["browser -> servlet filters -> DispatcherServlet -> controller -> service (@Transactional proxy opens tx) -> repository -> database; the transaction commits when the transactional service method returns", "browser -> controller -> service -> database -> filters -> DispatcherServlet", "browser -> DispatcherServlet -> filters -> controller -> service -> database (tx commits at the database write)", "browser -> repository -> database -> service -> controller -> DispatcherServlet (reverse order)"], a: 0, e: "Filters wrap the DispatcherServlet, which finds the controller; the transactional service method opens the transaction, the repository uses it, and the commit happens as the proxied method returns - before the controller writes the response. A commit at the database write would break atomicity, and request handling never flows bottom-up." },
    { d: "Spring_Boot_Request_Path", n: "db", q: "Why does the transaction commit before the HTTP response is written, and what breaks if you rely on writing the response inside the transaction?", opts: ["The transaction ends when the transactional method returns, so a slow or failing response write happens after commit - a broken response does not roll back the data", "The commit is triggered by the connection returning to the pool, which happens after the response", "The response is always flushed before the service method returns", "The transaction ends when the database detects a closed socket"], a: 0, e: "The @Transactional proxy commits on the way out of the method, and only then does the controller serialize and write the response. Holding the transaction open across serialization wastes a pooled connection and still cannot give you a two-phase commit between the database and the socket. The options claiming the pool or the socket drives commit are not how transaction managers work." },
    { d: "Spring_Boot_Request_Path", n: "browser", q: "A user clicks a link to https://shop.example.com/orders on a cold connection. Which sequence must complete before any byte of the HTTP request can reach your Spring Boot app?", opts: ["DNS resolution, TCP three-way handshake, TLS handshake, then the HTTP request line", "TLS handshake, DNS resolution, HTTP request, then the TCP handshake", "TCP handshake, HTTP request, TLS handshake, then DNS resolution", "ARP lookup, DNS resolution, HTTP request, then TLS handshake"], a: 0, e: "The name must resolve, the connection must be established, the channel must be encrypted, and only then can the request line be sent, so your application sees nothing until that chain finishes. Every other ordering puts TLS or the HTTP payload before the transport that carries it, and ARP is local network address resolution that never appears in this path." },
    { d: "Spring_Boot_Request_Path", n: "filter", q: "Two Filter beans are registered for /*, one annotated @Order(1) and one @Order(2). For a single inbound request, which statement is true?", opts: ["Both run in whatever order the application context happened to register them, because @Order is ignored for servlet Filters", "@Order(1) runs first on the way in, and because doFilter nests the calls, @Order(2) finishes first on the way out", "@Order(2) runs first because larger order values get higher precedence", "Only one of them runs, since the first matching Filter consumes the chain"], a: 1, e: "Spring sorts Filter beans by @Order ascending before wrapping them around the chain, and each doFilter call nests the next one, so unwinding happens in reverse. Order values do not invert, bean-name ordering is only a fallback when no @Order is present, and every matching Filter in the chain runs." },
    { d: "Spring_Boot_Request_Path", n: "filter", q: "A Filter calls request.getInputStream() to inspect the payload and then passes the request along the chain. What does your controller method receive?", opts: ["Spring Boot buffers every request body in memory for the whole chain, so any number of filters can read it safely", "The container throws IllegalStateException the moment a Filter calls getInputStream, so Filters may only read headers", "An empty body, unless the Filter wrapped the request in something that caches the bytes before forwarding it", "The body again, but only if the Filter is registered before CharacterEncodingFilter"], a: 2, e: "The body is a one-shot stream, so once the Filter consumes it the downstream reader finds nothing unless the Filter forwards a wrapping request such as ContentCachingRequestWrapper. Boot does not buffer bodies for you, containers do not forbid reading the stream, and duplicate reads are rejected regardless of Filter ordering." },
    { d: "Spring_Boot_Request_Path", n: "dispatcher", q: "A GET /orders request reaches the DispatcherServlet. Which component actually resolves it to your annotated controller method?", opts: ["BeanNameUrlHandlerMapping, which matches bean names such as /orders against the URL", "SimpleUrlHandlerMapping, which reads a mapping table declared in application.properties", "The container's default servlet, which forwards unmatched paths into Spring MVC", "RequestMappingHandlerMapping, which indexes @GetMapping and @RequestMapping annotations at startup"], a: 3, e: "Spring MVC builds a RequestMappingHandlerMapping that indexes every annotation-based mapping into a URL-to-handler table before the first request arrives. The legacy mapping beans do not read annotations, and the container's default servlet never sees paths that are mapped into the DispatcherServlet." },
    { d: "Spring_Boot_Request_Path", n: "controller", q: "A controller method declares a parameter @RequestParam String id, but the incoming query string omits id. What happens next?", opts: ["MissingServletRequestParameterException is raised during argument resolution and the request ends as a 400, before your method body runs", "The method is invoked with id = null and a NullPointerException is thrown later in the service", "The parameter is bound to an empty string, because Spring coerces missing values to an empty value", "The container answers 405 Method Not Allowed because the query string is incomplete"], a: 0, e: "Argument resolution runs after the handler is mapped but before the method body, so the missing required parameter short-circuits into a 400 response. There is no null binding for a required parameter, no empty-string coercion, and a bad query string does not change the fact that the path still matches the handler." },
    { d: "Spring_Boot_Request_Path", n: "service", q: "A controller returns a DTO from a @PostMapping. At which point on the request path is that DTO converted into the JSON response body?", opts: ["Inside the service method, immediately after the DTO is constructed", "Back in the DispatcherServlet, where an HttpMessageConverter serializes the return value after the controller method returns and before the response is committed", "In the servlet access log valve, after the response stream closes", "In a Filter that runs ahead of the controller and pre-serializes the body"], a: 1, e: "The controller hands the object back to the DispatcherServlet, which picks a message converter such as Jackson to write the body while the response is still open. Neither the service layer nor any Filter serializes JSON, and the transaction commit point has nothing to do with when bytes are written." },
    { d: "Spring_Boot_Request_Path", n: "repository", q: "A @Transactional service method calls a repository method annotated @Transactional(readOnly = true) with default propagation. Which configuration wins?", opts: ["The repository's readOnly flag, because annotations closer to the database are more specific", "A fresh read-only transaction is opened for the repository call, and the service transaction resumes afterwards", "The service transaction, because REQUIRED joins it, so no new transaction exists for the readOnly flag to configure", "Both apply, as Spring creates a savepoint and switches the connection into read-only mode"], a: 2, e: "REQUIRED joins the transaction already open on the service, so the repository annotation never starts a transaction of its own and its readOnly setting has nothing to apply to. Annotations are not resolved by proximity to the database, no savepoint is created, and the connection mode is not changed for a joined transaction." },
    { d: "Spring_Boot_Request_Path", n: "db", q: "You disable open-in-view and return a JPA entity with an uninitialized lazy collection straight from a controller. What error do you get and why?", opts: ["A Jackson NullPointerException, because the collection field resolves to null", "No error at all, because Hibernate silently substitutes an empty collection", "Spring reopens the persistence session automatically when the serializer touches the field", "LazyInitializationException, because the persistence session closed when the transaction ended and the proxy can no longer load"], a: 3, e: "The session lives and dies with the transaction, so by the time serialization touches the proxy there is nothing left to run the follow-up select. Jackson would not NPE on an empty collection, Hibernate does not silently swap in an empty list for an uninitialized proxy, and Spring never resurrects a closed session." },
    { d: "Spring_Boot_Request_Path", n: "dispatcher", q: "A request arrives for /does-not-exist, matching neither a controller nor any static file. What is the actual path the request takes in a default Boot 3.3 app?", opts: ["Spring MVC raises an exception such as NoHandlerFoundException or NoResourceFoundException, the request is dispatched to /error, and the BasicErrorController renders the 404 body", "The DispatcherServlet writes an empty 200 response because no handler matched", "Tomcat rejects the request while parsing the URL, so it never reaches Spring at all", "The container serves its own 404 page and the Spring error handling is skipped entirely"], a: 0, e: "An unmatched path throws inside Spring MVC, and Boot's error handling forwards that to the /error dispatch where BasicErrorController produces the JSON 404. The DispatcherServlet never emits a bare 200 for an unmatched path, Tomcat still invokes it for a well-formed URL, and your advice chain is part of that dispatch rather than bypassed." },
    { d: "Spring_Boot_Request_Path", n: "filter", q: "You need a Filter to log the response status and body. What is the correct technique?", opts: ["Call chain.doFilter twice, so the response passes through your Filter on both the inbound and outbound legs", "Write the status, headers and body into a response wrapper inside the Filter, then copy the captured content to the real response after chain.doFilter returns", "Register the Filter with isAsyncSupported set to false so the container flushes before your code exits", "Annotate the Filter with @ResponseStatus so Spring MVC writes the response for you"], a: 1, e: "Code after chain.doFilter runs on the way out, but by then the real response has already been streamed, so you have to capture it in a wrapper and copy it over afterwards. Calling doFilter twice duplicates the downstream work, async flags cannot delay the flush, and @ResponseStatus has no meaning on a Filter." },
    { d: "Spring_Boot_Request_Path", n: "controller", q: "A client posts a body with Content-Type: application/json, but the payload is malformed JSON. Which exception surfaces and what status results?", opts: ["The controller runs with a null parameter and throws a NullPointerException, producing a 500", "The message converter returns 415 Unsupported Media Type, because the body could not be understood", "HttpMessageNotReadableException, raised while the converter parses the body, which is mapped to a 400 response", "MethodArgumentTypeMismatchException, which is always handled as a 500 by default"], a: 2, e: "JSON parsing happens during argument resolution, so a malformed payload stops before the method body and maps to 400. A null binding would only happen for an absent and optional body, 415 is about an unsupported Content-Type rather than a broken payload, and type mismatch problems are a separate case that also maps to 400." },
    { d: "Spring_Boot_AOP_Proxy", n: "proxy", q: "In Spring Boot, what decides JDK dynamic proxy versus CGLIB for a proxied bean, and what breaks a CGLIB proxy?", opts: ["Boot defaults proxyTargetClass=true, so CGLIB subclasses the class; final classes, final methods, and private methods cannot be advised", "The JDK proxy is used whenever the class implements any interface; CGLIB cannot be used with proxies", "Both are chosen at random and it does not matter", "CGLIB is used only for classes with no methods"], a: 0, e: "With proxyTargetClass=true the container subclasses the target, which requires a non-final class and non-final methods that advice can override. Interface-based JDK proxies are used when you turn that off (and are what Spring Data repositories use), and they require the call to go through the interface. Private methods are invisible to both - a CGLIB proxy is a subclass, not an instrumented class." },
    { d: "Spring_Boot_AOP_Proxy", n: "caller", q: "What must be true about the caller for @Transactional advice on a service method to execute at all?", opts: ["The caller must invoke the method through the proxy - that is, an injected bean reference or self-injection, not a direct new or a this call", "The method must be public and the class must be public", "The caller must be in a different package", "The class must implement an interface"], a: 0, e: "The advice lives in the proxy; a direct new Service() or a this.otherMethod() call never touches the proxy, so no advice runs. Public plus non-final is necessary for the proxy to be able to override the method, and the interface is only relevant if you use JDK proxies - but none of those make the call proxied." },
    { d: "Spring_Boot_AntiPatterns", n: "selfinv", q: "methodA() calls this.methodB(), and only methodB() is annotated @Transactional. What happens at runtime?", opts: ["No transaction is started: the self-invocation bypasses the proxy, and the database calls run in auto-commit mode", "A transaction starts at methodA because the proxy is already in the call stack", "A transaction starts at methodB because annotations are evaluated on the target class", "A TransactionRequiredException is thrown"], a: 0, e: "This is the self-invocation anti-pattern: the proxy only intercepts calls that come from outside, so the work still happens but with no surrounding transaction, and it auto-commits statement by statement. Fix it by moving the annotated method to another bean, self-injecting the proxy, or restructuring so the annotated method is the one invoked externally. The failure is silent, which is what makes it expensive." },
    { d: "Spring_Boot_AOP_Proxy", n: "tx", q: "You add @Transactional to a private method. What is the effect?", opts: ["None - a private method cannot be overridden by a proxy, so no transaction is started", "A transaction starts, because annotations are read from the target class", "A transaction starts only when the class implements an interface", "The application fails to start because the annotation is illegal on a private method"], a: 0, e: "Spring's AOP advice is applied through method interception, and neither a CGLIB subclass nor a JDK proxy can intercept a private call that never leaves the object. Startup is fine and the annotation is legal; it is simply inert. The visible symptom is data being written with no transaction - partial commits and no rollback." },
    { d: "Spring_Boot_AOP_Proxy", n: "service", q: "A service class is declared final and every method is final. @Transactional is present and the app starts. What is the likely runtime symptom?", opts: ["No transactions at all: CGLIB cannot subclass a final class, so the proxy falls back to nothing and writes auto-commit", "The application fails to start with a clear error about final classes", "Transactions work, because Hibernate manages its own connections", "Transactions work for reads but silently fail for writes"], a: 0, e: "Making the class final quietly disables the proxy rather than failing loudly, so every method runs with no transaction - the most expensive kind of bug, because it only shows up under concurrent failure. A clear startup error is what you would get from a bad property or a duplicate bean, not from final. Caching and @Async have the same failure mode." },
    { d: "Spring_Boot_AOP_Proxy", n: "repo", q: "Does @Transactional on a Spring Data repository method work, and how does it interact with a transactional service method?", opts: ["Yes - the repository is proxied too, and a default REQUIRED call just joins the service's existing transaction", "No - only service beans can be transactional", "Yes, but the repository always opens a second, independent transaction", "Yes, but only for read methods, never for save or delete"], a: 0, e: "Spring Data repositories are proxies, and the SimpleJpaRepository base implementation is transactional, so annotating a custom repository method works and REQUIRED joins whatever transaction is already active. Opening a second transaction would be REQUIRES_NEW, and reads are transactional too - the absence of transactions on reads is exactly what causes lazy-loading failures outside a request." },
    { d: "Spring_Boot_AOP_Proxy", n: "proxy", q: "A service is proxied with CGLIB because proxy-target-class is left at its Boot 3 default, and the field that injects it is declared as an interface. What object ends up in that field?", opts: ["The CGLIB proxy instance, since it subclasses the target and therefore also implements the interface", "The raw target bean, because Spring unwraps to the target whenever an interface is requested", "A JDK proxy for that interface, because interface-typed injection points force interface-based proxies", "Nothing, because the context fails at startup with a NoUniqueBeanDefinitionException"], a: 0, e: "A CGLIB proxy is a generated subclass of the target, so it is assignable to any interface the target implements and is injected as-is. Spring does not unwrap to the target at injection time and does not swap proxy strategies just because the field type is an interface." },
    { d: "Spring_Boot_AOP_Proxy", n: "proxy", q: "A method annotated @Transactional calls this.otherMethod() where otherMethod is annotated @Async. What do you observe at runtime?", opts: ["A separate thread runs otherMethod, but its transaction is suspended and never resumed", "otherMethod executes synchronously in the caller's thread, because the @Async advice never sees the call", "Spring throws a self-invocation exception at startup because two proxy annotations are combined", "otherMethod runs twice, once inline and once on the executor"], a: 1, e: "The call leaves through this, so it bypasses the proxy and the async wrapper, and the work happens inline on the transaction's thread. No exception is raised at startup, nothing is duplicated, and no thread handoff or suspension occurs because the async advice was never entered." },
    { d: "Spring_Boot_AOP_Proxy", n: "proxy", q: "Two beans inject the same singleton service that carries @Transactional. What do the two injected references point to?", opts: ["A new proxy is created for every injection point, because proxies are not singletons", "The first injection gets the proxy and every later injection gets the raw target", "One proxy per bean definition, so both references receive that same singleton proxy with the target held inside it", "A proxy is created on first use for each thread and cached per thread"], a: 2, e: "The proxy is the singleton bean: Spring creates it once per bean definition and hands the identical instance to every injection point, with the target held inside. Proxies are not built per injection point, per thread, or per request, and later injections never receive the unwrapped target." },
    { d: "Spring_Boot_AOP_Proxy", n: "tx", q: "You annotate a service method with plain @Transactional and call it from outside the bean. What propagation applies?", opts: ["MANDATORY, which refuses to open a transaction and fails if the caller has none", "REQUIRES_NEW, which suspends the caller's transaction and always opens its own", "NEVER, which requires the caller to have no transaction and throws if one exists", "REQUIRED, which joins the caller's transaction if one exists and starts a new one otherwise"], a: 3, e: "REQUIRED is the default, which is why nested service calls share a single commit instead of opening separate transactions. The other three options describe explicit settings that must be written on the annotation, and none of them is the default behaviour." },
    { d: "Spring_Boot_AOP_Proxy", n: "tx", q: "Inside a @Transactional method you catch a RuntimeException thrown by your own code and log it, with no other changes. What happens to the data written so far?", opts: ["The transaction is still marked rollback-only, so the commit fails with UnexpectedRollbackException", "The exception never crosses the proxy boundary, so no rollback is marked and the work commits", "Spring detects the exception through the call stack and rolls back anyway", "The transaction rolls back and a replacement transaction starts for the rest of the method"], a: 1, e: "Rollback is decided at the proxy boundary, where the interceptor marks rollback only if the exception propagates out of the transactional method. A caught exception never gets that far, so nothing marks rollback-only, no UnexpectedRollbackException appears, and no transaction is restarted." },
    { d: "Spring_Boot_AOP_Proxy", n: "tx", q: "Which exceptions trigger an automatic rollback of a transaction with default settings?", opts: ["Every Throwable, since Spring marks rollback for anything thrown out of the method", "Checked exceptions only, following the classic EJB convention", "RuntimeException and Error only; checked exceptions commit unless rollbackFor says otherwise", "Only exceptions you explicitly annotate with a rollback marker in production code"], a: 3, e: "Spring's default rule rolls back on unchecked exceptions and Error, which is the behaviour most teams discover the hard way with checked business exceptions. It is not the reverse EJB rule, it is not every Throwable, and there is no production rollback annotation because that name belongs to Spring's test support." },
    { d: "Spring_Boot_AOP_Proxy", n: "tx", q: "A method declares @Transactional(timeout = 5) with default propagation and is called from an outer transactional method. When does the 5 second timeout take effect?", opts: ["The JDBC driver cancels any query on this connection after 5 seconds, regardless of which method started the transaction", "Spring polls the connection every 5 seconds and closes it, so long statements are simply disconnected", "It applies only to REQUIRES_NEW transactions and is ignored on the default propagation", "Only when this method is the one that actually begins the transaction; when it joins an outer transaction, that outer transaction's timeout governs"], a: 3, e: "Transaction attributes are applied at the moment a transaction is really started, so a joined transaction keeps the settings of its owner. The driver does not independently enforce your annotation, Spring does not kill statements on a timer, and the setting is not restricted to REQUIRES_NEW." },
    { d: "Spring_Boot_AOP_Proxy", n: "service", q: "Spring is starting up and you have a large component-scanned service with no @Transactional and no other aspect. What does the container create for it?", opts: ["A proxy, because the bean is eligible for advice as soon as it is component-scanned", "A proxy only if the class implements at least one interface", "A raw instance, because a bean with no advice-eligible method never needs a proxy", "A proxy for every class in a component-scanned package, whether annotated or not"], a: 2, e: "Spring creates a proxy only when at least one method matches an advisor, so a bean with nothing to advise is registered as the plain target instance. Proxies are not built for every scanned bean, an interface is irrelevant for CGLIB-based proxying, and scanning alone never triggers proxy creation." },
    { d: "Spring_Boot_AOP_Proxy", n: "caller", q: "A service is proxied with a JDK dynamic proxy because it implements an interface. You call applicationContext.getBean(\"orderService\") and the method you want exists only on the implementation class. What do you get?", opts: ["The target instance, because getBean always unwraps proxies before returning", "The JDK proxy, which implements only the interface, so a method declared solely on the implementation class is unreachable through it", "A CGLIB proxy, because Boot re-wraps JDK proxies whenever a concrete class is requested", "BeanNotOfRequiredTypeException on every call, because proxies cannot be retrieved by bean name"], a: 1, e: "With a JDK proxy the object in the context implements only the proxy interfaces, so calling back to an implementation-only method is not possible through that reference. getBean does not unwrap, it does not upgrade the proxy type, and proxies are perfectly retrievable by bean name." },
    { d: "Spring_Boot_AOP_Proxy", n: "repo", q: "You call a Spring Data repository method from a plain class that has no transaction open at all. What makes the call work?", opts: ["TransactionRequiredException is thrown, because repository methods never open a transaction on their own", "The work is buffered in memory and committed by a background flusher", "Spring Data's SimpleJpaRepository is itself annotated @Transactional, so the call starts its own default transaction", "It runs against a container-wide shared EntityManager that is never closed"], a: 2, e: "The base repository implementation carries its own @Transactional, so with no surrounding transaction it opens one per call using default REQUIRED behaviour. Writes would fail with TransactionRequiredException only if nothing opened a transaction at all, and there is no buffered write queue or immortal shared EntityManager." },
    { d: "Spring_Boot_AutoConfiguration", n: "classpath", q: "What is the first input that decides which auto-configurations are even candidates?", opts: ["Your classpath - only the auto-configurations named in the imports files of the jars you actually depend on are considered", "Your application.properties file", "The @SpringBootApplication scan of your own packages", "The order of your @Component classes"], a: 0, e: "Auto-configuration is classpath-driven: start.spring.io-generated starters pull in auto-configurations, and those back off again when their @ConditionalOnClass or @ConditionalOnProperty checks fail. Properties only influence conditions after a class is a candidate, and your own packages are scanned by the component scan, which is a different mechanism entirely." },
    { d: "Spring_Boot_AutoConfiguration", n: "imports", q: "Boot 3 loads auto-configuration from a file under META-INF/spring. Why does this matter when you move a project from Boot 2.7?", opts: ["Auto-configuration entries moved from spring.factories to the .imports file, so a hand-rolled spring.factories list is silently ignored in Boot 3", "The .imports file is only used for test slices", "The file must be named spring-autoconfigure-metadata.properties", "Nothing changed; the file is just a convention for tooling"], a: 0, e: "If you wrote your own auto-configuration for Boot 2.7 and registered it in spring.factories, Boot 3 will not see it - the entry has to be in META-INF/spring/org.springframework.boot.autoconfigure.AutoConfiguration.imports. Other mechanism files still exist: spring.factories still carries EnvironmentPostProcessor and ApplicationListener registrations, and the metadata file is for tooling, not loading." },
    { d: "Spring_Boot_AutoConfiguration", n: "ordering", q: "Two auto-configurations both define a bean that another one @ConditionalOnBean-depends on. Which annotations control the evaluation order?", opts: ["@AutoConfigureBefore / @AutoConfigureAfter (or @AutoConfigureOrder to sort a list) - conditions are evaluated while configuration classes are parsed", "@Order on the @Bean methods", "The alphabetical order of the class names", "@DependsOn on the @Bean methods"], a: 0, e: "Conditions are evaluated during configuration class parsing, so ordering is expressed with the @AutoConfigureBefore/@AutoConfigureAfter family; @AutoConfigureOrder sorts candidates that implement the order interface. @Order is for bean method/instance ordering within a context and does not sequence condition evaluation, and alphabetical order is not a guarantee even though it often looks like one." },
    { d: "Spring_Boot_AutoConfiguration", n: "beancond", q: "What is the difference between @ConditionalOnMissingBean and @ConditionalOnBean?", opts: ["OnMissingBean backs off when the application already defines the bean; OnBean requires the bean to already be defined, so it is order-sensitive and risky on user beans", "They are aliases with different default attribute values", "OnMissingBean only works on @Configuration classes, OnBean only on @Bean methods", "OnBean is the Boot 3 replacement for OnMissingBean"], a: 0, e: "The pair is deliberate: an auto-configuration uses OnMissingBean so yours wins, and uses OnBean only for its own internal beans, never for beans defined by the application, because a user bean may be registered after your condition is evaluated. Putting OnBean on a user bean is the classic ordering bug - it works in one test and fails in another depending on import order." },
    { d: "Spring_Boot_AutoConfiguration", n: "backoff", q: "You want your own DataSource to win over Boot's. What is the idiomatic Boot 3 way?", opts: ["Define a DataSource bean yourself - DataSourceAutoConfiguration's @ConditionalOnMissingBean makes it back off - and bind spring.datasource.* into it with @ConfigurationProperties", "Set spring.autoconfigure.exclude=DataSourceAutoConfiguration and define the bean yourself", "Override the static createDataSource method by declaring a bean with the same name in a different package", "Add @Primary to your repository"], a: 0, e: "The back-off condition is the designed extension point: your bean is defined, the auto-config steps aside, and you still get relaxed binding and validation by binding the same properties. Excluding works but throws away the auto-configuration's helpful failure messages and defaulting, same-name overriding is an override conflict, and @Primary on a repository has nothing to do with DataSource selection." },
    { d: "Spring_Boot_AutoConfiguration", n: "propcond", q: "What does @ConditionalOnProperty(name = \"app.messaging.enabled\", havingValue = \"true\") do when the property is missing entirely?", opts: ["The bean is not registered, because a missing property is treated as not matching havingValue", "The bean is registered with the property defaulting to true", "Startup fails with a placeholder resolution error", "The bean is registered but its @Value fields stay null"], a: 0, e: "The condition compares the resolved value; absent means no match, so matchIfMissing=false (the default) skips the bean. That is why production configs so often fail to start after a rename, and why matchIfMissing exists for deliberate defaults. Missing properties never throw at condition time - placeholders only fail later, when the bean is being created." },
    { d: "Spring_Boot_AutoConfiguration", n: "webcond", q: "One auto-configuration must apply to servlet stacks only, and another to reactive stacks only. How is that expressed?", opts: ["@ConditionalOnWebApplication(type = Type.SERVLET) and @ConditionalOnWebApplication(type = Type.REACTIVE)", "@Profile(\"servlet\") and @Profile(\"reactive\")", "@ConditionalOnProperty(name = \"spring.main.web-application-type\")", "@ConditionalOnBean(DispatcherServlet.class)"], a: 0, e: "Web application type is a first-class condition, and it is the reliable discriminator: Type.ANY matches both, and a missing DispatcherServlet bean condition is ambiguous because bean conditions are order-sensitive. Profiles are an environment concern, not a technology discriminator, and switching on a property duplicates what the condition already knows." },
    { d: "Spring_Boot_AutoConfiguration", n: "register", q: "How should a Boot 3 auto-configuration class be written, and why?", opts: ["Annotate it @AutoConfiguration (which implies proxyBeanMethods = false) and declare @Bean methods with conditions", "Annotate it @Configuration(proxyBeanMethods = true) so the conditions can call each other", "Annotate it @Component so the component scan picks it up", "Annotate it @Configuration and put it in the same package as your application"], a: 0, e: "@AutoConfiguration is the explicit marker for a candidate; proxyBeanMethods = false means @Bean methods call each other directly instead of through the enhanced configuration class, which is both faster and avoids CGLIB final-method limits. Component scanning is not how auto-configurations are found - they are loaded from the imports file - and package placement is irrelevant." },
    { d: "Spring_Boot_AutoConfiguration", n: "candidates", q: "For an auto-configuration listed in the imports file, which of these is NOT a requirement for it to take effect?", opts: ["That no other auto-configuration has already registered a bean of the same type", "That the auto-configuration class is present on the classpath", "That the class is listed in META-INF/spring/org.springframework.boot.autoconfigure.AutoConfiguration.imports", "That every @Conditional on the class evaluates to true"], a: 0, e: "Being listed, being on the classpath and passing the conditions are what make it run; a pre-existing bean of the same type is decided later by @ConditionalOnMissingBean at evaluation time and never removes the class from the candidate set. That check may cause an individual bean method to back off, but it is not a requirement for the auto-configuration itself." },
    { d: "Spring_Boot_AutoConfiguration", n: "candidates", q: "You add a third-party starter and one of its auto-configurations clearly did not run. What is the fastest way to find the recorded reason?", opts: ["Start with --verbose so the auto-configuration trace is printed by the logger", "Enable the debug report (--debug or debug=true) and read the condition evaluation report, which lists every auto-configuration and why it was excluded or matched", "Call the actuator /beans endpoint, which always includes exclusion reasons for auto-configurations", "Open META-INF/spring.factories, which records the outcome of the last startup"], a: 1, e: "The condition evaluation report dumps each condition's outcome, which is exactly where a missing bean or failed @Conditional shows up. Verbose logging does not produce that report, /beans shows bean definitions rather than condition outcomes, and files on disk are never rewritten with startup results." },
    { d: "Spring_Boot_AutoConfiguration", n: "beancond", q: "You put @ConditionalOnBean on a bean method inside a component-scanned @Configuration class. Why is that risky?", opts: ["Because bean definitions may not exist yet at that point, the condition can silently evaluate to false and leave you with an application that starts but is missing beans", "Because the annotation is only processed by the auto-configuration import selector and is completely ignored elsewhere", "Because it forces a circular dependency between the configuration classes", "Because it is deprecated outside auto-configurations and fails the build with a warning"], a: 0, e: "Bean-definition registration order is unpredictable for scanned classes, so @ConditionalOnBean can quietly evaluate to false with no error at startup. The annotation is still processed outside auto-configurations, it does not inherently create a cycle, and it is not deprecated or build-failing." },
    { d: "Spring_Boot_AutoConfiguration", n: "backoff", q: "You want your own bean definition to beat Boot's auto-configured one. Which of these will NOT make Boot back off?", opts: ["Your @Bean method lives in a component-scanned @Configuration, which is evaluated before auto-configurations run", "spring.autoconfigure.exclude names the auto-configuration that would define the competing bean", "A bean definition of the same type is already visible when @ConditionalOnMissingBean is evaluated", "A higher @Order value on your configuration class, which does not affect bean definition registration at all"], a: 3, e: "@Order controls advice and configuration class precedence, not whether a bean definition exists when a condition runs, so it does nothing to make Boot yield. The other three all remove or preempt the competing definition, which is exactly what @ConditionalOnMissingBean checks for." },
    { d: "Spring_Boot_AutoConfiguration", n: "propcond", q: "A bean must load only when app.feature.enabled is explicitly set to false; a missing property must NOT load it. Which annotation do you write?", opts: ["@ConditionalOnProperty(name = \"app.feature.enabled\", havingValue = \"false\", matchIfMissing = true), because a missing property also counts as false", "@ConditionalOnProperty(name = \"app.feature.enabled\", havingValue = \"false\"), because havingValue is an exact string match and matchIfMissing defaults to false", "@ConditionalOnProperty(name = \"app.feature.enabled\"), because the mere presence of the key is enough to enable the bean", "@ConditionalOnProperty(name = \"app.feature.enabled\", matchIfMissing = true), because a missing property counts as enabled"], a: 3, e: "The condition compares the resolved value against havingValue as a literal string, and with matchIfMissing left at its default of false an absent property does not satisfy it. matchIfMissing = true would load the bean precisely when the property is missing, and dropping havingValue makes any non-false value match instead of only an explicit false." },
    { d: "Spring_Boot_AutoConfiguration", n: "webcond", q: "A project accidentally has both spring-boot-starter-web and spring-boot-starter-webflux on the classpath. What does Boot do?", opts: ["Both stacks start and requests are routed between them by URL pattern", "The application fails at startup with a BeanDefinitionOverrideException", "Spring Boot deduces a SERVLET web application, so @ConditionalOnWebApplication(type = SERVLET) auto-configurations apply and the reactive ones back off", "WebFlux wins, because it appears later in the resolved dependency graph"], a: 2, e: "The presence of servlet API classes makes Boot deduce the servlet application type, which selects the MVC auto-configurations and backs off the reactive ones. Nothing routes between two servers at once, no bean override exception is thrown for this, and classpath order plays no part in the decision." },
    { d: "Spring_Boot_AutoConfiguration", n: "classpath", q: "A starter ships an auto-configuration that must not run unless a specific class is on the classpath. Which annotation does the author reach for?", opts: ["@ConditionalOnClass, which evaluates against the type names supplied, tolerating classes that may be absent", "@ConditionalOnBean, which checks whether the bean definition is already registered", "@ConditionalOnProperty, which would be set by the starter's own metadata file", "@ConditionalOnWebApplication, which inspects the servlet or reactive stack"], a: 0, e: "@ConditionalOnClass is the canonical guard for optional dependencies: it passes when the named types are present and fails cleanly when they are not, which is exactly why classpath content is the first filtering step. @ConditionalOnBean looks at bean definitions rather than classes, property conditions have nothing to do with type availability, and web conditions only distinguish servlet from reactive." },
    { d: "Spring_Boot_Config_Properties", n: "relaxed", q: "Which environment variable binds to spring.datasource.hikari.maximum-pool-size = 20?", opts: ["SPRING_DATASOURCE_HIKARI_MAXIMUM_POOL_SIZE=20", "SPRING_DATASOURCE.HIKARI.MAXIMUM-POOL-SIZE=20", "DATASOURCE_HIKARI_MAXIMUM_POOL_SIZE=20", "SPRING_DATASOURCE_HIKARI_MAXIMUMPOOLSIZE=20"], a: 0, e: "Relaxed binding maps the canonical kebab-case property to the uppercase, underscore-separated env form, and both are equivalent. Dots, hyphens and missing separators are not: the env name must be a clean, uppercase, underscore form of the property path. A prefix-less name like DATASOURCE_... binds to a different property entirely and is silently ignored." },
    { d: "Spring_Boot_Config_Properties", n: "cmdline", q: "The same property is set three ways: --server.port=9090 on the command line, SERVER_PORT=8081 in the environment, and server.port=8080 in application.properties. Which value wins?", opts: ["9090 - command line arguments outrank OS environment variables, which outrank application.properties", "8080 - application.properties is the base configuration everything else decorates", "8081 - the environment always wins because it is set outside the jar", "The application fails to start because server.port is defined more than once"], a: 0, e: "Boot's precedence list puts command line arguments above ServletConfig/ServletContext params, above JNDI, above system properties, above OS environment variables, and above both profile-specific and plain application.properties. Defining a property more than once is normal and is exactly how you override packaged defaults. The env var is the right answer only if the command line flag is absent." },
    { d: "Spring_Boot_Config_Properties", n: "profileprops", q: "How do you activate application-dev.properties, and what happens to the plain application.properties values?", opts: ["spring.profiles.active=dev (or SPRING_PROFILES_ACTIVE) overlays it on top of application.properties, overriding only the keys it defines", "application-dev.properties replaces application.properties entirely", "The dev file is loaded only in production", "It is loaded automatically whenever the file exists"], a: 0, e: "Profile-specific documents are an additional, higher-precedence source of properties, merged key by key over the non-profile-specific ones - so keys you do not override keep their default values. Profile selection is never automatic from file existence, and the more specific documents (application-dev.properties outside the jar) beat the less specific ones inside it." },
    { d: "Spring_Boot_Config_Properties", n: "imports", q: "Why use spring.config.import=optional:file:/etc/app/ instead of a classpath: file?", opts: ["Config data is location- and precedence-aware: imports are processed as documents that can be optional, and they let you layer external files or a config server with predictable ordering", "It is a legacy syntax kept only for Spring Cloud", "It disables profile-specific documents", "It converts properties into YAML"], a: 0, e: "The Config Data API treats every source as a document with a defined order, which is what makes external configuration (mounted secrets, a config server) predictable. optional: is the part developers miss - without it a missing file fails startup. The other options invent behaviour the mechanism does not have." },
    { d: "Spring_Boot_Config_Properties", n: "envenv", q: "How does a plain Environment.getProperty(\"app.region\") call resolve a value that lives in a file named APP_REGION, and what is the caveat?", opts: ["SystemEnvironmentPropertySource maps APP_REGION to app.region via relaxed name matching, so it resolves; the caveat is that the same source is not enumerable the same way and the mapping is heuristic", "It never resolves, because System.getenv is not part of the Environment", "It resolves only if the value is also declared in application.properties", "It resolves but the value is always upper-cased"], a: 0, e: "Boot's system environment property source translates relaxed names in both directions, which is why an env-only property can be read. The caveats that matter in practice: this source has no declared property names, so it cannot be listed by the configprops endpoint, and the heuristic translation means a value can be found under a name you did not write down - which is exactly why you prefer typed @ConfigurationProperties for real configuration." },
    { d: "Spring_Boot_Config_Properties", n: "configprops", q: "What is the difference between @ConfigurationPropertiesScan and @EnableConfigurationProperties?", opts: ["@ConfigurationPropertiesScan registers every @ConfigurationProperties class in the scanned packages; @EnableConfigurationProperties registers the specific classes you name", "@ConfigurationPropertiesScan only works in tests", "@EnableConfigurationProperties binds values from the environment while @ConfigurationPropertiesScan binds from a file", "They are interchangeable in all cases"], a: 0, e: "Both register the bean that performs binding and validation, but the scan finds types for you (including support for @ConfigurationProperties records and constructor binding) while @EnableConfigurationProperties is explicit and names the class - useful when the class lives in a library or a different package. The mapping of @ConfigurationPropertiesScan defaults to the annotated class's package, so a class elsewhere needs basePackages." },
    { d: "Spring_Boot_Config_Properties", n: "validation", q: "You add @Validated and @NotNull on a record field in a @ConfigurationProperties class. What happens when the property is absent?", opts: ["Startup fails with a bind/validation exception naming the property, because JSR-380 validation is applied while binding", "The field is left null and the failure appears on first use", "Validation runs only under the dev profile", "A default value of null is registered and validation passes"], a: 0, e: "Validating the configuration at startup is the point of the pattern: fail fast, with a message naming the offending property, instead of discovering a null in production. You have to put @Validated (or jakarta.validation constraints with constructor binding) on the properties class and let the registration happen via @ConfigurationPropertiesScan or @EnableConfigurationProperties; without the validation being applied, null constraints are never evaluated." },
    { d: "Spring_Boot_Config_Properties", n: "envvars", q: "A @ConfigurationProperties record reads app.store.base-url, but the container only exposes environment variables. Which variable name does Spring Boot 3.3 resolve for it?", opts: ["APP_STORE_BASEURL", "APP_STORE_BASE_URL", "APPSTORE_BASEURL", "BASE_URL"], a: 1, e: "Spring Boot maps a property to an environment variable by upper-casing it and turning dots and dashes into underscores, so app.store.base-url resolves to APP_STORE_BASE_URL. APP_STORE_BASEURL and APPSTORE_BASEURL drop the separator that marks the end of base-url, and the property mapper never rejoins those letters, so they stay unbound." },
    { d: "Spring_Boot_Config_Properties", n: "appprops", q: "A @ConfigurationProperties(prefix = \"app.logo\") bean exposes List<String> urls. Which application.properties entry sets the second element to /b.png?", opts: ["app.logo.urls[1]=/b.png", "app.logo.urls[2]=/b.png", "app.logo.urls[0]=/b.png", "app.logo.urls[1].value=/b.png"], a: 0, e: "Indexed binding is zero-based, so [1] addresses the second element while [0] is the first. [2] would target a third element that does not exist yet, and urls[1].value treats the entry as a nested object instead of a plain String value." },
    { d: "Spring_Boot_Config_Properties", n: "cmdline", q: "The jar is started with --spring.profiles.active=dev,metrics while application.properties also sets spring.profiles.active=staging. Which profile-specific files are loaded?", opts: ["application-staging.properties only, because files always beat arguments", "All three are merged, with staging applied last", "application-dev.properties and application-metrics.properties only, because command-line arguments outrank application.properties", "Startup fails, because spring.profiles.active may appear in only one place"], a: 2, e: "Command-line arguments are the highest-priority standard property source, so they replace spring.profiles.active rather than adding to it, activating dev and metrics while staging is dropped. Profile lists are never merged across sources, and a key being defined in two places is ordinary precedence behavior, not a startup error." },
    { d: "Spring_Boot_Config_Properties", n: "defaults", q: "Which of these is NOT one of the four standard locations Spring Boot 3.3 searches for application.properties?", opts: ["file:./config/", "file:./", "classpath:/config/", "classpath:/META-INF/"], a: 3, e: "Spring Boot searches file:./config/, file:./, classpath:/config/ and classpath:/ in that order of descending precedence, so the first three are all standard. META-INF is where auto-configuration metadata lives, but an application.properties placed there is not read as a default location." },
    { d: "Spring_Boot_Config_Properties", n: "validation", q: "A configuration class annotated @ConfigurationProperties and @Validated has @Min(1) on int port, and the file sets app.http.port=0. When does the application stop?", opts: ["On the first request that reads the port", "Never; @Validated only applies to controller parameters", "During startup binding, with a binding failure that names the offending field", "Never; an invalid value silently falls back to the default"], a: 2, e: "Binding and validation happen while the context is created, so the violated constraint aborts startup with a ConfigurationPropertiesBindException that names the field. Deferring the check to the first read or falling back silently would defeat fail-fast startup, and @Validated on a configuration bean triggers JSR-380 checks just as it does on controller parameters." },
    { d: "Spring_Boot_Config_Properties", n: "configprops", q: "In Spring Boot 3.3 a record such as HttpProps(String baseUrl, Duration timeout) binds correctly with no @ConstructorBinding annotation. Why?", opts: ["Records are treated as immutable and are actually bound through generated setters", "Constructor binding is applied automatically for a type with a single constructor, so @ConstructorBinding is only needed to disambiguate several constructors", "@ConstructorBinding is now applied globally by the auto-configuration import file", "It only works when the record is also annotated @Validated"], a: 1, e: "The binder uses constructor binding automatically when the type has a single constructor, which is exactly how records are written. Records have no setters to bind through, and neither @Validated nor any global annotation is what turns constructor binding on." },
    { d: "Spring_Boot_Config_Properties", n: "profileprops", q: "application.properties sets spring.profiles.active=qa, but the deployment passes SPRING_PROFILES_ACTIVE=prod,metrics. What does the application activate?", opts: ["qa, prod and metrics, because profile lists from every source are combined", "qa only, because files are read before environment variables", "Neither; conflicting profile settings abort startup", "prod and metrics only, because the environment variable outranks the file"], a: 3, e: "The environment variable sits higher in the property-source order than application.properties, so it overwrites spring.profiles.active instead of contributing to it, and only prod and metrics load. Profile lists are not combined across sources, and two sources disagreeing on a key is ordinary precedence, not a fatal conflict." },
    { d: "Spring_Boot_Config_Properties", n: "imports", q: "A config entry reads spring.config.import=optional:file:/etc/app/overrides/. What does the optional: prefix guarantee?", opts: ["Startup continues when the directory does not exist, while without it a missing import aborts startup", "The file is read only if no other property source has defined the key", "The file is read lazily on the first getProperty call instead of at startup", "The import failure is logged as a warning, but startup still aborts"], a: 0, e: "The optional: marker tells the config loader to skip a missing resource instead of failing, which is what you want for a machine-specific overrides directory. Without it the import is required and startup aborts, while lazy resolution and priority changes are not what the prefix does, since imports are always resolved during startup." },
    { d: "Spring_Boot_Data_Model", n: "order", q: "Order has a List<OrderItem> and OrderItem has an Order. Which side owns the relationship, and what is the practical consequence?", opts: ["OrderItem owns it (@ManyToOne with @JoinColumn, or mappedBy on the other side); changing the child collection on the wrong side silently does nothing", "Order owns it, because the parent is always the owning side", "Both own it, and the database ends up with two foreign keys", "Neither owns it; JPA infers the owning side from the @Id"], a: 0, e: "The owning side is the side that holds the foreign key, which for a parent/child pair is normally the child. @OneToMany(mappedBy = ...) is a read-only inverse view: add items to the collection without setting the child's order reference and nothing is persisted. The mapping follows the schema, not the object graph." },
    { d: "Spring_Boot_Data_Model", n: "book", q: "What are the JPA defaults for @ManyToOne and @OneToMany, and which one surprises people on a large result set?", opts: ["@ManyToOne defaults to EAGER and @OneToMany to LAZY; the eager many-to-one is what turns one query per parent into a join explosion", "Both default to LAZY in JPA", "Both default to EAGER, so joins are unavoidable", "Both default to LAZY, so the N+1 problem cannot happen"], a: 0, e: "The asymmetry is spec behaviour: the many side is a single reference and is loaded eagerly, the one side is a collection and is proxied. That eager fetch is why 'one query per book' degrades into a huge cartesian join with multiple collections, and why making those associations LAZY is often the first performance fix." },
    { d: "Spring_Boot_Data_Model", n: "orderitem", q: "OrderItem has no surrogate id and is identified by (order_id, book_id). What is the idiomatic mapping?", opts: ["@EmbeddedId with an @Embeddable key class containing both columns, or a Map key on a @OneToMany", "A @GeneratedValue id you hide from the API", "@IdClass with two @Id fields but no embedded key class", "A @Transient composite field and manual SQL in the repository"], a: 0, e: "A composite key needs a real key type: @EmbeddedId or @IdClass, so equals, hashCode and detachment behaviour are well defined. A generated surrogate id is a legitimate modelling choice if you want a stable identifier for the line, but hiding a generated key is not the same as modelling a composite key, and transient fields plus hand-written SQL lose lazy loading, flush ordering and query derivation." },
    { d: "Spring_Boot_Data_Model", n: "user", q: "A User entity overrides equals and hashCode using the generated id. What breaks?", opts: ["Until the entity is persisted the id is null, so it lands in a HashSet under a mutable hash - then its hash changes on flush and it disappears from the set", "Nothing; Hibernate handles null ids", "The entity cannot be used in a @OneToMany", "equals is never called for entities"], a: 0, e: "Hash-based collections require a hash that does not change, and the id is assigned at flush time. Use the business key (email, natural key) or the id only for already-persisted instances and be consistent - which is exactly what the generated equals/hashCode in project Lombok and IDEs usually gets wrong for entities in both directions." },
    { d: "Spring_Boot_Data_Model", n: "payment", q: "Why is @Enumerated(EnumType.STRING) the usual choice for a status column, and what happens with the default?", opts: ["It stores the constant name, so reordering or renaming constants is visible in the data; the default ordinal form silently reinterprets existing rows when the enum changes", "It is faster to query with an index", "It allows null values in a non-nullable column", "The default is more readable in the database"], a: 0, e: "String form is decoupled from declaration order, so inserting a constant in the middle cannot rewrite history, and the value in the database is readable during an incident. Ordinals are compact but the column silently changes meaning; renaming or reordering is then a data migration, not a code change. The other options are not reasons to choose either form." },
    { d: "Spring_Boot_Data_Model", n: "author", q: "Author has @OneToMany(mappedBy = \"author\", cascade = CascadeType.PERSIST, orphanRemoval = true) List<Book> books. Which behavior is correct?", opts: ["persist(author) also inserts its books, and taking a book out of the list deletes its row on the next flush", "orphanRemoval deletes the child row immediately at books.remove(book), without waiting for a flush", "CascadeType.PERSIST alone also guarantees that removing a book from the list deletes it", "The author_id foreign key column is created on the authors table"], a: 0, e: "Cascade PERSIST propagates persist to each new Book, and orphanRemoval marks elements removed from the owned collection for deletion at the next flush rather than instantly at remove(). CascadeType.PERSIST has no delete semantics at all, and because mappedBy makes Author the inverse side, author_id lives on the book table." },
    { d: "Spring_Boot_Data_Model", n: "book", q: "Book carries @Version private int version, and two transactions update the same book concurrently. What does Hibernate 6 do?", opts: ["The updates are serialized by a database lock and both commits succeed", "Both transactions start fine, but the second commit fails because the stored version no longer matches", "The second writer silently overwrites the first, because @Version only counts reads", "Hibernate switches the row to pessimistic locking for the rest of the transaction"], a: 1, e: "Every update writes an incremented version, so the loser of the race finds a stale version in its WHERE clause and fails with an optimistic-lock error at flush or commit. The provider neither serializes writers nor overwrites them, and @Version never takes a pessimistic lock; the caller is expected to retry." },
    { d: "Spring_Boot_Data_Model", n: "bookcategory", q: "Book and Category are mapped with @ManyToMany, and someone adds cascade = CascadeType.ALL to Book.categories. What is the real risk?", opts: ["Cascade is ignored for many-to-many collections, so the annotation has no effect", "Categories can no longer be fetched without an inner join", "Deleting a book also deletes Category rows that other books still reference, corrupting shared data", "The join table gains a second category_id column and DDL generation fails"], a: 2, e: "Cascade REMOVE, which is part of ALL, treats each Category as owned by the book, so deleting the book wipes shared category rows still referenced by other books. Cascade is definitely not ignored on many-to-many collections, and cascade never changes the shape of the join table or the fetch plan." },
    { d: "Spring_Boot_Data_Model", n: "category", q: "Category declares @ManyToOne private Category parent and @OneToMany(mappedBy = \"parent\") List<Category> children. Which statement matches the mapping?", opts: ["Both sides own a foreign key, so parent_id and child_id columns are both generated", "children is the owning side, because collections always hold the foreign key", "The categories table gets a parent_id column, so parent owns the relationship and children is only the inverse view", "mappedBy must be removed from children or Hibernate fails at startup"], a: 2, e: "The side without mappedBy is the owning side and carries the join column, so parent_id lives on categories and children merely mirrors it. Owning-ness has nothing to do with being a collection, only one side can own the relationship, and an inverse side needs no @JoinColumn." },
    { d: "Spring_Boot_Data_Model", n: "cart", q: "User has @OneToOne private Cart cart; with neither fetch nor cascade set. Which pair of facts is right?", opts: ["Carts are lazy by default, and deleting the user cascades to the cart row", "Carts are eager, and deleting the user automatically deletes the cart row", "Every association is lazy by default, including one-to-one", "Carts are fetched eagerly by default, and deleting the user leaves the cart row in place"], a: 3, e: "JPA defaults make @OneToOne and @ManyToOne EAGER, so the cart is selected together with the user unless you ask for LAZY. With no cascade the cart row is untouched when the user is deleted, which usually trips the foreign key from cart to user rather than removing anything." },
    { d: "Spring_Boot_Data_Model", n: "cart", q: "Cart holds @ElementCollection List<String> couponCodes with no fetch attribute. How is it stored and loaded?", opts: ["As a comma-separated string in a coupon_codes column of the carts table", "In a separate collection table keyed by the cart id, and loaded lazily by default", "Eagerly, because every collection of basic values must be loaded with its owner", "As real entities, so each element needs its own @Id"], a: 1, e: "An element collection is stored in its own collection table keyed by the cart id with one row per element, and its default fetch type is LAZY. There is no comma-separated column, collections of basic values are not forced eager, and the elements are not entities so they get no identity of their own." },
    { d: "Spring_Boot_Data_Model", n: "user", q: "User embeds an @Embedded Address (street, city, postcode), and another entity embeds the same Address class. Where is the data kept?", opts: ["In one addresses table, with a foreign key back to each owner", "Serialized into a JSON column automatically by Hibernate 6", "In each owning table as its own street, city and postcode columns; nothing is shared", "Only possible if Address is itself annotated @Entity"], a: 2, e: "Embedding inlines the value object's fields into each owning table, giving two independent sets of street, city and postcode columns with nothing shared. There is no addresses table unless you map one, Hibernate 6 does not switch to JSON automatically, and value types are intentionally not entities." },
    { d: "Spring_Boot_Data_Model", n: "orderitem", q: "OrderItem uses @EmbeddedId OrderItemId and also maps the book with @MapsId(\"bookId\"). What does @MapsId accomplish?", opts: ["It makes the bookId part of the embedded id share its column with the association's foreign key", "It creates a second book_id column so the id and the reference can differ", "It switches the association to eager loading", "It generates the id at runtime from a sequence"], a: 0, e: "@MapsId tells Hibernate that the named id attribute comes from the mapped association, so one book_id column serves as both the id part and the foreign key. A second column would defeat that purpose, and @MapsId has nothing to do with fetch type or id generation." },
    { d: "Spring_Boot_Data_Model", n: "payment", q: "Payment stores BigDecimal amount with @Column(precision = 12, scale = 2). Which statement is correct?", opts: ["precision is the digits after the decimal point, so the column becomes DECIMAL(2,12)", "The annotation is DDL-only, because at runtime the amount is passed to JDBC as a double", "The DDL column is DECIMAL(12,2) and values are bound as exact numerics, so no binary rounding occurs", "Hibernate 6 ignores these attributes and maps BigDecimal to DOUBLE PRECISION"], a: 2, e: "precision is the total digit count and scale is the digits after the point, so 12 and 2 give DECIMAL(12,2). The annotation is not DDL-only, since Hibernate binds the value with setBigDecimal, which is exactly why BigDecimal avoids the rounding you would get from a double or DOUBLE PRECISION." },
    { d: "Spring_Boot_Data_Model", n: "bookitem", q: "BookItem needs a unique serial number and a mandatory reference to its Book. Which mapping is correct?", opts: ["@Column(unique = true) on serial, plus @OneToMany(mappedBy = \"book\") on BookItem", "@Column(unique = true, nullable = false) on serial, plus a plain @ManyToOne Book book on BookItem", "A unique constraint declared on the @ManyToOne field, because constraints belong to associations", "@ManyToOne(mappedBy = \"item\") on BookItem, so both sides become bidirectional"], a: 1, e: "The foreign key column sits on the book_item table, so BookItem must be the side that declares @ManyToOne, while unique and nullable belong on the ordinary serial column. An inverse @OneToMany or a mappedBy on a many-to-one would put the reference on the wrong table, and a unique constraint cannot be declared on an association at all." },
    { d: "Spring_Boot_Nplus1", n: "loop", q: "What exactly triggers an N+1 select problem?", opts: ["A lazy association is dereferenced inside a loop, so the persistence context issues one extra query per iteration", "The repository method is called more than once", "A @Transactional annotation is missing", "The database has no index on the foreign key"], a: 0, e: "The pattern is: one query fetches the parents, then each row triggers its own lazy load. The count is deterministic - N+1 - and the tell is SQL log volume that grows with result size. A missing index makes each of those extra queries slower but does not create them, and calling a repository twice is just two queries." },
    { d: "Spring_Boot_Nplus1", n: "query101", q: "You call orderRepository.findAll() and then order.getItems() for each order inside a @Transactional method. How many SQL statements do you see with lazy collections?", opts: ["1 findAll + 1 select per order - the N+1 pattern", "Exactly 1, because the persistence context batches the collection loads", "2, because Hibernate always adds a single join query", "0 additional statements, because collections are cached"], a: 0, e: "Each collection is a separate proxy that executes on first access, so the statement count scales with the result set. The persistence context caches by identity, which does not help when the rows are distinct collections, and the second-level cache is off by default. Only a join fetch or an entity graph collapses it to one statement." },
    { d: "Spring_Boot_Nplus1", n: "joinfetch", q: "You add join fetch to the repository query, but the response still triggers extra queries. What is the usual reason?", opts: ["A second, lazily loaded collection is accessed outside the query - one query can only fetch multiple bags safely if they are not both bag collections", "join fetch is ignored unless the method name starts with findBy", "The @Transactional annotation was removed from the service", "The query must be a native query to use fetch joins"], a: 0, e: "Fetch joins solve the problem you fetch on; a second collection - typically another LAZY bag - either fails with 'cannot simultaneously fetch multiple bags' or loads separately. Fix the remaining collection with a second query, an @EntityGraph, or map one side as a Set, and always use distinct with the join fetch. JPQL joins work fine, and @Transactional is not what makes a fetch join work." },
    { d: "Spring_Boot_Nplus1", n: "fixedservice", q: "Which change reduces N+1 to a small fixed number of queries without rewriting the query?", opts: ["Set hibernate.default_batch_fetch_size (or @BatchSize) so collection and entity loads are batched into IN clauses", "Add @Query(nativeQuery = true) to the same derived query", "Switch the repository to JpaRepository instead of CrudRepository", "Annotate the loop with @Transactional(propagation = REQUIRES_NEW)"], a: 0, e: "Batch fetching groups the individual loads Hibernate would have issued into IN queries, so the count becomes roughly 1 plus a couple regardless of N - at the cost of memory and a slightly larger working set. The other options change nothing: the repository base interface, the query flavour and the transaction propagation are all orthogonal to how many statements Hibernate issues." },
    { d: "Spring_Boot_Nplus1", n: "onequery", q: "When you fix N+1 with @EntityGraph(attributePaths = ...) or a fetch join, which other details still matter?", opts: ["You may still get duplicates, so projections need distinct; with two to-many fetches you need a Set or a two-step load, and pagination must be on the root query", "Nothing - the graph makes the result one-to-one by construction", "You must also add an index on every joined column", "You must remove the @Transactional annotation"], a: 0, e: "Fetch joins are ordinary joins, so a parent with N children appears N times and DTO construction may hand you duplicates - which is why distinct is often needed. Two to-many fetches in one query is the classic 'multiple bag fetches' error, and in-memory pagination on a fetch-joined collection is silently wrong. An index helps join cost but is unrelated to the duplicate rows." },
    { d: "Spring_Boot_Transactions", n: "required", q: "An outer transactional method calls an inner method also annotated REQUIRED. What is the result?", opts: ["One physical transaction: the inner call joins it, participates in the same rollback rules, and nothing commits until the outer method returns", "Two transactions, both committing independently", "No transaction, because REQUIRED only applies to the outermost call", "A read-only transaction, because propagation always downgrades"], a: 0, e: "REQUIRED means 'join if one exists, create otherwise', which is the default. The inner method's rollback marks the shared transaction rollback-only, and the commit happens once at the top - so an inner failure that you swallow still kills the outer commit. Nothing is independent and nothing is read-only." },
    { d: "Spring_Boot_Transactions", n: "requiresnew", q: "Why does REQUIRES_NEW require a second database connection, and what is the production risk?", opts: ["It suspends the current transaction and opens a new one, so it needs a second connection from the pool - if the pool is small, the outer transaction starves waiting for one and the app deadlocks or times out", "It copies the data to a new database", "It needs a second EntityManagerFactory", "It locks the whole table until the new transaction commits"], a: 0, e: "Suspending does not release the connection: the outer transaction keeps holding its connection while the inner one checks out another, so a pool smaller than your nesting depth self-deadlocks. Hikari's 'Connection is not available, request timed out' is the classic symptom. The risk scales with how often the code path runs, not with how often the DB is slow." },
    { d: "Spring_Boot_Transactions", n: "rollback", q: "Under the default rollback rules, which of these roll back a @Transactional method? (multiple may apply - pick the one that is always true)", opts: ["RuntimeException and Error; checked exceptions do NOT roll back unless you set rollbackFor", "Any Throwable, always", "Only checked exceptions", "Nothing rolls back - you must call setRollbackOnly yourself"], a: 0, e: "The default rule mirrors EJB3 and is a classic trap: throw new IOException() and your transaction commits. Declare rollbackFor = Exception.class (or unchecked = Exception.class) when the method can throw checked failures that matter. Nothing about the exception type marks the transaction automatically, and rollback-only is a manual escape hatch, not the default." },
    { d: "Spring_Boot_Transactions", n: "poison", q: "An inner transactional method throws, you catch it in the outer method and continue. What does the outer method see when it returns?", opts: ["UnexpectedRollbackException - the shared transaction was already marked rollback-only, and the outer attempt to commit fails", "The data commits, because the exception was handled", "Only the inner work is rolled back", "A deadlock"], a: 0, e: "The inner call joined the same transaction, so the failure poisoned it; catching the exception in application code does not un-mark it, and commit fails loudly rather than silently. Either do not catch, or use REQUIRES_NEW for the part that must survive - which is why 'I caught the exception and it still rolled back' is such a common and confusing production surprise." },
    { d: "Spring_Boot_Transactions", n: "nested", q: "How does NESTED propagation differ from REQUIRES_NEW?", opts: ["NESTED uses a savepoint inside the current transaction, so the inner work can roll back independently without a second transaction or connection", "NESTED opens a second transaction on a second connection", "NESTED is only supported on the reactive manager", "NESTED commits the outer transaction early"], a: 0, e: "NESTED is a savepoint: same transaction, same connection, partial rollback only. It requires the platform to issue SAVEPOINT statements, so it depends on driver and transaction manager support, and it is easy to forget it is not a real independent transaction. REQUIRES_NEW is a genuinely separate transaction on a second connection - and commits the inner work even if the outer later rolls back." },
    { d: "Spring_Boot_Transactions", n: "commit", q: "For a REQUIRED transaction started by a service method, when does the database actually see the commit?", opts: ["When the proxied method returns normally, the transaction manager commits - not when each statement is executed", "After each SQL statement, because auto-commit is on", "When the HTTP response is written to the socket", "When the connection is returned to the pool"], a: 0, e: "The transaction manager is what turns auto-commit off, issues the work, and commits at the boundary. Committing per statement would defeat the purpose of the unit of work, and the connection returning to the pool is a later, different event that is only safe because the transaction already ended. Writing the response happens after the commit, which is why a failed response cannot roll the data back." },
    { d: "Spring_Boot_Transactions", n: "outer", q: "You annotate the controller method with @Transactional instead of the service method. What breaks?", opts: ["The transaction covers the web layer - a later LazyInitializationException or an over-long transaction that holds a pooled connection across serialization and response writing", "Nothing; the boundary is wherever you put it", "Spring MVC forbids @Transactional on controllers", "The transaction commits before the repository call"], a: 0, e: "A transaction on the controller holds a pooled connection for the whole request, including view rendering and socket writes, and it spreads the persistence concern into the adapter layer where every other caller forgets it. MVC does not forbid it - which is why the mistake is silent. The commit still happens when the annotated method returns; the damage is scope, not timing." },
    { d: "Spring_Boot_Transactions", n: "inner", q: "A method with REQUIRES_NEW is called from a REQUIRED method, and the outer method then throws. What is the final state?", opts: ["The inner work is already committed and survives; the outer work is rolled back", "Both are rolled back", "Both commit", "The inner work is rolled back and the outer commits"], a: 0, e: "REQUIRES_NEW is a real independent transaction: it commits when it returns, so it cannot be undone by the outer failure. That is exactly why people reach for it to write audit or error records - and exactly why it is dangerous as a default, because it also commits work the caller expected to disappear, and it needs a second connection from the pool." },
    { d: "Spring_Boot_Caching", n: "cacheproxy", q: "Why does @Cacheable sometimes seem to do nothing when the method is called from another method in the same class?", opts: ["The cache advice lives in a proxy; a self-invocation bypasses it, so the annotation is inert on internal calls", "@Cacheable only works on methods with arguments", "The cache is empty because the first call returned null", "@Cacheable requires a public class and a no-arg constructor"], a: 0, e: "Same root cause as self-invocation with @Transactional and @Async: the annotation is honoured by the proxy, and an internal call never reaches it. Null results are cached too, and a cacheable method needs no arguments to work. Fix it by splitting the class or self-injecting the proxy - the same fix you already know from transactions." },
    { d: "Spring_Boot_Caching", n: "cache", q: "What does @Cacheable do when the annotated method throws?", opts: ["Nothing is cached, because the cache is only populated on successful return", "The exception is cached and rethrown on later calls", "A partial entry is written and then evicted", "The cache is flushed entirely"], a: 0, e: "The advice stores the return value on the normal path, so failures are not cached - which is usually what you want, though it also means a persistent failure keeps hammering the database unless you add a negative cache or a circuit breaker. Exceptions are not serializable values, and there is no partial write; if you need failure caching, @Cacheable(cacheManager = ...) with a wrapped result is the pattern." },
    { d: "Spring_Boot_Caching", n: "evictor", q: "A service updates a book and calls a @CacheEvict method - but the cache still serves stale data. What is the most common cause?", opts: ["The evict method is invoked internally (self-invocation) or through a non-proxied reference, so the eviction never runs", "Eviction happens before the update commits, so it caches the old value again", "@CacheEvict requires a transaction", "Caffeine evicts asynchronously, so the entry survives briefly"], a: 0, e: "Eviction is advice, so it has exactly the same proxy requirement as @Cacheable - a self-invoked call is a no-op. Eviction does not need a transaction, and eviction is synchronous, not deferred. A real timing bug is possible with cache-aside and concurrent writes, which is where a short TTL and write-through or versioned keys help." },
    { d: "Spring_Boot_Caching", n: "cachemgr", q: "Which CacheManager does Spring Boot use by default for a simple local cache, and what do you change to get a shared one?", opts: ["Caffeine (or ConcurrentMapCacheManager if Caffeine is absent); for a shared cache add a Redis starter and Boot switches to RedisCacheManager", "Always ConcurrentMapCacheManager unless you write your own", "Always RedisCacheManager, which falls back to a local map when Redis is absent", "Always EhCache, with Caffeine only in tests"], a: 0, e: "Boot auto-configures a local Caffeine cache when that library is present, and falls back to a simple ConcurrentMapCacheManager, which is unbounded and fine only for tiny, test-only caches. Boot does not silently fall back from Redis to a local map - if a Redis connection is configured and unreachable, you get a timeout per call, not a local cache - and a shared cache is the only thing that works across replicas." },
    { d: "Spring_Boot_Caching", n: "db", q: "You want a per-customer cache key built from an argument. Which is the idiomatic way?", opts: ["@Cacheable(key = \"#customerId\") or @Cacheable(key = \"#root.args[0].id\"), with the SpEL evaluated against the method arguments", "@Cacheable(cacheNames = customerId) - the argument name becomes the key", "@Cacheable(keyGenerator = \"uuidGenerator\") so each call gets a unique entry", "@Cacheable plus @CachePut on the same method"], a: 0, e: "SpEL key expressions are the supported mechanism: #id names a parameter, #p0/#a0 index it, and #root gives you the whole argument set, so composite keys like #customer.id + ':' + #product.id are natural. The method name is a cache name, not a key; a random key defeats the cache; and @CachePut on the same method is a confusing combination that always overwrites on read." },
    { d: "Spring_Boot_Caching", n: "client", q: "Two application replicas both run a local Caffeine cache behind one load balancer. What is the user-visible symptom?", opts: ["Stale data that depends on which replica answers - each replica has its own cache and its own eviction timing", "Cache misses on every request", "OutOfMemory, because Caffeine cannot be shared", "Consistent data, because the cache is keyed by the method"], a: 0, e: "Local caches are per-JVM, so reads are non-deterministic across replicas and evictions only reach the instance that performed the write - this is the classic 'works on my instance' bug. You either move to a shared cache manager (Redis) or accept staleness and shrink the TTL. Caffeine and keying have nothing to do with the memory or miss symptoms described." },
    { d: "Spring_Boot_Caching", n: "service", q: "You enable @EnableCaching and @Cacheable on a service method, then hit the endpoint twice. What is the expected SQL pattern?", opts: ["First call runs the query and populates the cache; the second call serves the cached value and issues no SQL, until eviction or TTL expiry", "Both calls run the query, because the transaction manager bypasses the cache", "The first call returns cached data from a previous run, the second queries", "The cache only works for write methods"], a: 0, e: "That is the cache-aside pattern: a miss populates, a hit does not touch the database, and eviction or TTL expiry returns you to the database. The transaction manager is orthogonal, and the first call in a fresh process is always a miss. The interesting production detail is what invalidates the entry - evict on write, or accept a short TTL." },
    { d: "Spring_Boot_Caching", n: "controller", q: "Should you annotate a @RestController method with @Cacheable? What are the trade-offs?", opts: ["It works and covers the serialized response, but it caches presentation concerns, hides per-user variation unless your key includes identity, and skips service-level reuse for internal callers", "No, it is forbidden on controllers", "Yes, and it is always better because it avoids serializing twice", "No, because controllers are proxied and @Cacheable cannot apply"], a: 0, e: "Controllers are proxied beans, so the annotation does apply - which is exactly the problem: you are caching a wire representation, you must build a correct key (customer, locale, roles) yourself, and any internal caller of the service bypasses the cache. The correct default is to cache the expensive domain operation in the service and let the same cache serve web and batch callers." },
    { d: "Spring_Boot_Caching", n: "cache", q: "A profile service must both return the updated user and refresh the entry in the users cache on every call. Which annotation guarantees the method still runs and the cache is written?", opts: ["@Cacheable, because it re-invokes the method whenever the entry is missing", "@CacheEvict with allEntries = true, because clearing forces the next read to rebuild the entry", "@CachePut, because it always executes the method and stores its return value under the key", "@CacheConfig, because class-level configuration refreshes entries whenever the bean is used"], a: 2, e: "@CachePut runs the method on every call and writes the result, so the caller gets fresh data and the cache stays in sync. @Cacheable skips the body on a hit and only fills the cache when the entry is absent, eviction deletes rather than refreshes, and @CacheConfig just declares shared cache names." },
    { d: "Spring_Boot_Caching", n: "evictor", q: "An update method annotated @CacheEvict(cacheNames = \"books\", beforeInvocation = true) throws a constraint violation halfway through. What happens to the cached entry for that book?", opts: ["It stays in the cache, because Spring only evicts after the method returns normally", "It is removed anyway, because a thrown exception always triggers allEntries eviction as a safety net", "It is overwritten with the rejected values, because the exception handler writes them back before rethrowing", "It is removed, because beforeInvocation = true deletes the entry before the method body runs, even though the update failed"], a: 3, e: "beforeInvocation = true moves eviction ahead of the method body, so the entry is gone regardless of the outcome. With the default beforeInvocation = false the eviction is skipped when the method throws, exceptions never fill the cache, and no handler writes failed data back." },
    { d: "Spring_Boot_Caching", n: "cachemgr", q: "A Boot app uses the default local cache manager and the JVM heap grows steadily over a weekend because cached product entries are never dropped. What is the correct fix?", opts: ["Configure a CaffeineCacheManager with expireAfterWrite, because the default ConcurrentMapCacheManager has no time-to-live and never evicts on its own", "Set spring.cache.type=redis and restart, because Redis is the only cache that expires entries", "Add a @Scheduled method that clears the map hourly, because local caches cannot expire at all", "Raise -Xmx, because the default cache does evict and simply needs more headroom"], a: 0, e: "Boot's default local cache is a plain ConcurrentHashMap with no expiry and no size limit, so entries live until something explicitly evicts them. Switching the type alone does not help because Redis still needs a TTL policy, hand-written clearing is only a workaround, and a bigger heap just delays the same growth." },
    { d: "Spring_Boot_Caching", n: "cacheproxy", q: "Two @Cacheable methods have no key attribute and each takes a single String region argument. Under the default key generator, what happens?", opts: ["Both write to the same entry, because cache names are ignored when keys are generated", "Each method writes into its own cache under a SimpleKey holding the region value, so identical regions hit but the two caches stay separate", "Spring uses the method's fully qualified name, so every argument maps to a single entry per method", "A failure is raised at startup, because a SpEL key expression is mandatory"], a: 1, e: "The default SimpleKeyGenerator builds a SimpleKey from the method arguments, and lookup happens inside the cache named by cacheNames, so each method gets its own namespace and identical arguments collide only within it. Cache names are not ignored, the method name is never part of the key, and key is optional." },
    { d: "Spring_Boot_Caching", n: "service", q: "Five methods in BookService all repeat @Cacheable(cacheNames = \"books\", keyGenerator = \"isbnKeyGen\"). What does putting @CacheConfig on the class actually buy you?", opts: ["It makes cache names hierarchical so every method shares one parent entry space", "It applies caching to all public methods of the class without any per-method annotation", "It replaces the CacheManager, so no CacheManager bean is needed afterwards", "It lets individual methods omit the repeated cacheNames and keyGenerator values by inheriting them from the class, while each method still needs its own @Cacheable to participate"], a: 3, e: "@CacheConfig only supplies defaults that individual annotations inherit, so each method still needs @Cacheable, @CachePut, or @CacheEvict to take part. It creates no hierarchy, does not switch caching on implicitly, and has no bearing on how the CacheManager is resolved." },
    { d: "Spring_Boot_Caching", n: "repo", q: "A @Transactional update method calls @CacheEvict at the end, yet another request still reads the old row before the transaction commits and repopulates the cache. What is the standard fix?", opts: ["Move the eviction into the repository layer, because repository calls run later inside the same transaction", "Evict or refresh the cache only after commit, for example from a transaction synchronization callback or an event published afterCommit", "Configure the cache to store null values, so a miss looks the same as an old row", "Use a transactional CacheManager so the eviction commits together with the database write"], a: 1, e: "Cache operations are not transactional, so evicting before commit leaves a window where a concurrent reader caches pre-commit data; deferring the eviction until afterCommit closes it. Moving the call deeper into the same transaction does not help, null caching changes nothing about staleness, and CacheManager is not a transactional resource." },
    { d: "Spring_Boot_Caching", n: "db", q: "You want @Cacheable to skip the cache entirely when the caller is an internal batch user, and also to avoid storing null results. Which pair of attributes does that?", opts: ["unless = \"#internalBatch\" evaluated before the call, and condition = \"#result == null\" evaluated afterwards", "Both attributes set to the same SpEL, because condition and unless are aliases kept for backward compatibility", "condition = \"#internalBatch\" evaluated before the method runs, and unless = \"#result == null\" evaluated on the value it returns", "Only condition, because Spring never caches null return values by default"], a: 2, e: "condition decides whether the cache is consulted at all and is evaluated against the arguments before invocation, while unless inspects the returned value afterwards. Swapping them puts a result-based test too early and an argument test too late, they are not aliases, and null results are stored unless you exclude them." },
    { d: "Spring_Boot_Security_JWT", n: "chain", q: "In a default Spring Security Boot application, where does authentication happen and what is the shape of the chain?", opts: ["A FilterChainProxy holds an ordered list of security filters; the authentication filters run early and populate a SecurityContext for the request", "Inside the controller, via an @AuthenticationPrincipal resolver", "In a servlet container valve configured in server.xml", "Inside the DispatcherServlet's HandlerAdapter"], a: 0, e: "Spring Security is a filter chain, and the default Boot order starts with CSRF, then authentication, then authorization, then the exception-translation filters that turn failures into 401 or 403. The @AuthenticationPrincipal resolver only reads what the filters already stored, so if the chain does not run - a filter ordering mistake, or a URL you excluded - nothing downstream can authenticate anyone." },
    { d: "Spring_Boot_Security_JWT", n: "filter", q: "Where in the request does a stateless JWT filter belong, and what must it do on failure?", opts: ["Early in the chain, before authorization; on an invalid or expired token it must hand off to the AuthenticationEntryPoint so the client gets 401, not a bare 403", "After the controller, as a response wrapper", "Inside the service layer, by parsing the Authorization header manually", "Only on /login"], a: 0, e: "The token filter must run before authorization so the SecurityContext is populated, and the correct failure behaviour is delegation to the entry point - unauthenticated means 401, authenticated-but-denied means 403, and conflating them breaks client retry logic. Doing it in the service layer is the hand-rolled approach that misses every endpoint you forgot." },
    { d: "Spring_Boot_Security_JWT", n: "ctx", q: "What is the role of SecurityContextHolder in a stateless API?", opts: ["A per-thread store of the current Authentication for the request; the filters set it on the way in and the framework clears it on the way out, so nothing persists in a session", "It stores JWTs in the HTTP session so they survive restarts", "It is a cache of validated tokens keyed by subject", "It holds the CSRF token"], a: 0, e: "SecurityContextHolder is a thread-local strategy: with SessionCreationPolicy.STATELESS no session is created, so each request re-authenticates from the bearer token. That is also why a filter that forgets to clear the context, or an error dispatch, can leak an authentication into another request. CSRF tokens and token caches are unrelated mechanisms." },
    { d: "Spring_Boot_Security_JWT", n: "entrypoint", q: "A client gets 403 when it sends no Authorization header, and 403 when it sends a valid token lacking the required role. What should be configured?", opts: ["A custom AuthenticationEntryPoint returning 401 for the anonymous case, and an AccessDeniedHandler returning 403 for the denied case", "Both should return 401, since the token is involved", "Both should return 302 to a login page", "Neither - the controller should throw ResponseStatusException"], a: 0, e: "ExceptionTranslationFilter picks the entry point when the Authentication is anonymous or missing and the access-denied handler when a real Authentication lacks the authority, so the two situations are distinguishable and should be reported differently. Spring's defaults are 302 (form login) or 403 for both, which is why REST APIs configure both handlers explicitly. @PreAuthorize denials arrive as AccessDeniedException and are handled by the denial handler." },
    { d: "Spring_Boot_Security_JWT", n: "client", q: "For a resource server that validates JWTs issued elsewhere, what do you configure in Boot 3?", opts: ["spring-boot-starter-oauth2-resource-server with a jwk-set-uri (or a public-key location), plus a converter if you need roles from claims", "spring-boot-starter-security plus a hand-written filter that parses the token", "A UserDetailsService with a hard-coded token list", "Session cookies with rememberMe()"], a: 0, e: "The resource-server starter supplies the standard chain, Nimbus-based validation of signature, issuer and expiry, and key retrieval from the issuer's JWKS. A hand-written filter is legitimate when you need control, but then key rotation, clock skew and claim mapping are yours to own. Session cookies and UserDetailsService are the stateful alternative and mean the token is not validated per request at all." },
    { d: "Spring_Boot_Security_JWT", n: "chain", q: "A mobile client sends no token to a secured endpoint, and later sends a valid token without ROLE_ADMIN to an admin endpoint. Which pair of responses is correct?", opts: ["401 for the missing token and 403 for the insufficient role, produced by AuthenticationEntryPoint and AccessDeniedHandler respectively", "403 for both, because Spring Security always answers Forbidden", "401 for both, because authentication and authorization failures are identical to the client", "400 for the missing token and 403 for the role, since a missing header is a malformed request"], a: 0, e: "An unauthenticated request triggers the AuthenticationEntryPoint, which challenges with 401, while an authenticated user who lacks the authority hits the AccessDeniedHandler and gets 403. Answering 403 for both hides whether the client should log in again, and a missing header is not a malformed HTTP message." },
    { d: "Spring_Boot_Security_JWT", n: "filter", q: "You set SessionCreationPolicy.STATELESS for a JWT API. Which statement is true afterwards?", opts: ["Spring Security still creates an HttpSession per request to hold the SecurityContext, but ignores it when authorizing", "No HttpSession is created or loaded by Spring Security, so session fixation handling and session-based logout have nothing to work with", "The JWT is stored in the HttpSession, which is now kept in memory instead of on disk", "CSRF protection switches itself off, because there is no session to protect"], a: 1, e: "STATELESS means Spring Security never touches a servlet session, so everything on the security path that depends on session state disappears. The token is read from a header on every request instead of being stored, and CSRF behaviour is configured separately from the session policy." },
    { d: "Spring_Boot_Security_JWT", n: "client", q: "Why should an access token travel in an Authorization header rather than a cookie on a public JSON API?", opts: ["Cookies are encrypted by the browser, so putting the token in one would hide it from page scripts", "Headers have a much larger size limit than cookies, and a long JWT would be truncated in a cookie", "A cookie is attached automatically by the browser on every same-site request, which reopens the CSRF surface and exposes the token to any script that reads document.cookie, while a header is only added by code that sets it", "The servlet specification forbids filters from reading security tokens out of cookies"], a: 2, e: "Because the browser attaches cookies on its own, an attacker can ride the user's credentials through cross-site requests and any XSS can read the token from document.cookie. Cookies are not encrypted by the browser, size is not the constraint, and filters can read cookies perfectly well." },
    { d: "Spring_Boot_Security_JWT", n: "ctx", q: "In a stateless API, why must the SecurityContext be removed from the SecurityContextHolder when the request finishes, even though the next request will overwrite it?", opts: ["Because the SecurityContext is immutable and must be rebuilt for each request", "Because JWT validation results would otherwise be cached in the holder and outlive the token", "Because the holder accepts only one write per thread, so a second request on that thread could never authenticate", "Because container threads are pooled, so an identity left in the ThreadLocal would be visible to a later request on that thread before its own authentication completes"], a: 3, e: "Servlet container threads are recycled, so whatever identity is left behind can be read by the next request that runs on that thread before authentication has finished. The context is mutable and rewritten normally, no validation result is cached there, and there is no one-write-per-thread limit." },
    { d: "Spring_Boot_Security_JWT", n: "ctx", q: "Tokens verify cleanly but your API intermittently rejects them with 401 right after a deployment when server clocks differ by a few seconds. What is the most likely cause?", opts: ["The exp or nbf claim fails validation because of clock skew, which is why verifiers expose a configurable clock-skew allowance", "The signature algorithm is missing from the allowed list, so verification aborts before any claim is read", "The typ header is absent, which Boot 3 rejects by default for access tokens", "The proxy compressed the Authorization header and corrupted the payload segment"], a: 0, e: "A signature can be perfectly valid while a time claim still fails, and small differences between the issuer's clock and yours push exp or nbf over the edge. An algorithm restriction would reject every token rather than some, there is no default typ check, and proxies do not rewrite bearer tokens." },
    { d: "Spring_Boot_Security_JWT", n: "entrypoint", q: "A browser SPA authenticates with JWTs sent in the Authorization header and leaves Spring Security's CSRF protection on with default settings. What breaks?", opts: ["Nothing, because CSRF tokens are only enforced on state-changing controller methods", "Every state-changing request needs a CsrfToken that the SPA has no session to hold, so POST, PUT and DELETE are rejected while GET still passes", "Login fails, because the authentication filter consumes the CSRF token before parsing the JWT", "JWT validation is disabled while a CSRF filter is active, so every request returns 401"], a: 1, e: "CsrfFilter runs ahead of your controller and demands a token for unsafe methods, and the default repository keeps that token in an HttpSession the bearer-token SPA never establishes. Safe methods such as GET are unaffected, the filter does not interfere with JWT parsing, and the two mechanisms do not block each other's validation." },
    { d: "Spring_Boot_Security_JWT", n: "controller", q: "A service method is annotated @PreAuthorize(\"hasRole('ADMIN')\") and the validated JWT carries the authority ROLE_ADMIN. Does the call succeed?", opts: ["No, because hasRole compares authorities verbatim and expects the claim to contain exactly ADMIN", "No, unless you set spring.security.user.role-prefix to empty, because roles only come from the user store", "Yes, because hasRole prepends the default ROLE_ prefix before comparing, so ROLE_ADMIN matches", "Yes, but only if @EnableMethodSecurity is disabled, which otherwise blocks role expressions"], a: 2, e: "hasRole appends the configured role prefix, ROLE_ by default, so it looks for ROLE_ADMIN among the granted authorities, and hasAuthority is the exact-match variant. Verbatim comparison describes hasAuthority, the user store is irrelevant once authorities come from the token, and method security is what makes the expression run at all." },
    { d: "Spring_Boot_Security_JWT", n: "controller", q: "The security chain permits /api/reports/** for any authenticated user, but the service method behind it carries @PreAuthorize(\"hasRole('FINANCE')\"). What does an authenticated non-FINANCE user get?", opts: ["In, because the chain's authorization rule wins once the request is authenticated", "Rejected with 401, because method security runs before the authentication filter completes", "In, because @PreAuthorize is ignored whenever an httpSecurity matcher covers the path", "Rejected with 403, because the chain rule and the method expression are independent layers and both must pass"], a: 3, e: "The filter chain only decides whether a request may reach the handler, and the method security aspect then evaluates its own expression and throws AccessDeniedException, which surfaces as 403. There is no precedence between the layers, method security runs well after authentication, and a matcher never disables annotations." },
    { d: "Spring_Boot_Security_JWT", n: "client", q: "In Boot 3.3 you set spring.security.oauth2.resourceserver.jwt.issuer-uri and nothing else. How does the app obtain the keys it needs?", opts: ["It downloads the OIDC discovery document from the issuer, reads the jwks_uri and fetches the public keys from that JWKS endpoint", "It generates a signing key of its own, so only tokens you mint yourself will validate", "It calls the issuer on every request to ask whether the presented token is still good", "It accepts any structurally valid token until you add jwk-set-uri"], a: 0, e: "issuer-uri triggers discovery at startup so the authorization server's JWKS location is learned automatically and refreshed when the issuer rotates keys. A resource server never mints its own keys, per-request round trips to the issuer are not part of JWT validation, and without discovery or jwk-set-uri there is no key source at all." },
    { d: "Spring_Boot_Security_JWT", n: "client", q: "After logout, a user's access token still opens the API for another 15 minutes. What is the right response in a stateless design?", opts: ["Store every issued token in the database and look it up on each request, restoring a server-side session", "Keep access tokens short-lived and revocable refresh tokens behind them, with a small denylist only for emergencies", "Raise the token lifetime to 24 hours so fewer tokens expire mid-session", "Move the SecurityContext back into the HttpSession so logout can clear it"], a: 1, e: "Stateless validation never consults a server store by default, so revocation can only come from letting the access token die quickly or refusing to refresh it. A lookup per request rebuilds the session state you removed, a longer lifetime widens the window, and moving the context into a session changes the architecture rather than the problem." },
    { d: "Spring_Boot_Observability", n: "actuator", q: "After adding spring-boot-starter-actuator, what is exposed over HTTP by default, and how do you change it?", opts: ["Only /actuator/health and /actuator/info over the web; anything else needs management.endpoints.web.exposure.include", "All endpoints, always", "No endpoints until management.endpoints.enabled-by-default is set", "Only /actuator/metrics"], a: 0, e: "Actuator deliberately ships a small, safe web surface - health and info - and exposing metrics, env, configprops, loggers, heapdump or shutdown is an explicit decision you make. enabled-by-default is a different switch: it controls whether endpoint beans exist at all, which is what you use on non-web deployments. Getting this wrong in either direction is common: a fleet-wide scrape failing, or an env endpoint leaking secrets." },
    { d: "Spring_Boot_Observability", n: "health", q: "What does the default /actuator/health aggregate, and why is that a deployment concern?", opts: ["A composite status from every registered HealthIndicator - disk space, db, and anything custom; a DOWN result fails a readiness probe and pulls the pod from the Service", "Only the application's own up/down flag", "Only the database", "Nothing unless you write a HealthIndicator"], a: 0, e: "Boot auto-registers indicators for the technologies on your classpath, and the overall status is the worst of them - which is exactly what a readiness gate consumes. That is how a shared external system can take an otherwise healthy pod out of rotation, and the reason production setups split health into groups instead of one flat status." },
    { d: "Spring_Boot_Observability", n: "liveness", q: "What should a liveness probe check, and what happens if you let it check the database?", opts: ["Only that the process can make progress, typically nothing more than 'the context is up'; a DB check makes every pod restart during a database blip, turning a dependency outage into a full outage", "Database connectivity, so a restart fixes stale connections", "Full readiness, so the probe is maximally strict", "Disk usage only"], a: 0, e: "Liveness answers 'should this process be killed and replaced', so everything it checks must be fixable by restarting the process. Readiness answers 'should this process get traffic' and may check dependencies. Kubernetes enables the probes group automatically, which is why an unguarded liveness check silently couples your pod lifecycle to your database's." },
    { d: "Spring_Boot_Observability", n: "readiness", q: "How do you make readiness wait for the database and for warm-up, without dragging liveness along?", opts: ["Enable the probes group and define health groups: readiness includes readinessState plus db, liveness includes only livenessState", "Use the same health group for both probes", "Add a sleep before the liveness endpoint answers", "Disable the actuator and rely on fixed deploy delays"], a: 0, e: "The probes group is created automatically on Kubernetes, and health groups let you say readiness = started and the DB answers, while liveness = the JVM is not stuck. Reusing one group for both re-creates the DB-in-liveness bug, and a sleep in the probe is a race with extra steps that gets worse on a busy deploy." },
    { d: "Spring_Boot_Observability", n: "dbhealth", q: "You run Flyway migrations on application startup with several replicas. What goes wrong and what is the robust design?", opts: ["Replicas race on DDL locks and one pod's migration can break another's; run migrations as a separate job or init step, then gate readiness on schema readiness", "Nothing - Flyway takes a lock and serialises migrations automatically", "Migration failure only affects the pod that ran it", "Flyway is only for SQL Server"], a: 0, e: "Flyway (and Liquibase) do lock the history table, so concurrent startups queue up - but that turns pod startup order into a deployment dependency and a slow migration chain can exceed the pod's startup budget. The robust design separates schema change from application start: a migration job in the pipeline, then readiness gated on the database the app actually needs. Option 1 is wrong because a migration error usually means every pod fails identically." },
    { d: "Spring_Boot_Observability", n: "micrometer", q: "How does a metric recorded with Micrometer in Spring Boot reach Prometheus?", opts: ["Add micrometer-registry-prometheus; the MeterRegistry records it, the actuator exposes the scrape endpoint, and Prometheus pulls from it", "The JVM pushes metrics to a remote endpoint automatically", "Actuator POSTs metrics to Datadog once the starter is present", "Only built-in HTTP metrics are recorded unless you add an exporter"], a: 0, e: "Boot configures a MeterRegistry from whichever registry implementation it finds, the actuator serves Prometheus/OpenMetrics text at /actuator/prometheus, and scraping is pull-based. Web, JVM, Hikari pool and cache metrics come for free once a registry is on the classpath; the remaining work is naming your meters and tags carefully, since cardinality is where metrics platforms fall over." },
    { d: "Spring_Boot_Observability", n: "otel", q: "Which pieces do you need to get distributed traces out of a Spring Boot 3 service, and what is Micrometer's role?", opts: ["An OpenTelemetry SDK plus an OTLP exporter, bridged through Micrometer Tracing; Micrometer provides the vendor-neutral Observation API and manages the tracer and context propagation", "Nothing extra - @Transactional alone produces spans", "Only a logback pattern including %X{traceId}", "A vendor agent attached via JAVA_TOOL_OPTIONS"], a: 0, e: "Micrometer supplies Observation and the instrumenting API so that Spring MVC, the scheduler and the repository produce consistent signals, and Micrometer Tracing manages the tracer lifecycle; the OTel SDK and exporter are what ship the spans. Log correlation is a poor substitute - it gives you identifiers without timing or causality - and the agent is one transport option, not the only one." },
    { d: "Spring_Boot_Observability", n: "logs", q: "How do you correlate a log line with a distributed trace, and why does it matter operationally?", opts: ["Include the traceId and spanId in the pattern (or use structured JSON logging with a correlation field) so an alert links straight to the trace; MDC only works if context propagation is configured for async and remote hops", "Set logging.level.root=DEBUG and search for the timestamp", "Include the request URL in every message", "Enable Actuator metrics and correlate by pod name"], a: 0, e: "Trace and span identifiers are what turn a stack of log lines into a story, and they must be carried in MDC and propagated to worker threads and remote services. Timestamps are ambiguous under concurrency, a URL is not unique per request, and pod name tells you where, not which call - this is the difference between a five-minute and a two-hour incident." },
    { d: "Spring_Boot_Observability", n: "metrics", q: "A team tags every HTTP timer with userId to find slow users, and Prometheus memory climbs within a day. What went wrong?", opts: ["Timers cannot carry tags in Micrometer, so the values fell back to an untagged gauge", "Prometheus rejects labels above a fixed limit, so most samples were silently discarded", "The tag is unbounded, so every distinct user creates another time series and the scrape payload explodes; tags must come from a small bounded set", "Histograms ignore tags, so all users' durations were merged into a single timer"], a: 2, e: "Each tag combination is its own series, and a user id multiplies the timer by millions almost immediately. Micrometer supports tags on timers, Prometheus does not drop them silently, and collapsing users into one timer is what the design destroys rather than what it achieves." },
    { d: "Spring_Boot_Observability", n: "prometheus", q: "Batch pods finish in 40 seconds while your Prometheus server scrapes every 15 seconds. Which approach reliably keeps their metrics?", opts: ["Stay on the pull model, because Prometheus always catches at least two scrapes of any pod", "Increase the scrape timeout, since slow scrapes are the only reason data is missed", "Have a cron script scrape each pod's actuator port and ship the output files to the server", "Push the batch job's metrics to a Pushgateway that Prometheus scrapes, while long-running services stay on pull"], a: 3, e: "Pull requires the target to be alive at scrape time, which short-lived pods frequently are not, so the job pushes to a Pushgateway that is scraped at leisure. Normal services keep the simpler pull model, and no timeout setting can scrape a process that has already exited." },
    { d: "Spring_Boot_Observability", n: "micrometer", q: "You need the p95 latency of checkout calls and the current size of an in-memory queue. Which Micrometer instruments fit each?", opts: ["A timer for latency, which records durations and can publish percentiles, and a gauge for queue size, which reflects the current value", "A counter for latency and a gauge for queue size, because counters are cheaper to record", "A gauge for both, since gauges are the general-purpose instrument in Micrometer", "A counter incremented once per checkout call and a summary for queue size"], a: 0, e: "Timers accumulate durations and can publish the percentile histogram a p95 needs, while a gauge reads the value at scrape time and suits a queue that rises and falls. Counters only increase and cannot produce percentiles on their own, and gauges keep no history to compute latency from." },
    { d: "Spring_Boot_Observability", n: "endpoints", q: "You want the actuator reachable only on an internal interface while the application serves public traffic. What is the standard Boot 3 setup?", opts: ["Set server.forward-headers-strategy, because actuator then follows the public connector", "Set management.server.port to a separate port and restrict management.endpoints.web.exposure.include to the endpoints you need", "Write your own @RestController that re-exposes health and metrics under a private path", "Run a second copy of the application with actuator enabled and point the load balancer at it"], a: 1, e: "Boot lets management run on its own port so a container or firewall can keep it internal, and exposure is an explicit allow list rather than everything by default. Forwarded headers only affect URL generation, hand-rolled controllers bypass auto-configuration, and a second deployment is an operational workaround." },
    { d: "Spring_Boot_Observability", n: "tracing", q: "Your service calls another with RestClient, but the downstream span shows up as a brand-new trace instead of a child of yours. What is missing?", opts: ["A @NewSpan annotation on the RestClient call, because spans only cross process boundaries when marked", "A second OpenTelemetry SDK, since Micrometer Tracing records metrics but never propagates context", "Context propagation: the current span must be injected into the outbound headers as W3C traceparent, which Micrometer Tracing does for instrumented clients once a tracing bridge is on the classpath", "Manual log correlation, because trace ids never travel across HTTP"], a: 2, e: "A trace only connects across a network hop if the caller writes its trace context into the outgoing headers and callee reads them back. Annotations do not inject headers, Micrometer Tracing delegates export to an OpenTelemetry-compatible backend rather than being metrics-only, and log correlation consumes the trace id rather than carrying it." },
    { d: "Spring_Boot_Observability", n: "health", q: "Kubernetes readiness must include the database and disk, liveness must stay independent of both, and component details should be visible only to an authenticated operator. Which configuration does it?", opts: ["management.endpoint.health.probes.enabled=true plus a custom health group for readiness, with show-components set to when-authorized for the details", "management.health.livenessstate.enabled=true, because enabling one probe automatically splits every other check", "A single /actuator/health response with an X-Probes header that Kubernetes reads", "management.endpoint.health.show-details=always, which hides the liveness checks from probes"], a: 0, e: "Boot lets you define a health group with its own include list and bind the readiness and liveness probes to groups, so each probe sees only what it should, and show-components can be gated with when-authorized. Enabling probes does not reorganise the aggregates by itself, Kubernetes reads distinct probe endpoints rather than headers, and show-details=always would expose internals to everyone." },
    { d: "Spring_Boot_Observability", n: "logs", q: "Support needs the level for one package raised without a restart, and also wants the rolling log file streamed to a viewer. What do you need?", opts: ["Only a change to logback.xml, because Boot watches the file and reloads levels automatically", "Restart the pod with DEBUG in the environment, because logging levels are frozen once Logback initializes", "A custom Appender bean, because runtime level changes require code changes", "The /actuator/loggers endpoint exposed, so you can post a new level at runtime, and logging.file.name set at startup so /actuator/logfile has a file to stream"], a: 3, e: "The loggers endpoint writes a new level into the live logging system, which is why it must be on the exposure allow list, and the logfile endpoint simply streams the file that only exists if you configured a file name at boot. Boot does not watch logback.xml for changes, levels are mutable at runtime, and no custom appender is required." },
    { d: "Spring_Boot_Async_Scheduling", n: "proxy", q: "Why does an @Async method sometimes appear to run synchronously?", opts: ["It is invoked from inside the same class, so the call bypasses the async proxy and runs on the caller's thread; private and final methods cannot be advised either", "Async only works on classes annotated @Service", "Async requires @EnableAsync on the calling class", "Async only works for void methods"], a: 0, e: "@Async is advice on a proxy, so internal calls never reach it - the tell is that the work is fast and the caller's thread was busy for the whole duration. @EnableAsync belongs on a configuration class, and CompletableFuture or Future return values are supported as well as void. The fix is the same self-invocation workaround you already know from transactions." },
    { d: "Spring_Boot_Async_Scheduling", n: "executor", q: "You add @Async with no custom executor. What actually runs the task, and what is the risk under load?", opts: ["A SimpleAsyncTaskExecutor that creates a thread per task with no bound, so bursts turn into memory pressure or thread exhaustion", "A fixed pool sized to the number of CPUs", "The Tomcat request thread pool, so the endpoint still blocks", "A single-threaded scheduler shared with @Scheduled"], a: 0, e: "Boot only auto-configures a TaskExecutor for @Async when the application provides one (a bean named taskExecutor, or any Executor), otherwise the uncapped default is used. A bounded pool with a bounded queue and an explicit rejection policy is the difference between shedding load and an outage. Nothing runs on the request thread by default, and single-threaded behaviour belongs to @Scheduled." },
    { d: "Spring_Boot_Async_Scheduling", n: "taskdecorator", q: "An async task logs a different traceId and the current user is null. What is the fix?", opts: ["Add a TaskDecorator (or Micrometer context propagation with a ContextSnapshot) that copies MDC, the SecurityContext and RequestContextHolder into the worker thread and clears them afterwards", "Switch to @Async(proxyMode = DIRECT) so it runs on the caller thread", "Set spring.jpa.open-in-view=false", "Catch and rethrow the exception inside the task"], a: 0, e: "Thread-locals do not follow you to another thread: a TaskDecorator is the supported hook to capture and replay MDC, the SecurityContext and the servlet request attributes, and it must clean up so pooled threads do not leak state into the next task. DIRECT mode makes execution synchronous, which is exactly what you want in tests, not in production. Open-in-view and exception handling are unrelated." },
    { d: "Spring_Boot_Async_Scheduling", n: "scheduler", q: "What does @Scheduled use by default, and what changes if you define a TaskScheduler bean?", opts: ["A single-threaded scheduler, so one slow job delays every other job; defining a TaskScheduler bean (or spring.task.scheduling.pool.size) replaces it with a pool", "A pool sized to the CPU count, always", "The @Async executor, always", "A new JVM per job"], a: 0, e: "The default is a one-thread scheduler, which is why 'my cron ran late' is such a common report and why a blocking job silently postpones everything else. Supplying a TaskScheduler gives you a pool and enables CronTrigger, FixedDelayTrigger and the reactive variant per method. @Async is a separate execution path that shares nothing with the scheduler except the possibility of a shared bean." },
    { d: "Spring_Boot_Async_Scheduling", n: "lock", q: "Three replicas each run a @Scheduled(cron) job that charges cards. What is the production-safe design?", opts: ["A distributed lock (ShedLock on a shared store, or a single elected consumer) plus an idempotency key, so the job runs once per schedule even across restarts and clock skew", "Nothing - the scheduler coordinates replicas", "Use fixedDelay instead of cron so replicas stagger", "Run the job only on the pod with the lowest IP"], a: 0, e: "Kubernetes schedules nothing: every replica fires the same cron on its own clock, so you get three charges. A lock prevents overlap; idempotency handles the harder case where the lock holder dies after doing the work but before recording it. Neither fixedDelay nor a naming convention solves it - the alternative is a dedicated worker deployment or a leader-elected consumer." },
    { d: "Spring_Boot_Async_Scheduling", n: "custompool", q: "A ThreadPoolTaskExecutor is configured with corePoolSize 4, maxPoolSize 8, queueCapacity 2 and AbortPolicy. A burst of 30 tasks arrives. What happens?", opts: ["All 30 run eventually, because the queue grows to absorb the burst", "4 threads start, 2 tasks wait in the queue, 4 more threads are created once the queue is full, and everything after that is rejected with RejectedExecutionException", "8 tasks run in parallel and the rest wait in the queue", "The executor silently discards anything past the 8th task, with no exception"], a: 1, e: "A Java executor fills core threads, then queues up to capacity, then grows toward max, and only then rejects, so with this configuration 10 tasks are held and the rest fail fast. An unbounded queue would swallow the whole burst instead of growing to max, and the default policy throws rather than silently discarding." },
    { d: "Spring_Boot_Async_Scheduling", n: "executor", q: "You define two ThreadPoolTaskExecutor beans, reportsExecutor and mailExecutor, and want a particular method dispatched to reportsExecutor. What do you write?", opts: ["@Async(executor = \"reportsExecutor\") on the method, which is the only supported selector", "@Async on the method plus a @Qualifier annotation on the enclosing class", "@Async(\"reportsExecutor\") on the method, where the default attribute is the name of the executor bean", "@Async on the interface method only, because annotations are resolved from the proxy interface"], a: 2, e: "The default attribute of @Async holds the executor bean name, so that one annotation is the whole mechanism. There is no executor attribute, @Qualifier does not apply to async dispatch, and the annotation belongs on the invoked method rather than being resolved through an interface." },
    { d: "Spring_Boot_Async_Scheduling", n: "exchandler", q: "A void @Async method throws IllegalArgumentException and the caller sees nothing in its logs or response. Where did the exception go?", opts: ["It was propagated back through the proxy and rethrown in the request thread", "Spring caught it and retried the method until it succeeded", "It was swallowed by the executor's rejection policy, so the method never ran", "It was handed to the AsyncUncaughtExceptionHandler, whose default implementation only logs it, which is why you register your own handler or return a Future"], a: 3, e: "With no return value there is no channel back to the caller, so Spring forwards the throwable to an AsyncUncaughtExceptionHandler and the default one just logs. Nothing is rethrown or retried, and a rejection would mean the task never started rather than failed after starting." },
    { d: "Spring_Boot_Async_Scheduling", n: "caller", q: "A controller starts a report job with @Async and must know when it finished and catch its failure. What should the async method return?", opts: ["CompletableFuture<Report> or Future<Report>, so the caller can compose or block and failures surface as a wrapped ExecutionException", "void, with the controller polling a static flag for completion", "long, the id of the queued task, so the caller can look the result up later", "Thread, so the controller can join on the pool thread that ran the job"], a: 0, e: "A Future-typed return value is the supported way for a caller to observe an async result, giving both completion and exception propagation through ExecutionException. A void method plus a static flag is ad hoc and hides failures, returning a task id just moves the wait elsewhere, and the Thread object carries no result." },
    { d: "Spring_Boot_Async_Scheduling", n: "scheduler", q: "A cleanup job takes 10 minutes and you want the next run to start 5 minutes after the previous one finished. Which setting does that, and what does the alternative do?", opts: ["fixedRate = 300000, because fixedRate measures the gap between one run ending and the next starting", "fixedDelay = 300000, which counts from the completion of one run to the start of the next, whereas fixedRate counts from each start time so an overrunning job makes the next run fire as soon as the current one ends", "Either, because Spring Boot converts both settings into the same trigger internally", "A cron expression of */5 * * * * *, because intervals longer than a minute are unsupported"], a: 1, e: "fixedDelay is measured end-to-start, which is exactly the cadence you described, while fixedRate is start-to-start and therefore fires immediately after an overrunning job completes. Boot does not normalise the two settings into one, and cron accepts ordinary intervals just fine." },
    { d: "Spring_Boot_Async_Scheduling", n: "trigger", q: "A billing job must run at 03:00 on the first day of every month in Europe/Berlin, including when the clocks change. How do you express it?", opts: ["@Scheduled(cron = \"0 0 3 1 * *\", timezone = \"CET\"), because the attribute is spelled timezone", "@Scheduled(fixedRate = 2592000000) with a day-of-month check inside the method", "@Scheduled(cron = \"0 0 3 1 * *\", zone = \"Europe/Berlin\"), so the run stays pinned to that zone regardless of the server's default", "@Scheduled(cron = \"0 0 3 1 * *\") with no zone, because Boot pins cron evaluation to UTC by default"], a: 2, e: "Spring's cron attribute takes a zone attribute holding a ZoneId name, so the schedule stays anchored to Europe/Berlin even if the container runs in another timezone. The attribute is spelled zone rather than timezone, a fixed-rate interval drifts away from calendar boundaries, and leaving zone unset would let the JVM's default zone decide." },
    { d: "Spring_Boot_Async_Scheduling", n: "scheduler", q: "Three @Scheduled methods share Boot's default scheduler and one of them takes 30 minutes. What is observed in production?", opts: ["Each scheduled method gets its own thread, so the long one cannot affect the others", "Spring Boot fails at startup with a concurrency configuration error", "The long job is cancelled after a default five-minute timeout", "The other scheduled methods are delayed until the long job finishes, because Boot auto-configures a single-threaded scheduler unless you provide your own TaskScheduler"], a: 3, e: "The auto-configured scheduler uses one thread for every @Scheduled method in the context, so a long run blocks everything queued behind it. Boot does not allocate a thread per method, nothing fails at startup, and there is no default timeout that cancels running work." },
    { d: "Spring_Boot_Async_Scheduling", n: "contextprop", q: "A @Transactional service method hands the real work to an @Async method that is also annotated @Transactional. What happens to the transaction?", opts: ["The async method runs on a pool thread where the caller's transaction is not bound, so it opens its own new transaction and the caller's commit does not cover that work", "The async method joins the caller's transaction, because propagation follows the logical call rather than the thread", "Spring rejects the configuration at startup, because @Async and @Transactional cannot be combined", "The call is forced to run synchronously so both annotations share one transaction"], a: 0, e: "Transaction state is bound to the current thread, and async dispatch moves the work to a pool thread where that binding is gone, so the annotations there start a fresh transaction. Nothing forbids combining the two, propagation never crosses threads, and the dispatch does not become synchronous just because a transaction is open." },
    { d: "Spring_Boot_Async_Scheduling", n: "lock", q: "You adopt a database-backed scheduler lock with lockAtMostFor = PT5M, but one run takes 20 minutes. What happens?", opts: ["The job is paused for 15 minutes and then resumes, because the lock blocks the thread", "The lock expires while the job is still running, so another replica can acquire it and the job runs twice concurrently", "The job throws LockException the moment the lease elapses", "Nothing changes, because lockAtMostFor is only advisory metadata"], a: 1, e: "lockAtMostFor is a lease that guarantees the lock is released even if the owner dies, so a run longer than the lease hands the lock to the next scheduler while the first is still executing. It never pauses or kills the running job, and it is enforced rather than merely advisory." },
    { d: "Spring_Boot_Async_Scheduling", n: "custompool", q: "You configure a ThreadPoolTaskExecutor with corePoolSize 5 and maxPoolSize 20, but a thread dump never shows more than 5 threads. Why?", opts: ["Spring clamps every executor to the number of CPU cores regardless of configuration", "The executor bean was never registered, so tasks ran on Boot's single-threaded fallback", "With the default unbounded queue, work waits as soon as the core threads are busy, so the pool never grows toward maxPoolSize", "maxPoolSize applies only to @Scheduled methods, not to @Async dispatch"], a: 2, e: "A pool only grows past its core size when the queue is full, and Spring's default queue is unbounded, so the extra capacity is dead configuration. Boot does not silently clamp the pool to core size, a working executor obviously has threads, and maxPoolSize belongs to task executors rather than the scheduler." },
    { d: "Spring_Boot_Messaging", n: "outbox", q: "Why write the message into an outbox table in the same transaction as the order instead of publishing from @Transactional code?", opts: ["Because the data change and the message must commit atomically - publishing inside the transaction can send before the commit (consumer sees nothing) or after a rollback (ghost event)", "Because brokers cannot be called inside a transaction", "Because JPA forbids network calls within a transaction", "Because the outbox is faster than direct publishing"], a: 0, e: "This is the dual-write problem: you cannot atomically commit to a database and to a broker. The outbox turns the business change plus an intent record into one atomic commit, and a separate relay publishes and marks rows as sent. The relay is at-least-once, so consumers must be idempotent - the outbox relocates the failure rather than abolishing it." },
    { d: "Spring_Boot_Messaging", n: "relay", q: "What does the outbox relay need to get right, and what does it trade away?", opts: ["Publish at least once (publish then mark, or mark then publish), with retries, backoff and a dead-letter path; the cost is possible duplicates and a small publish delay", "Exactly-once delivery, guaranteed by the database commit", "No duplicates, because rows are deleted after publishing", "Immediate delivery, because it reuses the business transaction's connection"], a: 0, e: "Any ordering of 'publish' and 'mark sent' leaves a failure window, so the honest guarantee is at-least-once plus idempotent consumers, with visibility-timeout-style retries and alerting on the oldest unsent row. Exactly-once across a database and a broker is not something a commit can provide. The relay is deliberately a separate step, which also gives you a natural place to add tracing and backpressure." },
    { d: "Spring_Boot_Messaging", n: "consumer", q: "A consumer receives the same order.created event twice after a relay retry. What makes the handler safe?", opts: ["An idempotency key: a unique constraint on the message id (or a processed-messages table) written in the same transaction as the effect, so the second delivery is a no-op", "Manual acknowledgement with autoAck = true", "Making the listener method readOnly", "Raising the broker's max poll interval"], a: 0, e: "Under at-least-once delivery, dedupe has to be enforced where the effect happens, atomically with it - a unique insert that fails means 'already done'. A business key such as the order id is often better than a transport id, because a redelivery may carry a new message id. Auto-acknowledge makes things worse, and readOnly concerns transaction semantics, not duplicates." },
    { d: "Spring_Boot_Messaging", n: "sideeffect", q: "A listener makes a slow HTTP call and then updates state. Which design detail deserves the most scrutiny?", opts: ["When the offset is acknowledged: long work in the listener holds the partition, so retries and rebalancing stall - take a pointer, ack, and do the work asynchronously, or split into a fast handler plus a queue", "The JSON serializer, because slow calls always mean a bad serializer", "The topic's partition count, which must equal the consumer thread count", "Whether the listener is @Transactional"], a: 0, e: "Consumer lag is a function of how long you hold the offset, so an external call inside the listener is the classic throughput ceiling. Partitions and threading are real tuning concerns but not the cause of stalled progress. @Transactional on a listener is legitimate and only gives atomic work-plus-offset when the container supports transaction-aware acknowledgement; otherwise you are at-least-once again." },
    { d: "Spring_Boot_Messaging", n: "client", q: "Order events must be consumed in creation order for a given order while other orders are processed in parallel. What should the producer set as the Kafka message key?", opts: ["The order id, so all events for one order land in a single partition", "A new UUID per message, to spread load evenly across partitions", "A constant key such as \"orders\", so every record shares one key", "The partition number, chosen by the producer before sending"], a: 0, e: "Kafka only guarantees order inside a partition, so keying by order id sends every event for that order to one partition and keeps them ordered. A UUID key scatters those events across partitions and destroys the guarantee, and the key never names a partition directly." },
    { d: "Spring_Boot_Messaging", n: "controller", q: "A controller saves an order and calls kafkaTemplate.send() inside the same @Transactional method. The send succeeds, then a later flush fails and the transaction rolls back. What can a consumer now see?", opts: ["Nothing unusual, because Kafka enlists in the same transaction and aborts the send", "An order.created event for an order that was never committed", "No event at all, because send() is undone when the transaction rolls back", "The event with an empty payload, since the entity was never flushed"], a: 1, e: "Kafka does not join the database transaction, so a send that succeeded stays on the broker even when the database rolls back — the phantom-event half of the dual-write problem. The outbox closes both gaps because the row only becomes visible to the relay when the very same transaction commits." },
    { d: "Spring_Boot_Messaging", n: "service", q: "A service method calls saveOrder() in its own transaction, commits, and then calls writeOutboxRow() in a second transaction. Which failure is still possible?", opts: ["The second transaction commits first, leaving an outbox row with no order", "Both rows roll back together, because the transaction manager spans both calls", "The process dies between the two commits, leaving an order with no outbox row", "Neither — two sequential commits give the same guarantee as one combined commit"], a: 2, e: "Only one local transaction writing both rows guarantees all-or-nothing, so a crash in the gap leaves an order that will never be published. The outbox row cannot commit first because the order commit happens before it, and a crash cannot undo a row that already committed." },
    { d: "Spring_Boot_Messaging", n: "db", q: "A relay must rebuild a routable broker message from an outbox row with no other context. Which set of columns is the minimum it needs?", opts: ["Payload, consumer group name, and target partition", "Aggregate id, row version, and the consumer's offset", "Event type, target topic, and the consuming service name", "Aggregate id, event type or target topic, payload, and creation timestamp"], a: 3, e: "The relay needs the key, the routing information, the body, and a timestamp for ordering and retention. Consumer groups, partitions and offsets exist only after the broker accepts the record, and the consuming service's name is not what routes it." },
    { d: "Spring_Boot_Messaging", n: "outbox", q: "The relay publishes an outbox row to the broker, then the JVM is killed before the row is marked published. What happens when the relay restarts?", opts: ["The row is published a second time, so consumers must tolerate duplicates", "The row is marked sent anyway, because the broker confirmed the first publish", "The row is discarded, since an already-sent row is invalid on restart", "The database restores the row from its write-ahead log and skips it"], a: 0, e: "The relay cannot know whether the send reached the broker, so on restart it resends and the system stays at-least-once rather than exactly-once. That is precisely why the consumer needs an idempotency key or dedup store — no database mechanism marks the row as already delivered." },
    { d: "Spring_Boot_Messaging", n: "relay", q: "Compared with a polling relay that queries the outbox every few seconds, what does a change-data-capture relay such as Debezium actually change?", opts: ["It guarantees exactly-once delivery, so consumers can skip idempotency", "It removes polling latency and repeated table queries, at the cost of managing replication slots and WAL growth", "It removes the outbox table, because CDC can read the business table directly", "It requires the outbox to live in a different database from the business tables"], a: 1, e: "CDC tails the write-ahead log, so new outbox rows reach the broker almost immediately without hammering the table with polls, but you now own connectors, replication slots and WAL retention. Delivery stays at-least-once so idempotent consumers are still required, and the outbox table remains essential because the business row does not carry the event payload." },
    { d: "Spring_Boot_Messaging", n: "broker", q: "Two consumers join the same group for the order topic. How are partitions assigned, and what ordering guarantee survives?", opts: ["Both consumers receive every partition, and ordering is lost after the rebalance", "One consumer owns all partitions until it fails, then the other takes over", "Partitions are split between them, and order is still guaranteed inside each partition", "Partitions are duplicated to both, and the broker merges results by timestamp"], a: 2, e: "In a consumer group each partition has a single owner at a time, so a rebalance transfers partitions rather than copying them. Ordering is a per-partition property, so keying by order id keeps one order's events ordered even while ownership moves between instances." },
    { d: "Spring_Boot_Messaging", n: "consumer", q: "A consumer instance is down for an hour while the topic retains data for seven days. What happens when it comes back?", opts: ["It restarts from the earliest offset and re-reads the whole topic", "It receives only new records, because the broker drops data published while it was down", "It cannot rejoin the group, because members are locked out after an hour offline", "It resumes from its committed offset and processes the backlog it missed"], a: 3, e: "Committed offsets are stored by the group coordinator, so a returning member continues exactly where it stopped, provided topic retention still covers the gap. Retention rather than downtime decides data loss, and nothing prevents a member from rejoining after a long absence." },
    { d: "Spring_Boot_Messaging", n: "handler", q: "A @KafkaListener throws an exception on every attempt for a single record. What is the default Spring Kafka behaviour?", opts: ["It retries a bounded number of times with backoff, then logs and skips the record so the partition keeps moving", "It blocks the partition forever, until the code is fixed and the consumer restarted", "It commits the offset on the first failure and hides the error from the logs", "It publishes the record to a dead-letter topic automatically, with no configuration"], a: 0, e: "The default error handler retries with backoff and then recovers by logging the failed record, so one poison message cannot stall the partition. It does not deadlock or silently swallow the failure, and a dead-letter topic only exists once you configure a publishing recoverer yourself." },
    { d: "Spring_Boot_Messaging", n: "sideeffect", q: "A listener updates a local row and then calls a slow external payment API. Why must the HTTP call happen outside the database transaction?", opts: ["The HTTP client throws IllegalStateException while a transaction is active", "An open transaction holds locks during a slow network call, and the API result cannot be rolled back with the row", "Spring Boot blocks outbound HTTP inside @Transactional methods for security reasons", "The transaction manager would try to commit the HTTP response as an outbox row"], a: 1, e: "A remote call inside a transaction stretches lock hold times and leaves the database unable to undo an outcome it never controlled — the payment either happened or it did not. The other options describe framework restrictions that Spring Boot does not actually impose." },
    { d: "Spring_Boot_Messaging", n: "db", q: "Where must the outbox table live if the business write and the message write have to be atomic?", opts: ["In a separate message database, so the two stores can be scaled independently", "In the same database but written by a background job that runs after the service returns", "In the same database as the business tables, so one local transaction covers both", "In the broker's own storage, so no extra table is needed"], a: 2, e: "Atomicity across the business row and the outbox row requires a single local transaction, which only works when both rows sit in the same database. A job that runs after the service returns is outside that transaction, so a crash between them still loses the message, and a broker-side table does not exist before the publish." },
    { d: "Spring_Boot_Deployment", n: "image", q: "Why ship a layered jar or an exploded jar on a distroless base, rather than one big fat image?", opts: ["The layered layout (BOOT-INF/classes plus BOOT-INF/lib) caches dependency layers across builds, so a code-only change pushes kilobytes instead of the whole jar; bootBuildImage produces an OCI image with those layers", "Layered jars start faster because the JVM skips verification", "Fat images cannot run on Kubernetes", "Layered jars remove the need for a JRE"], a: 0, e: "The layering exists for build caching and registry push size, which is where deploy time actually goes. The JVM still verifies, fat images run fine on Kubernetes, and you still need a JVM. For containers the usual next step is an exploded or layered jar on a minimal, non-root base image." },
    { d: "Spring_Boot_Deployment", n: "jvm", q: "What container-aware JVM sizing avoids being OOM-killed on a memory-limited pod?", opts: ["-XX:MaxRAMPercentage (with headroom for metaspace, code cache and direct buffers) so the heap scales with the cgroup limit, and a limit larger than the heap plus native memory", "-Xmx equal to the pod's memory limit", "-Xmx fixed at 8g regardless of the limit", "Nothing - the JVM sizes the heap from the container limit on its own"], a: 0, e: "MaxRAMPercentage is the intended mechanism under a cgroup limit, and native memory sits outside the heap - which is why a 512Mi limit with a 400Mi heap still gets killed. Setting -Xmx to the whole limit is the classic mistake. Exit code 137 with no Java OutOfMemoryError almost always means the cgroup limit was hit before the JVM could report a Java heap error." },
    { d: "Spring_Boot_Deployment", n: "probes", q: "A new pod warms a cache for 90 seconds and is killed at 40. Which fix is right, and what remains necessary?", opts: ["Add a startup probe (or raise its failureThreshold) so liveness is not evaluated until startup finishes; readiness must still stay false until warm-up completes", "Raise the liveness initialDelaySeconds to 90 and delete readiness", "Disable liveness permanently", "Sleep in the application's main method"], a: 0, e: "The startup probe exists for slow starts: while it is failing, liveness and readiness are not evaluated, and the pod gets a generous budget. Readiness still has to gate traffic separately, because 'started' is not 'ready'. Sleeping in main hides the problem from the orchestrator and slows every deploy, including the good ones." },
    { d: "Spring_Boot_Deployment", n: "graceful", q: "Which settings stop a rolling update from dropping in-flight requests, and what does the orchestrator need on top?", opts: ["server.shutdown=graceful with spring.lifecycle.timeout-per-shutdown-phase, plus a preStop sleep and a terminationGracePeriodSeconds longer than your longest request", "Increasing the replica count", "Setting readiness to false on shutdown", "Nothing - Kubernetes already drains connections"], a: 0, e: "Graceful shutdown stops accepting new requests and lets in-flight ones finish; the preStop sleep matters because endpoint removal and pod termination are not simultaneous, and the grace period must exceed your slowest request. Scaling up first narrows the window, and readiness-to-false alone still races the kill signal." },
    { d: "Spring_Boot_Deployment", n: "configsource", q: "How should a containerised Spring Boot app receive per-environment configuration?", opts: ["At runtime, as environment variables or mounted files, so one immutable image is promoted through environments; build-time baking turns any rollback into a rebuild", "Baked into application-prod.properties during the Docker build", "Hard-coded defaults in @ConfigurationProperties classes only", "Fetched from a mutable git branch at startup and never pinned"], a: 0, e: "One immutable image promoted through environments is the foundation of a rollback you can actually perform, and runtime configuration is the only thing that varies per environment. Baked properties make a rollback a rebuild and redeploy of everything, and no validation means a missing variable shows up in production. Pin what you depend on, and validate configuration at startup so the failure is immediate." },
    { d: "Spring_Boot_Deployment", n: "registry", q: "What is wrong with tagging your container image as latest and letting every environment pull whatever is newest?", opts: ["Deploys become non-reproducible and rollbacks impossible - you cannot name the version that is running; use immutable tags or digests", "Nothing, as long as the image is built in CI", "latest forces the registry to rebuild the image", "latest prevents layer caching"], a: 0, e: "The tag becomes the only piece of identity you have, and 'latest' is a moving pointer, so two pods of the same deployment can run different code and a rollback has no target. Immutable tags plus a digest reference, and promotion by digest through environments, are the standard answer. Layer caching is unrelated to the tag's meaning, and CI-built images still need identity." },
    { d: "Spring_Boot_Deployment", n: "cicd", q: "Your CI builds a layered jar and the Dockerfile copies dependency layers before the application layer. What does this buy you when only application code changed?", opts: ["Nothing — Docker rebuilds every layer whenever any file in the context changes", "The dependency layers are reused from cache, so only the thin application layer is rebuilt", "The JVM starts faster, because dependencies are unpacked directly onto the classpath", "The image becomes smaller, because dependencies are shared between images"], a: 1, e: "Layered jars put rarely changing dependencies in earlier layers, so Docker's content-addressable cache keeps them and only the final application layer is rebuilt after a code change. The win is build time and registry transfer of unchanged layers — image size and JVM startup are essentially unaffected." },
    { d: "Spring_Boot_Deployment", n: "image", q: "What do Spring Boot buildpacks (bootBuildImage) give you that a hand-written Dockerfile does not?", opts: ["A much smaller image, because buildpacks compress the jar during the build", "A fixed base image digest that you choose for every environment", "A maintained, patched base image and JVM lifecycle handling without you writing the Dockerfile", "In-image database migrations, since the buildpack bundles Flyway automatically"], a: 2, e: "Buildpacks supply a curated, frequently patched run image and handle JVM defaults and lifecycle concerns, so you never maintain the Dockerfile yourself. You give up fine-grained control such as pinning an exact digest, no migration tooling is bundled, and image size is not the main difference." },
    { d: "Spring_Boot_Deployment", n: "registry", q: "Which image reference guarantees that every environment runs exactly the bytes you tested?", opts: ["acme/orders:1.4.2, because semantic versions are never re-pushed", "acme/orders:stable, because only release builds receive that tag", "acme/orders:prod, because production tags are protected by policy", "acme/orders@sha256:9f2c..., because a digest is content-addressed and immutable"], a: 3, e: "A digest is a hash of the image content, so changing any layer produces a different digest and the reference can never silently point elsewhere. Tags — even release or protected ones — are mutable pointers that someone can re-push, which is what makes them unsafe as a deploy reference." },
    { d: "Spring_Boot_Deployment", n: "orchestrator", q: "A Deployment with 5 replicas rolls out with maxUnavailable 1 and maxSurge 2. What do those two values control?", opts: ["How many old pods may be terminated early and how many extra pods may run above the target during the update", "How many pods must pass readiness before the rollout starts, and how long each may take to start", "How many crash-looping pods are tolerated before the rollout is automatically rolled back", "The CPU and memory ceiling applied to each pod while it is starting"], a: 0, e: "maxUnavailable bounds how far the available count may drop below five, while maxSurge allows up to two pods above the target so new ones can start before old ones are killed. Readiness thresholds, rollback policy and resource ceilings belong to probes, rollout history and resource limits, not to these two fields." },
    { d: "Spring_Boot_Deployment", n: "configsource", q: "A team bakes the production database password into an ENV instruction in the Dockerfile. What is the main problem with this?", opts: ["The JVM caches environment variables, so the password cannot be rotated without a rebuild", "The secret is stored in the image configuration and layers, so anyone who can pull the image can read it", "Spring Boot refuses to read passwords from environment variables outside development", "The container will not start, because ENV instructions are ignored by OCI runtimes"], a: 1, e: "Values set at build time are recorded in the image metadata, so anyone with pull access can extract them with docker inspect or docker history. Rotation then also forces a rebuild and re-push, which is why secrets belong in a runtime store such as a mounted file, a secret manager or the orchestrator's secret objects." },
    { d: "Spring_Boot_Deployment", n: "jvm", q: "A container has a 4Gi memory limit and the JVM is started with -Xmx4g. Why can the pod still be OOM-killed?", opts: ["The JVM ignores -Xmx when running in a container and sizes the heap from the host machine", "Kubernetes enforces the limit only after a grace period, so the process is always killed once", "The 4Gi limit covers heap, metaspace, thread stacks and native memory, so the total passes it", "-Xmx4g is invalid inside a container, so the JVM silently reverts to a 512Mi heap"], a: 2, e: "The cgroup limit covers the whole process — heap plus metaspace, code cache, thread stacks and native buffers — so a heap alone equal to the limit guarantees an overrun. Leaving headroom with MaxRAMPercentage, or a heap set well below the limit, is what keeps the total inside the boundary." },
    { d: "Spring_Boot_Deployment", n: "pod", q: "A pod declares resources.requests.memory = 512Mi and resources.limits.memory = 2Gi, and the only candidate node has 400Mi free. What happens?", opts: ["The pod is scheduled there, because only limits matter for placement", "The pod starts and is throttled down to 400Mi by the kubelet", "The scheduler rounds the request down to fit and starts the pod anyway", "The pod stays Pending, because placement checks free capacity against requests"], a: 3, e: "The scheduler reserves capacity using requests, so a 512Mi request cannot be placed on a node with 400Mi free no matter how large the limit is. The limit is only a runtime ceiling for throttling or OOM-killing, and the scheduler never shrinks a request to force a fit." },
    { d: "Spring_Boot_Deployment", n: "probes", q: "A liveness probe fails whenever the database blips, restarting containers that are otherwise healthy. What does this reveal about the probe design?", opts: ["Liveness must not depend on downstream systems — the database check belongs in readiness", "The readiness probe should be removed so the pod keeps receiving traffic during the outage", "The probe should use TCP instead of HTTP, since HTTP probes time out under load", "The startup probe should be deleted, because it only delays liveness checks by design"], a: 0, e: "Liveness answers whether the process itself is broken and needs a restart, so coupling it to a database outage turns a transient dependency failure into a restart loop. Readiness is the correct home for dependency checks because failing it merely removes the pod from Service endpoints until the database returns." },
    { d: "Spring_Boot_Deployment", n: "db", q: "Four replicas start during a rolling deploy, each configured with spring.jpa.hibernate.ddl-auto=update. What is the main risk?", opts: ["Each replica provisions its own private database, so writes are not shared", "Concurrent schema changes race each other, and a half-applied migration can leave the schema inconsistent", "JPA refuses to start when more than one instance tries to own the schema", "The pods are OOM-killed, because DDL statements spike memory past the limit"], a: 1, e: "Several processes running DDL at once can interleave statements, so the schema may end up partially migrated with no automatic rollback. Schema changes belong in a single controlled step — a migration tool run once as a pre-deploy job, or at least one that takes a lock — rather than in every replica's startup path." },
    { d: "Spring_Boot_Testing_Slices", n: "unit", q: "What does a plain JUnit + Mockito test give you that a Spring test does not?", opts: ["Speed and isolation - no context, no auto-configuration, no database; the tradeoff is that it verifies interactions, not wiring or real behaviour", "Coverage of auto-configuration and the filter chain", "Real SQL against a real schema", "Automatic transaction rollback between tests"], a: 0, e: "A unit test is fast because it skips the container, but that is also its limit: it cannot catch a missing bean, a bad property or a broken query. It also tempts you into asserting mock interactions, which pins implementation rather than behaviour. The rule of thumb: test behaviour, mock at your own boundaries." },
    { d: "Spring_Boot_Testing_Slices", n: "webmvc", q: "What does @WebMvcTest actually load, and what must you provide?", opts: ["Only the web slice - @Controller, @ControllerAdvice, filters, WebMvcConfigurer - with other beans supplied as mocks (for example @MockitoBean) and no database", "The whole context including repositories and a real datasource", "Nothing - a plain unit test with a mocked MVC layer", "Only Jackson, with the dispatcher excluded"], a: 0, e: "The slice limits scanning to web-layer annotations and auto-configures MVC infrastructure, so a request exercises real handler mapping, validation, serialization and exception handling in milliseconds - while every collaborator is yours to supply. That combination is the point: it catches broken mappings and wrong status codes that a full context test only finds slowly. Everything below the web layer, including transaction behaviour, is out of scope." },
    { d: "Spring_Boot_Testing_Slices", n: "datajpa", q: "What does @DataJpaTest give you by default, and what will surprise you?", opts: ["A JPA slice with an embedded database, auto-configured repositories and a test transaction that rolls back - so propagation behaves differently than in production and H2 is not your real engine", "A real MySQL container running your production dialect", "No transaction, so each save commits immediately", "The full application context including your services"], a: 0, e: "It is a deliberately narrow slice: repositories, EntityManager and an embedded DB, with rollback between tests. Two surprises follow - dialect-specific SQL is never executed, and a test that opens its own transaction (REQUIRES_NEW, or TestTransaction) commits data the rollback never undoes, so tests interfere. Use Testcontainers for what only a real database can tell you." },
    { d: "Spring_Boot_Testing_Slices", n: "testcontainers", q: "What does a Testcontainers-managed database buy you over @DataJpaTest with H2?", opts: ["The real engine, dialect, collation, locking and migration behaviour, so a test that passes cannot hide a dialect-only failure until production", "Much faster tests, because containers start in milliseconds", "Automatic rollback between tests", "No need for a test profile"], a: 0, e: "Fidelity is the entire point: H2 in PostgreSQL compatibility mode is not PostgreSQL, and that gap is exactly where production-only failures live. With @ServiceConnection Boot wires the datasource URL for you, and containers are slower, not faster - so they belong in a small integration suite. Rollback still comes from your own @Transactional test." },
    { d: "Spring_Boot_Testing_Slices", n: "mvc", q: "A test builds MockMvc with standaloneSetup(new OrderController()) and calls mockMvc.perform(get(\"/orders/1\")). What is actually executed?", opts: ["A real Tomcat server on a random port, contacted over a socket", "The full DispatcherServlet with every auto-configured filter and converter in the application", "The controller in-process, with no servlet container and no network involved", "Only the controller method, bypassing argument resolvers and message converters"], a: 2, e: "Standalone MockMvc wires a minimal DispatcherServlet in-process, so requests travel as objects rather than bytes over TCP, which is why it is fast. It still runs argument resolvers and message converters, but it never starts Tomcat — webAppContextSetup is what pulls in the full application context instead." },
    { d: "Spring_Boot_Testing_Slices", n: "webmvc", q: "A @WebMvcTest for a secured controller suddenly returns 401 for a test that passed before security was added. What is the correct fix?", opts: ["Switch to @SpringBootTest, because only a full context applies security", "Disable Spring Security for the slice with a property, permanently", "Move the test to a plain JUnit test that constructs the controller by hand", "Annotate the test with @WithMockUser so MockMvc sends an authenticated principal"], a: 3, e: "@WebMvcTest auto-configures Spring Security, so MockMvc requests pass through the filter chain and an anonymous caller is rejected with 401. @WithMockUser, or requestBuilder.with(.user(...)), supplies the principal those rules expect; moving to @SpringBootTest or disabling security only hides the real behaviour." },
    { d: "Spring_Boot_Testing_Slices", n: "jsonb", q: "Which test belongs in a @JsonTest slice?", opts: ["A test asserting the serialized JSON shape of a DTO through @JsonTester", "A test asserting the HTTP status returned by a @RestController", "A test persisting an entity and verifying the generated id", "A test stubbing a downstream RestClient call with MockRestServiceServer"], a: 0, e: "@JsonTest loads only the Jackson auto-configuration and @JsonTester, so it is scoped purely to serializing and deserializing your objects. Controller status codes need @WebMvcTest, persisted ids need @DataJpaTest, and stubbing outbound HTTP is the job of @RestClientTest." },
    { d: "Spring_Boot_Testing_Slices", n: "restclient", q: "A service uses RestClient to call a partner API. Which test proves the outgoing request has the right URL, headers and body without any network traffic?", opts: ["A @WebMvcTest that replaces the partner with @MockBean", "A @RestClientTest binding a MockRestServiceServer to the client and declaring expectations", "A @DataJpaTest that verifies the response payload after it is saved", "An @SpringBootTest that points the base URL at localhost"], a: 1, e: "@RestClientTest loads just the RestClient infrastructure and lets MockRestServiceServer intercept the real request, so you can assert method, URI, headers and body exactly. A mocked bean never exercises the client, and pointing at localhost still opens a real socket and needs a server listening." },
    { d: "Spring_Boot_Testing_Slices", n: "datajpa", q: "@DataJpaTest keeps replacing your datasource with an embedded database even though the project defines a Testcontainers one. How do you make the slice use the real datasource?", opts: ["Add @Transactional(propagation = Propagation.NOT_SUPPORTED) to bypass the default", "Set spring.jpa.database-platform to the container's dialect in application.properties", "Annotate the test with @AutoConfigureTestDatabase(replace = Replace.NONE)", "Switch to @SpringBootTest, which never touches the datasource configuration"], a: 2, e: "The slice swaps in an embedded database with Replace.AUTOMATIC by default, so Replace.NONE is the switch that keeps whatever your configuration defines — including a Testcontainers-managed one. Propagation and dialect settings do not affect that replacement, and @SpringBootTest is a far heavier route to the same datasource." },
    { d: "Spring_Boot_Testing_Slices", n: "testcontainers", q: "A Testcontainers test starts a PostgreSQL container. In Spring Boot 3.3, which mechanism wires its connection details into the DataSource without hand-written property code?", opts: ["A @DynamicPropertySource method that calls container.getHost() and container.getPort()", "A testcontainers.yml file that Spring Boot reads automatically", "@ServiceConnection on the container field, picked up by Boot's connection detail support", "A @TestConfiguration that copies host and port into @Value fields"], a: 2, e: "@ServiceConnection lets Spring Boot discover the running container's connection details and expose them as connection detail beans, so no boilerplate is needed. @DynamicPropertySource still works but is the manual version, and a @TestConfiguration with @Value fields has to be imported by hand and bypasses Boot's abstraction entirely." },
    { d: "Spring_Boot_Testing_Slices", n: "integration", q: "@SpringBootTest is configured with webEnvironment = RANDOM_PORT. What does the test actually start?", opts: ["The full application context plus a real embedded web server listening on a random port", "Only the web layer, with MockMvc standing in for the server as in @WebMvcTest", "The application context without any server, so tests must call beans directly", "The remote server from the main profile, addressed over the network"], a: 0, e: "RANDOM_PORT boots the entire context and starts embedded Tomcat on an ephemeral port, so TestRestTemplate calls travel over real HTTP — which is what makes it an integration test. Omitting the server gives webEnvironment = MOCK, while @WebMvcTest deliberately loads only a thin slice of the application." },
    { d: "Spring_Boot_Testing_Slices", n: "e2e", q: "A team wants every pull request validated by a full end-to-end suite covering login, checkout and payment. What is the main cost of that choice?", opts: ["The suite proves nothing that the lower test layers do not already prove", "The suite is slow and flaky enough to erode trust, while most coverage would arrive faster from unit and slice tests", "End-to-end tests cannot be written against Spring Boot applications at all", "The tests must be rewritten each release, because selectors change daily"], a: 1, e: "End-to-end tests do prove real wiring and sequencing, but they are the slowest and flakiest layer, so running a large suite on every change delays feedback and trains people to ignore red builds. The pyramid argues for a handful of high-level scenarios with most coverage in fast unit and slice tests that fail just as precisely." },
    { d: "Spring_Boot_Testing_Slices", n: "mocks", q: "Inside a @SpringBootTest, why use @MockBean for a service instead of a plain Mockito @Mock field?", opts: ["Because plain @Mock objects cannot be created outside a Mockito extension", "Because @MockBean is faster, since it avoids starting the Spring context at all", "Because a plain @Mock automatically replaces the real bean in the ApplicationContext", "Because the ApplicationContext must contain the mock so every other bean injects it"], a: 3, e: "Any component autowiring that collaborator needs the mock to be the registered bean definition, which is exactly what @MockBean arranges (and it resets between tests). A plain @Mock exists only as a field in your test class, so the real service is still constructed and injected everywhere else." },
    { d: "Spring_Boot_Testing_Slices", n: "unit", q: "A pure pricing rule has four branches and no collaborators. Which test gives the fastest feedback while covering all four?", opts: ["An @SpringBootTest that loads the full context and calls the rule from a @Test method", "An @WebMvcTest that exposes the rule through a controller and asserts the response", "A @DataJpaTest that persists the inputs and reads the computed price back", "A JUnit 5 @ParameterizedTest with a @CsvSource of inputs and expected outputs"], a: 3, e: "The rule is pure, so a parameterized unit test covers every branch in one method with no context startup and no I/O — the fastest signal available. Wrapping it in a Spring context, an HTTP round trip or a database write adds seconds per test without testing anything extra about the rule itself." },
    { d: "Spring_Boot_Testing_Slices", n: "integration", q: "Two test classes use @SpringBootTest with identical configuration, yet the log shows only one \"Started\" line. Why?", opts: ["Spring caches the ApplicationContext and reuses it whenever the configuration is identical", "The second class is skipped, because JUnit runs only one @SpringBootTest per classpath", "JUnit's parallel executor merges the two contexts to save memory", "It is a logging bug — every test always builds a fresh context"], a: 0, e: "Spring caches contexts keyed by configuration — imports, properties, profile and so on — so identical setups pay for a full context only once and later tests autowire into the cached one. It is not a JUnit limit or a shared static field, and any difference in configuration forces a brand new context to be built." },
    { d: "Spring_Boot_AntiPatterns", n: "fieldinj", q: "Why is field injection with @Autowired a production liability?", opts: ["Dependencies are invisible in the signature, the object can be constructed with nulls, and testing needs a container or reflection instead of a plain new", "Field injection is not transactional", "Field injection prevents final fields", "Field injection breaks JSON serialization"], a: 0, e: "Constructor injection makes the dependency list part of the type, keeps fields final, and lets a unit test call new OrderService(repo) with no Spring at all. Field injection is also invisible to refactoring - you can add a dependency without touching a signature, so nobody reviews it. Transactions, Jackson and final fields are all red herrings here." },
    { d: "Spring_Boot_AntiPatterns", n: "checkedtx", q: "A @Transactional method throws a checked exception which you catch and log. What happens to the data?", opts: ["Nothing rolls back - the default rule only rolls back RuntimeException and Error, so partial work commits", "Everything rolls back, because the exception was logged", "Only statements after the exception roll back", "The transaction is suspended and retried"], a: 0, e: "The default rollback rule surprises people in production: a business failure expressed as a checked exception commits whatever succeeded. Annotate with rollbackFor = Exception.class, or use unchecked exceptions, and treat any swallowed exception inside a transaction as a review smell. Logging does not change transaction state, and there is no statement-level partial rollback." },
    { d: "Spring_Boot_AntiPatterns", n: "eagermany", q: "You make a @ManyToOne LAZY to fix a slow query and things get worse. What happened?", opts: ["The association is now loaded per row - often inside a loop or during serialisation - so a big join became an N+1 pattern", "LAZY associations cannot be loaded, so the query is retried forever", "LAZY requires an index, and adding it invalidated the plan", "Hibernate disabled the query cache"], a: 0, e: "LAZY is not a performance setting; it defers loading, and whoever dereferences it pays - usually once per row, sometimes after the session closed. The fix is to fetch the shape you actually need with a join fetch, an entity graph or a projection into a DTO. Retries, plan invalidation and the query cache are not the mechanism." },
    { d: "Spring_Boot_AntiPatterns", n: "longtx", q: "Why is a long-running @Transactional method dangerous in a service that also accepts uploads?", opts: ["It holds a pooled connection and row locks for the whole call - connection exhaustion, lock waits and replication lag; keep transactions short and do slow I/O outside them", "Long transactions are unsupported by JPA", "Long transactions disable the second-level cache", "Long transactions cannot be rolled back"], a: 0, e: "The transaction is the unit of atomicity, not the unit of work: everything inside it holds locks and a connection. A three-minute upload inside @Transactional means twenty concurrent uploads exhaust a pool of ten while every other request queues behind the lock. Do the I/O outside, wrap only the state change, and use compensation for the rest." },
    { d: "Spring_Boot_AntiPatterns", n: "notimeout", q: "A RestClient call to a partner service hangs and the whole service falls over. Which single change would have contained it?", opts: ["Explicit connect and read timeouts on the HTTP client, so the call fails fast and the thread returns to the pool", "A larger Tomcat thread pool", "More aggressive retries", "Making the call @Async"], a: 0, e: "Without timeouts a slow partner pins request threads indefinitely, and a small pool turns one dependency into a total outage. Timeouts plus a bounded retry budget, a circuit breaker and a bulkhead are the standard containment set. More threads just delays exhaustion, and async moves the problem to a pool you also have to bound." },
    { d: "Spring_Boot_AntiPatterns", n: "catchall", q: "A @RestControllerAdvice handles Exception.class and returns 500 with a generic message. What does it cost you?", opts: ["Every failure becomes an indistinguishable 500 - validation loses its 400, missing data loses its 404, and if the cause is not logged you have thrown away the only clue", "Nothing, as long as the message is generic", "It converts all errors into 200 with an error field", "Spring logs every exception twice"], a: 0, e: "The catch-all is what you add on day one and regret later: it flattens the status-code contract clients depend on, and swallowing the stack trace removes the only diagnostic you will get. Handle the specific exceptions, map them to meaningful statuses, log the unexpected ones at ERROR with the cause, and keep the catch-all for truly exceptional cases." },
    { d: "Spring_Boot_AntiPatterns", n: "privtx", q: "You put @Transactional on a private method that performs two repository writes, and the second write fails. Your database shows only the first write. Why?", opts: ["The annotation on a private method is never applied, so each repository call ran in its own transaction and committed independently", "Spring does proxy private methods via reflection, but rollback is skipped once the exception is caught", "The transaction applied, but private methods bypass the normal flush order so only the first statement persisted", "It worked as designed; partial writes come from a misconfigured connection pool"], a: 0, e: "Spring's proxy advice only intercepts public, advice-eligible methods, so a private method's @Transactional is silently ignored and the two writes were never in the same transaction. There is no reflective proxying of private methods, no flush-order anomaly, and a connection pool cannot produce a partial write on its own." },
    { d: "Spring_Boot_AntiPatterns", n: "nplus1", q: "Loading 200 orders each with an items collection issues 201 queries. Which change actually removes the extra round trips?", opts: ["Set hibernate.jdbc.batch_size to 50 so the extra selects are grouped into batches", "Fetch parents and children together with a single query, using an @EntityGraph or a JOIN FETCH in the JPQL", "Annotate the collection with @Transactional so all selects share one connection", "Raise the Hikari maximum pool size so the queries can run in parallel"], a: 1, e: "An N+1 is a query count problem, and the only real fix is collapsing the lookups into one fetch that returns both parents and children. Batch size groups writes rather than selects, sharing a connection does not reduce the number of statements, and a bigger pool just lets more storms run at once." },
    { d: "Spring_Boot_AntiPatterns", n: "mutableentity", q: "A @RestController returns the managed JPA entity directly and also binds request bodies onto it. What is the root problem, and the fix?", opts: ["Add @JsonIgnore to the id field so Hibernate can no longer track changes to the instance", "Change the relationship to FetchType.LAZY, which also stops the dirty checking", "Map the entity to a DTO before returning and bind requests to a separate command object, so no managed instance is ever driven by JSON", "Annotate the entity with @Immutable, which makes it safe to serialize and update"], a: 2, e: "Returning and binding managed entities lets Jackson write fields Hibernate is tracking, so dirty checking silently persists whatever the client changed. @JsonIgnore and lazy fetching do not stop change tracking, and an immutable entity would block the updates you legitimately need." },
    { d: "Spring_Boot_AntiPatterns", n: "blockingr2dbc", q: "A WebFlux handler annotated with @PostMapping calls a JPA repository that blocks on JDBC. What happens once a handful of requests are in flight?", opts: ["Startup fails, because JPA beans are not permitted in a reactive application", "It works normally, because WebFlux wraps every controller call in a boundedElastic scheduler", "The first request completes and the thread pool then deadlocks permanently", "The blocking call occupies an event-loop thread, so latency spikes and throughput collapses"], a: 3, e: "Reactive servers run handlers on a small fixed set of event-loop threads, and a blocking JDBC call pins one of them until the query returns. There is no startup failure, no automatic wrapping of your code in boundedElastic, and the result is a throughput collapse rather than a guaranteed deadlock." },
    { d: "Spring_Boot_AntiPatterns", n: "noprops", q: "API keys and feature flags are hard-coded as constants in a @Configuration class, so every environment needs a fresh build. What is the idiomatic Boot 3 fix?", opts: ["Move the values into profile-specific configuration (application-{profile}.yml plus environment variables or a secret store) so the same artifact can be promoted unchanged", "Wrap the constants in a static utility class so only one file differs between environments", "Read them from JNDI during class initialization so they resolve before Spring starts", "Keep them in code but guard each one with @Profile, redeploying a jar per environment"], a: 0, e: "Externalized, profile-based configuration is exactly what Boot's config data API exists for: one immutable artifact, different configuration per environment. A utility class or @Profile-guarded constants still force a rebuild per environment, and resolving secrets at class-init time merely moves the hard-coding earlier." },
    { d: "Spring_Boot_AntiPatterns", n: "selfinv", q: "CheckoutService.startOrder() calls its own reserveStock() method, and only reserveStock() carries @Transactional, so failed orders still leave stock reserved. Which single change guarantees the advice on reserveStock() takes effect?", opts: ["Add @Transactional to startOrder as well, since the call then happens inside a transaction", "Move reserveStock into a separate collaborator bean and call it through the injected reference", "Make reserveStock static, so the call no longer goes through this", "Switch the field injection of CheckoutService to constructor injection within the same class"], a: 1, e: "Only a call that crosses a proxy boundary reaches the advice, so a separate collaborator is the reliable fix. Annotating startOrder opens a transaction but still skips reserveStock's own advice, so its propagation, readOnly and timeout are lost, while static methods are never proxied and constructor injection does not change self-invocation at all." },
    { d: "Spring_Boot_AntiPatterns", n: "fieldinj", q: "You try to unit test OrderService with plain JUnit and Mockito, but its collaborators are field-injected. What is the immediate obstacle?", opts: ["Mockito cannot stub a field, so every collaborator must be replaced with a real implementation", "The class cannot be instantiated at all, because Spring only allows container-created instances of field-injected beans", "There is no constructor parameter to pass the mocks through, so you must either use ReflectionTestUtils or refactor to constructor injection", "JUnit refuses to run the test unless @SpringBootTest boots a full context and injects the fields"], a: 2, e: "Field injection gives you no seam to supply test doubles, so tests end up poking private fields reflectively or booting an entire Spring context just to construct the object. Mockito mocks interfaces regardless of how they are injected, the class remains directly instantiable, and plain JUnit runs happily without @SpringBootTest." },
    { d: "Spring_Boot_AntiPatterns", n: "catchall", q: "Your @RestControllerAdvice declares both handle(IllegalArgumentException ex) and handle(Exception ex). A controller throws IllegalArgumentException. Which handler runs?", opts: ["handle(Exception), because broad handlers are evaluated first as a safety net", "Neither, because Spring answers 400 without invoking your advice", "Both handlers, in sequence, with the second result overwriting the first", "handle(IllegalArgumentException), because Spring picks the most specific matching handler in the highest-precedence advice"], a: 3, e: "Handler selection walks the available methods and chooses the one whose parameter type is nearest to the thrown exception, after resolving advice precedence. The generic Exception method is only a fallback, both handlers never run for one exception, and Spring does not skip advice for an exception your advice can handle." },
    { d: "Spring_Boot_WebFlux", n: "mono", q: "What is the difference between Mono and Flux, and which do you use for a single entity lookup?", opts: ["Mono emits zero or one item and Flux zero or more; a single lookup returns Mono, and 'no result' is an empty Mono, not null", "Mono is single-threaded and Flux is multi-threaded", "Flux is blocking and Mono is non-blocking", "Mono is for Java and Flux is for Kotlin"], a: 0, e: "Mono and Flux are about cardinality, not threading - the threading framing is a persistent source of confusion in review. Model emptiness explicitly (empty Mono, or justOrEmpty) because a null inside a stream surfaces as a confusing NullPointerException, and remember the operator chain still runs on one thread unless you move it." },
    { d: "Spring_Boot_WebFlux", n: "webmvc", q: "Both spring-boot-starter-web and spring-boot-starter-webflux end up on the classpath. What does Boot do, and how do you choose?", opts: ["WebApplicationType resolves to SERVLET when both are present, so the app silently runs as MVC; exclude the starter you do not want, or set spring.main.web-application-type", "Startup fails because the two stacks are incompatible", "It picks reactive and logs a warning", "It starts two servers, one per stack"], a: 0, e: "Deduction prefers SERVLET whenever the servlet classes are present, so a stray web starter - often pulled in transitively by a reporting or admin dependency - quietly converts your reactive app into a blocking one with no error at all. Excluding the unwanted starter is best, because then the classpath tells the truth about what you run." },
    { d: "Spring_Boot_WebFlux", n: "r2dbc", q: "What does R2DBC give you over JDBC, and what does it not give you?", opts: ["A non-blocking Reactive Streams driver with a connection pool and backpressure, but no JPA, no second-level cache and no bytecode-enhanced lazy loading", "The full JPA feature set including entity graphs and detached entities", "Automatic batching identical to Hibernate's", "Transparent blocking, so JPA repositories can be called from it"], a: 0, e: "R2DBC is a driver-level API: repositories, transactions and object mapping are separate concerns you choose, and Hibernate's mature features have no equivalent. Backpressure is real, and so are the trade-offs - which is why many systems keep JDBC for the write-heavy core and adopt R2DBC where concurrency per connection dominates." },
    { d: "Spring_Boot_WebFlux", n: "db", q: "In a WebFlux app, what happens when a handler calls a blocking JPA repository, and what is the fix?", opts: ["It blocks an event-loop thread, capping throughput at roughly the loop's CPU count; the fix is R2DBC, or isolating the call on boundedElastic with a bounded pool", "Spring adapts it to a reactive stream automatically", "It throws UnsupportedOperationException at startup", "Each call gets its own unbounded thread"], a: 0, e: "Reactor Netty's event loops are few by design, so a few blocking calls starve the whole server - the symptom is high latency at modest CPU, not high CPU. R2DBC is the real fix; the bounded-elastic bridge is containment whose pool you must size, and virtual threads only help if the whole stack, including the pool, is sized for it." },
    { d: "Spring_Boot_WebFlux", n: "client", q: "Your team moves an endpoint from Spring MVC to WebFlux. A JavaScript client that consumed the old JSON API breaks afterwards. What is actually different for the client?", opts: ["The response now arrives as a stream, so the client must switch to Server-Sent Events to read the body", "Nothing in the HTTP contract changes - same URLs, status codes and JSON - but the server now sustains far more concurrent connections, so only capacity and timeouts move", "The content type changes to application/stream+json because reactive endpoints always stream", "WebFlux only speaks HTTP/2, so older clients must be upgraded"], a: 1, e: "The stack choice is server-side: DispatcherHandler still writes the same JSON over the same HTTP contract, so a well-behaved client needs no change at all. Streaming, content-type and protocol claims are wrong because a handler returning a Mono produces one ordinary response body, and the real difference is throughput under load, not the wire format." },
    { d: "Spring_Boot_WebFlux", n: "webflux", q: "A WebFlux service shows one core pegged and every request slowed to a crawl while the rest of the machine looks idle. A profiler shows a handler doing a synchronous JDBC call. What is happening?", opts: ["The JDBC driver is burning CPU inside the event loop, so the fix is a faster database driver", "Reactor Netty still creates a thread per request like Tomcat, and the pool is simply too small; raising server.netty.threads fixes it", "The synchronous call blocks an event-loop thread, and every other request assigned to that loop waits behind it", "The garbage collector is thrashing because reactive allocations are unbounded, so a bigger heap removes the stall"], a: 2, e: "Event loops are few and shared, so one blocked thread stalls all requests on that loop and the symptom is latency with idle CPU. There is no thread-per-request pool to enlarge by default, and neither a faster driver nor a bigger heap helps while the loop is still parked on a socket read." },
    { d: "Spring_Boot_WebFlux", n: "dispatcher", q: "You port a @RestController from MVC to WebFlux and keep the class exactly as it is. Which statement about that port is true?", opts: ["DispatcherServlet still routes the request, but it hands off to a reactive handler adapter", "The annotations must move into RouterFunction lambdas because @RequestMapping only works in MVC", "@RestController is no longer supported and you must return ModelAndView instead", "DispatcherHandler replaces DispatcherServlet, but @RestController and @RequestMapping work unchanged, and RouterFunction is the functional alternative"], a: 3, e: "DispatcherHandler is the reactive counterpart and it reuses the same HandlerMapping and HandlerAdapter machinery underneath, so annotations and JSON serialization carry over untouched. The distractors invent a servlet that no longer runs or a forced rewrite into the functional style, which is optional rather than required." },
    { d: "Spring_Boot_WebFlux", n: "mono", q: "A colleague writes an audit method that returns Mono<AuditEntry> and calls it from a scheduled job without subscribing. What happens?", opts: ["Nothing executes until something subscribes, so no audit entry is ever written - building the pipeline is lazy", "The Mono runs immediately on the calling thread because there is no request context to defer it", "Reactor subscribes automatically whenever the method returns a reactive type", "It throws IllegalStateException during assembly, which fails the scheduled job loudly"], a: 0, e: "A Publisher describes work; it performs none until a subscription exists, which is why fire-and-forget code must subscribe or hand the Mono to a framework that does. Automatic subscription and loud assembly errors are both wrong because assembly is purely declarative, so the failure appears as silence rather than a stack trace." },
    { d: "Spring_Boot_WebFlux", n: "mono", q: "An endpoint maps a Flux<OrderId> through flatMap(this::loadLines) and results come back in a different order than the ids. What is the correct explanation and fix?", opts: ["flatMap reorders the source sequence on purpose, so use map instead and each element will be transformed in place", "The database returned rows randomly; add an ORDER BY clause and the stream will come out sorted", "flatMap subscribes to inner publishers concurrently, so completion order wins; use concatMap, or sort afterwards, when source order must be preserved", "Flux only guarantees ordering for the first 1024 elements, so chunk the stream with window(1024)"], a: 2, e: "flatMap trades order for throughput because it subscribes to inner publishers concurrently and emits in completion order, while concatMap runs them one at a time and keeps source order. A database ORDER BY cannot fix this because the reordering happens in Reactor rather than in SQL, and map would not help either since it does not flatten inner publishers at all." },
    { d: "Spring_Boot_WebFlux", n: "bridge", q: "You must call a blocking legacy SDK from a WebFlux handler while keeping the method signature reactive. Which code is correct?", opts: ["return Mono.just(legacySdk.call(id)); so the value is captured eagerly on the request thread", "return Mono.fromCallable(() -> legacySdk.call(id)).subscribeOn(Schedulers.boundedElastic());", "return Mono.fromFuture(CompletableFuture.supplyAsync(() -> legacySdk.call(id))); using the common pool", "return Mono.justOrEmpty(legacySdk.call(id)).publishOn(Schedulers.parallel());"], a: 1, e: "fromCallable defers the call until subscription and subscribeOn(boundedElastic) moves it onto the pool Reactor reserves for blocking work, leaving the event loop free. Mono.just evaluates its argument on the spot, publishOn only shifts downstream work, and the unbounded common pool can grow without limit when blocking traffic spikes." },
    { d: "Spring_Boot_WebFlux", n: "scheduler", q: "After moving a blocking call onto Schedulers.boundedElastic(), users report that the SecurityContext and MDC values are missing in the new thread. What is the correct fix?", opts: ["Wrap the call in a synchronized block, because Reactor copies thread-local state automatically as soon as you subscribe", "Copy the values into the new thread yourself with ThreadLocal.set, which Reactor then preserves for the rest of the chain", "Use Schedulers.parallel() instead, because that pool is pre-warmed and therefore inherits the caller's thread state", "Adopt Micrometer context-propagation and capture the Reactor Context with contextCapture(), so state is snapshotted before the hop and restored on the boundedElastic thread"], a: 3, e: "Thread-locals belong to threads and a scheduler hop gives you a different one, so Reactor carries per-subscription state in its Context while context-propagation snapshots and restores what security and logging keep in thread-locals. Automatic copying, manual ThreadLocal.set and switching pools all assume state travels with the task, which is exactly what does not happen." },
    { d: "Spring_Boot_WebFlux", n: "jpa", q: "A team insists their WebFlux app can keep JPA and simply wants a property that makes Hibernate non-blocking. What is the truthful answer?", opts: ["No such property exists - Hibernate blocks on socket reads by design, so you either move to R2DBC or isolate the call on boundedElastic", "Set spring.jpa.properties.hibernate.jdbc.fetch_size=0 and Hibernate will use a reactive connection pool", "Add spring.main.web-application-type=reactive, which makes every DataSource call return a Mono", "Set spring.jpa.open-in-view=true so the EntityManager is deferred until the response is written"], a: 0, e: "Blocking lives inside Hibernate's JDBC-based session and no configuration switches it to non-blocking I/O, so the real choices are a reactive driver or an explicit offload. fetch_size, open-in-view and web-application-type each change something else entirely and none of them alters how a socket read is performed." },
    { d: "Spring_Boot_WebFlux", n: "r2dbc", q: "A WebFlux app with spring-boot-starter-data-r2dbc still tries to open a JDBC connection at startup and fails. What is the most likely cause?", opts: ["R2DBC also requires the JDBC driver, and Boot refuses to start unless both drivers are on the classpath", "The R2DBC driver is incompatible with the pool, so Boot silently falls back to a pooled JDBC DataSource", "Something independent of your repositories - Flyway, Liquibase or a leftover JPA dependency - still needs JDBC, so spring.r2dbc.url feeds R2DBC while spring.datasource.url serves that JDBC consumer", "Boot only enables R2DBC when spring.main.web-application-type=reactive, so set it explicitly"], a: 2, e: "Boot configures exactly one connection factory from its own properties, so a JDBC consumer such as a schema migration tool or a stray JPA starter is what drags in spring.datasource.url and fails when it is missing. Boot never falls back from R2DBC to JDBC, and having both drivers side by side is supported - the point is knowing which component wants which URL." },
    { d: "Spring_Boot_WebFlux", n: "webmvc", q: "On Spring Boot 3.3 with Java 21, a team sets spring.threads.virtual.enabled=true for their Spring MVC app. What changes and what does not?", opts: ["Nothing changes, because virtual threads only apply to WebFlux and MVC keeps its platform thread pool", "MVC request handling now runs on virtual threads, so blocking handlers stop consuming platform threads - but the code is still blocking and a slow database still holds the request open", "Tomcat is replaced by Reactor Netty automatically, which makes the application reactive", "Every thread in the JVM becomes a virtual thread, including the ones inside the database driver's own pool"], a: 1, e: "The flag switches Tomcat's request executor to virtual threads, which turns blocking requests into cheap threads and buys real capacity without rewriting handlers. It does not convert the app to WebFlux or make any code non-blocking, and the request still waits the full time for the database." },
    { d: "Spring_Boot_WebFlux", n: "db", q: "A CRUD service is migrated from MVC to WebFlux but response times for one heavy query do not improve at all. What best explains this and what should the team do?", opts: ["WebFlux only optimizes JSON serialization, so the query must be rewritten as a projection to benefit from any stack change", "The connection pool is shared between stacks, so the migration cannot show gains until the pool is doubled", "Reactor Netty cannot talk to this database, so requests fall back to a slower compatibility path", "The database is the bottleneck and it does not care which driver arrived, so profile and tune the SQL and pooling, then keep the stack that fits the rest of the workload"], a: 3, e: "A slow query is slow over both stacks because the time is spent in the database rather than in your server's threading model, so no amount of reactive plumbing shortens it. Serialization tricks, pool doubling and invented fallback paths misattribute the cost, which profiling will show sitting in SQL execution and connection waits." },
    { d: "Spring_Boot_Migration_3", n: "java", q: "What is the baseline JDK for Spring Boot 3.x, and what happens on an older one?", opts: ["Java 17; running on 11 fails with class file version errors because the platform itself requires 17", "Java 11, the same as Boot 2.7", "Java 8, because Jakarta EE 9 supports it", "Java 21, because Boot 3 requires virtual threads"], a: 0, e: "Spring Framework 6 and Boot 3 require Java 17 as a baseline; Java 21 is supported and gives you virtual threads, but it is not required. Running Boot 3 on 8 or 11 fails at class file version or against Spring's own bytecode, and no target flag makes an old JVM valid." },
    { d: "Spring_Boot_Migration_3", n: "namespace", q: "What is the most visible breaking change in Spring Boot 3, and what does the compiler do about it?", opts: ["javax.* to jakarta.* across persistence, validation, servlet and annotation packages; the old classes are gone, so you get cannot-find-symbol errors until every import and dependency is migrated", "Only group IDs change, so imports still compile", "jakarta.* is optional and javax.* keeps working behind a flag", "Nothing changes; javax and jakarta coexist in Boot 3"], a: 0, e: "It is a namespace migration, which is why the compiler is your checklist: every javax.persistence, javax.validation, javax.servlet and javax.annotation import has to move, and so does every third-party library that has not been rebuilt. The asymmetric trap is real - Jakarta EE 9 kept the javax namespace, so a half-migrated stack can compile against the wrong generation of EE APIs." },
    { d: "Spring_Boot_Migration_3", n: "props", q: "A Boot 2 application sets spring.redis.host. What happens on Boot 3?", opts: ["The property no longer binds to anything - the data starter moved to spring.data.redis.* - so it is silently ignored and the client falls back to its default host", "The property is renamed automatically at runtime", "Startup fails with a helpful message about the old key", "The property still works with a deprecation warning"], a: 0, e: "Silently ignored is the dangerous part: the app starts and the failure appears later as a connection refused in the cache layer. This is the general shape of a Boot 2 to 3 migration - few hard errors for old keys, so the safe approach is to diff the effective configuration between versions using the configprops endpoint or an environment dump, and to enable strict binding while you do it." },
    { d: "Spring_Boot_Migration_3", n: "baseline", q: "Before touching any code, what should a team capture to make a Boot 2 to 3 migration safe?", opts: ["A green test run of the current version, an inventory of custom starters and spring.factories entries, and a list of explicitly pinned dependency versions", "A production heap snapshot, because the migration will change garbage collection behaviour", "The output of mvn dependency:tree from the Boot 3 branch, so you know the target before you start", "A feature flag on every controller, so the reactive rewrite can roll out endpoint by endpoint"], a: 0, e: "The safety net is evidence of current behaviour plus a map of exactly what Boot 3 treats differently - registration files, custom starters and hand-pinned versions are where migrations break. A heap snapshot and feature flags address unrelated concerns, and reading the target dependency tree tells you nothing about what your application does today." },
    { d: "Spring_Boot_Migration_3", n: "deps", q: "You bump spring-boot-starter-parent to 3.3.x but an old logging adapter still resolves at 1.7. Why?", opts: ["The parent only manages plugins in Boot 3, so every dependency version must be written by hand", "Your pom pins that artifact's version explicitly, and an explicit version overrides the BOM's managed one", "Maven ignores the Boot BOM whenever a dependency appears in more than one configuration", "Boot 3 stopped importing the dependency-management BOM, so nothing is managed any more"], a: 1, e: "Dependency management is a default rather than a lock: any version you declare yourself wins over the imported BOM, which is why hand-pinned versions survive a parent bump. The parent still manages both dependencies and plugins in Boot 3, so the fix is to delete the stale explicit version and let 3.3.x resolve it." },
    { d: "Spring_Boot_Migration_3", n: "config", q: "After upgrading, a bean your custom starter used to auto-configure is simply missing, and nothing is logged. What happened?", opts: ["@ComponentScan now needs an explicit basePackage, so your starter's beans are skipped", "Auto-configuration is disabled by default in Boot 3 and must be switched on with spring.boot.autoconfigure.enabled=true", "Boot 3 reads auto-configuration classes from META-INF/spring/org.springframework.boot.autoconfigure.AutoConfiguration.imports and silently ignores spring.factories entries for that purpose", "Your starter's package name contains javax, which Boot 3 refuses to scan"], a: 2, e: "Registration moved from spring.factories to the new imports file in Boot 3, and a leftover old entry is ignored without a warning - silent by design, which is why a vanished bean is the symptom. Auto-configuration is still enabled by default and package scanning is unrelated, so those explanations hide the one-line fix of shipping the new file." },
    { d: "Spring_Boot_Migration_3", n: "props", q: "In Boot 3 you write a @ConfigurationProperties class with a single constructor, using a record for binding. What do you need to add?", opts: ["The @ConstructorBinding annotation on the class, exactly as in Boot 2.x", "A no-arg constructor plus setters, because constructor binding was removed in Boot 3", "A @Bean method that calls the constructor yourself, since Boot no longer binds constructors", "Nothing extra - since Boot 3 a single constructor is bound automatically, so records work out of the box and @ConstructorBinding is not required"], a: 3, e: "Boot 3 dropped the requirement to mark constructor-bound classes, so a lone constructor or a record is enough for binding to work. Requiring setters or a manual @Bean method describes older habits, and treating the leftover annotation as mandatory mistakes something optional for a necessity." },
    { d: "Spring_Boot_Migration_3", n: "java", q: "A team adjusts its build flags for a Boot 3 migration on a JDK 21 build machine that deploys to Java 17 images. Which change is correct, and why?", opts: ["-source 17 -target 17, because those flags are independent of the JDK and give the most compatible bytecode", "--release 17, because it compiles against the Java 17 API signatures as well as emitting 17 bytecode, so an API that only exists on a newer JDK fails at build time instead of in production", "-Xlint:17, because Boot 3 uses the lint level as its compatibility check", "No flag is needed - the JDK running the build determines the class file version automatically"], a: 1, e: "--release checks both language level and the bootclasspath API, which is what a JDK 21 build machine needs to avoid compiling against APIs missing from 17. Source and target alone would happily accept a newer API and fail only when the app runs on the 17 base image, and no flag at all leaves you emitting 21 bytecode." },
    { d: "Spring_Boot_Migration_3", n: "namespace", q: "During the migration you rewrite javax.persistence and javax.servlet imports. Which of these must NOT be renamed?", opts: ["javax.sql.DataSource, javax.naming.InitialContext and the java.* packages - they belong to the JDK, not Jakarta EE", "javax.sql.DataSource, because everything under javax becomes jakarta without exception", "java.* only, because the JDK kept javax.sql and javax.naming for backwards compatibility", "None - in Boot 3 every javax.* symbol is renamed, including the JDK ones"], a: 0, e: "The rename covers Jakarta EE APIs that moved to the Eclipse Foundation, while javax.sql, javax.naming, javax.net.ssl and the whole java.* tree are Java SE and never left the JDK. A blanket string replace is the classic migration bug: it breaks valid JDK imports while still missing reflective and third-party usages that only fail at runtime." },
    { d: "Spring_Boot_Migration_3", n: "webstack", q: "Leadership asks you to switch to WebFlux during the migration to make a JPA-backed CRUD monolith faster. What is the sound engineering response?", opts: ["Agree, because WebFlux is faster by default, so the migration and the rewrite should be one change", "Agree, but only if you also disable Hibernate's second-level cache so it cannot block", "Decline the coupling: JPA forces blocking anyway, so reactive buys nothing here - stay on MVC unless profiling shows blocking I/O is the bottleneck, and treat a reactive rewrite as its own project", "Agree only after moving to an event store, because relational databases cannot be used from WebFlux"], a: 2, e: "With Hibernate in the path the application still blocks, so the rewrite adds risk without removing the bottleneck, and switching stacks is a rewrite rather than a flag on top of an already breaking migration. Racing both changes together destroys your ability to attribute failures, while the other options assume reactive magic or invent a database restriction that does not exist." },
    { d: "Spring_Boot_Migration_3", n: "docker", q: "The Boot 3 jar builds fine, but the container exits immediately with UnsupportedClassVersionError. What is wrong and what is the fix?", opts: ["The jar is corrupted by the layered build, and repackaging with spring-boot-maven-plugin fixes it", "Docker is running in Windows compatibility mode, so switch the daemon to Linux containers", "The base image must be eclipse-temurin:11 for Boot 3, because 17 is only needed at compile time", "The runtime image is older than Java 17, so it cannot load Boot 3's 17 bytecode - build on an eclipse-temurin:17 or newer base and rebuild the layers rather than retagging the old one"], a: 3, e: "A class file version error is a runtime JVM floor problem: the build produced 17 bytecode and the image's JVM is older, so nothing about the jar itself is wrong. Running on 11 or repackaging cannot help, and Windows container mode is unrelated to the class file version the JVM reports." },
    { d: "Spring_Boot_Migration_3", n: "test", q: "Your unit tests all pass after the Boot 3 upgrade, but the Testcontainers suite fails on a query that worked against H2. What does this tell you and what should you do?", opts: ["H2 was hiding a Hibernate 6 dialect difference, so run against the real database and fix the SQL or mapping before deploying", "Testcontainers is incompatible with Boot 3, so pin it to an older version and ignore the H2 result", "The failure is a flaky container, so rerunning it is enough - the green unit suite already proves the migration", "Hibernate 6 requires H2 2.x, so switch the test database back to a matching in-memory H2 version"], a: 0, e: "H2 accepts SQL that Postgres or MySQL may reject, and Hibernate 6's parser and dialect handling differ from 5.6, so the integration suite against the real engine is the actual gate. Blaming Testcontainers, calling it flaky or retreating to H2 all remove the evidence you need before that container reaches production." },
    { d: "Spring_Boot_Migration_3", n: "deploy", q: "The migrated build passes every test. How should the rollout be structured?", opts: ["Replace the old artifact everywhere at once so the two versions never coexist and configuration drift is impossible", "Smoke test the new artifact, release it to a small slice of traffic, and watch error rate and latency across a full traffic cycle before expanding", "Deploy it behind the same port in the background and let the load balancer pick it up at the next health check", "Hold the new version with zero traffic for a full release cycle to prove stability, then switch over"], a: 1, e: "A canary catches what tests cannot - traffic shape, pooling against production data and monitoring blind spots - while keeping the old artifact ready makes rollback a redeploy instead of an incident. A big-bang swap removes your safety net, and a version that never serves traffic proves nothing about its stability." },
    { d: "Spring_Boot_Migration_3", n: "rollback", q: "During rollout the new version fails a health check because one third-party starter still registers through spring.factories. What is the right response?", opts: ["Roll the whole migration back to Boot 2 and revisit it next quarter", "Disable that health check so the deployment can complete", "Stop that migration phase rather than the release: keep the old artifact serving, fix the starter or its imports file, and re-run the test gate before trying again", "Pin the starter to an older version that still uses spring.factories and leave it there permanently"], a: 2, e: "A blocker should halt the migration step, not the running service - the old artifact stays live while the single broken dependency is fixed, so the release never depends on a workaround. Abandoning the migration or masking the health check trades a contained delay for a larger outage later, and permanent pinning only defers the same failure." },
    { d: "Spring_Boot_Migration_3", n: "deps", q: "After bumping the BOM, your project no longer compiles: WebSecurityConfigurerAdapter cannot be resolved. What does this mean?", opts: ["The security starter was dropped from the Boot 3 BOM, so add spring-boot-starter-security explicitly to bring it back", "Your Maven cache is stale, and re-resolving dependencies will restore the missing class", "Boot 3 disabled Spring Security by default, so you must opt in with spring.security.enabled=true", "Boot 3 brings Spring Security 6, where WebSecurityConfigurerAdapter is removed - replace it with a SecurityFilterChain @Bean using the lambda DSL"], a: 3, e: "The class was deleted in Security 6, so no amount of re-resolving or enabling a flag will bring it back; the migration is a code change to component-style security configuration. Nothing was dropped from the BOM and security is still on by default, which is why the failure surfaces as a compile error rather than an insecure app." },
    { d: "Spring_Boot_Nplus1", n: "loop", q: "The Book Store has 8 books. The naive catalog endpoint runs findAll() and then reads the author and categories of each book. How many SQL statements does the endpoint actually execute, and why is the count not 8?", opts: ["18 - one findAll, then two lazy associations per book, plus the count query","8 - one query per book, which is what the loop suggests","1 - Hibernate batches every lazy proxy into the original findAll","18 books - Hibernate invents a row per association"], a: 0, e: "Measured, not guessed: the endpoint reports sqlQueries itself, because QueryCounter reads Hibernate statistics around the whole method. It answers 18 for 8 books. The count is not 8 because each lazy association access leaves the persistence context and issues its own round trip, so the cost is 1 + 2N rather than N.", ev: "nplus1", evk: "naive", t: { slug: "nplus1", step: 3 }, p: { file: "src/main/java/com/example/bookstore/service/CatalogService.java", from: 46, to: 50, note: "Two lazy accessors per book: getBookCategories() and getAuthor(). Each one can trigger queries." } },
    { d: "Spring_Boot_Nplus1", n: "onequery", q: "The join-fetch endpoint returns a byte-identical payload to the naive one and costs 1 query instead of 18. What actually changed?", opts: ["The fetch plan: one query now loads author, bookCategories and category together","The loop was rewritten to batch books before mapping them","The entities were cached between the two requests","The transaction was removed so Hibernate skipped the associations"], a: 0, e: "The captured responses prove the payloads are identical, so nothing about the mapping changed. The loop in CatalogFetchService is character-for-character the same as in CatalogService. Only the repository query changed: findAllWithAuthorAndCategories left-joins the graph, so the loop has nothing left to load lazily.", ev: "nplus1", evk: "joinFetch", t: { slug: "nplus1", step: 5 }, p: { file: "src/main/java/com/example/bookstore/service/CatalogFetchService.java", from: 29, to: 33, note: "Same loop as the naive path, but the query already fetched everything." } },
    { d: "Spring_Boot_Nplus1", n: "fixedservice", q: "A colleague removes the loop over books and gets 1 query. Which claim is actually correct?", opts: ["The loop was never the bug - N+1 is a fetch-plan problem, and any loop over eagerly fetched data is free","Loops and lazy loading are both wrong and should always be avoided","Loops are fine, but only inside @Transactional(readOnly = true)","Loops are the cause, and the fix is to use an EntityManager directly"], a: 0, e: "This is the idea worth keeping: the identical loop costs 2N extra queries in one service and zero in the other. The loop is not the defect, the fetch plan is. Chasing the loop leads you to rewrite working code and still miss the real cost.", t: { slug: "nplus1", step: 6 } },
    { d: "Spring_Boot_Nplus1", n: "controller", q: "A service returns a list of Order entities inside its transaction, and the controller then serializes each order by walking getItems(). By then the persistence context is closed. What do you observe?", opts: ["The items are serialized as an empty list, with no error", "Jackson opens a new transaction per order to load the items", "The items are always available, because entities never lose their state", "A LazyInitializationException when the serializer touches the collection"], a: 3, e: "Lazy collections need an open persistence context, and once the service transaction has committed, touching getItems() fails. Open-in-view, enabled by default in Spring Boot, hides this by holding the session until the response is written, but Jackson never opens a connection itself and silently returning an empty list would corrupt the payload." },
    { d: "Spring_Boot_Nplus1", n: "service", q: "The service team is choosing between @BatchSize(size = 20) on the collection and a join fetch in the JPQL. Which trade-off is accurate?", opts: ["@BatchSize changes the fetch type to EAGER, so the collection is loaded inside the original query", "Join fetch issues a separate query per root, while batching always produces exactly one query", "Both behave identically once the Hibernate second-level cache is enabled", "Batching issues one SELECT per 20 roots with no duplicate rows, while join fetch gives one query whose row count explodes when several associations are joined"], a: 3, e: "Batch fetching rewrites N collection loads into about N/20 IN queries, so row counts stay linear and each root appears once. A fetch join collapses everything into one statement, but joining a collection multiplies rows and joining two associations makes a cartesian product, and the second-level cache changes neither behavior." },
    { d: "Spring_Boot_Nplus1", n: "loop", q: "You wrap the naive loop that reads each order's items in @Transactional(readOnly = true). What happens to the statement count?", opts: ["It drops to 1, because a read-only transaction preloads every collection", "It stays at N+1, because a transaction keeps the session open but does not change how collections are fetched", "It drops to N, because the initial findAll is skipped in read-only mode", "It throws an exception, because read-only transactions forbid SELECT statements"], a: 1, e: "readOnly is a hint for flushing and driver-level optimization, not a change to the fetch plan, so Hibernate still issues one select per order for the items. A transaction cannot batch collection loads, skipping the root query would change the results, and read-only transactions are perfectly free to run SELECTs." },
    { d: "Spring_Boot_Nplus1", n: "query101", q: "A transactional method loads all 500 orders with findAll(), filters them in Java down to the 7 orders in the current status, and then reads getItems() for those 7. How many statements run?", opts: ["8, because only the rows that survive the filter are ever loaded", "1, because the filter runs in SQL once the method is read-only", "500, one per order, since the root select does not count", "501, because the root select returns all 500 rows regardless of the Java filter, plus one per displayed order"], a: 3, e: "The Java filter runs after the query, so findAll still pulls all 500 rows and only then do the 7 displayed orders each trigger a collection select, giving 1 + 7 = 501. Filtering cannot become SQL unless you move it into the query itself, the root select is a real statement, and read-only mode does not rewrite predicates." },
    { d: "Spring_Boot_Nplus1", n: "joinfetch", q: "You add left join fetch o.items to a repository query and also pass a Pageable. What is the problem?", opts: ["Spring Data detects the fetch join and silently drops the Pageable", "Pagination fails at startup, because JPQL forbids fetch joins on positioned queries", "The limit cannot be applied to joined rows correctly, so you get wrong page boundaries or Hibernate has to page in memory", "The fetch join is converted into one separate query per page"], a: 2, e: "A fetch join multiplies each root row by its collection size, so a SQL LIMIT would cut through the middle of a root's rows instead of between roots, and Hibernate ends up applying firstResult and maxResult after loading. Spring Data neither drops the Pageable nor splits the query, and fetch joins are legal in paged JPQL; only the push-down into SQL is lost." },
    { d: "Spring_Boot_Nplus1", n: "fixedservice", q: "You set spring.jpa.properties.hibernate.default_batch_fetch_size = 50 in application.properties. What changes?", opts: ["Repository methods now return at most 50 entities per page", "Lazy to-one and collection loads are fetched in batches of up to 50 ids instead of one query per parent", "Every association becomes EAGER, so fetch joins are no longer needed", "Only queries written with @EntityGraph are affected"], a: 1, e: "default_batch_fetch_size lets Hibernate resolve pending lazy loads with an IN query of up to 50 ids, which turns one query per parent into a fixed number. It does not cap result page sizes, it does not change any fetch type, so fetch joins and @EntityGraph still matter, and it applies to ordinary lazy loads rather than only annotated ones." },
    { d: "Spring_Boot_Nplus1", n: "onequery", q: "One JPQL statement does left join fetch o.items and left join fetch o.payments, with both associations mapped as List. What happens?", opts: ["Hibernate throws MultipleBagFetchException, because two bag collections cannot be fetched at once", "The query returns a cartesian product of items and payments, with no error", "Spring Data splits it into two queries automatically", "The payments fetch is silently ignored"], a: 0, e: "Two List (bag) collections cannot be fetched together, so Hibernate raises MultipleBagFetchException while building the query; map one side to Set or fetch only one collection. If both associations were Sets the statement would run but return the cartesian product of items and payments, and Spring Data never rewrites or silently drops the second fetch." },
    { d: "Spring_Boot_Transactions", n: "inner", q: "placeOrder calls applyOrderDiscount, and applyOrderDiscount is annotated @Transactional. The runtime report lists it under bypassedMethods, not advisedMethods. Why?", opts: ["It is a self-invocation, so the call never leaves the object and the proxy is never consulted","@Transactional is ignored on methods that return a value","The method is private, so Spring cannot see it","Advice runs but is not reported for same-class calls"], a: 0, e: "The measured report is unambiguous: advisedMethods contains placeOrder, reserveCopy and recordOrderPlaced, and bypassedMethods contains OrderService.applyOrderDiscount. reserveCopy gets advice because it is a different bean and the call crosses a proxy. applyOrderDiscount stays inside the same object, so nothing intercepts it. The annotation is present and completely inert.", ev: "transactions", evk: "required", t: { slug: "transaction", step: 2 }, p: { file: "src/main/java/com/example/bookstore/service/OrderService.java", from: 99, to: 115, note: "The call at line 99 and the annotated method at 111-115. The annotation looks right; the call never crosses a proxy." } },
    { d: "Spring_Boot_Transactions", n: "poison", q: "In poison mode an inner transaction throws, the catch block swallows the exception, and the method returns normally. The caller still gets HTTP 409. What went wrong?", opts: ["The inner transaction marked the outer one rollback-only, and that mark cannot be cleared - so the commit fails after the method returned","The catch block re-threw the exception under a different type","The order was rejected by a validation rule before any transaction opened","The outbox row could not be written, so the whole request was retried"], a: 0, e: "This is the trap that makes transaction bugs hard to read: the stack trace points at UnexpectedRollbackException, which the method never throws. Catching the original exception does not undo the rollback-only flag the inner transaction set on the shared transaction. The failure surfaces at commit time, far from the line that caused it.", ev: "transactions", evk: "poison", t: { slug: "transaction", step: 5 }, p: { file: "src/main/java/com/example/bookstore/service/OrderService.java", from: 132, to: 139, note: "triggerInnerRollbackOnly swallows the exception, which is exactly why the failure looks recovered." } },
    { d: "Spring_Boot_Transactions", n: "commit", q: "recordOrderPlaced is annotated @Transactional(propagation = Propagation.MANDATORY). What failure mode is that annotation chosen to prevent?", opts: ["The outbox event being written in its own transaction, so it could commit when the order rolls back","The event being written twice","The order being written before the stock reservation","The event being written without any transaction at all"], a: 0, e: "MANDATORY fails loudly instead of quietly starting a transaction of its own. If the caller ever loses its @Transactional, REQUIRED would silently commit the event on its own and the dual-write gap would reopen with no error at all. The captured run shows 2 of 2 events published and both delivered only after the order committed.", ev: "outbox", evk: "events", t: { slug: "transaction", step: 3 }, p: { file: "src/main/java/com/example/bookstore/service/OutboxService.java", from: 26, to: 27, note: "MANDATORY refuses to run without a caller transaction instead of creating one." } },
    { d: "Spring_Boot_Transactions", n: "outertx", q: "Switching the inner reservation to REQUIRES_NEW changes what the advised-method list reports. What does that mode actually change about atomicity?", opts: ["The reservation commits in its own suspended transaction, so it is no longer atomic with the order that depends on it","It makes the order commit earlier","It disables the outer transaction entirely","It rolls the outer transaction back if the inner one succeeds"], a: 0, e: "The captured report shows the different entry point (reserveCopyInNewTransaction) precisely so you can see advice applied to a second, independent transaction. The trade-off is real: the inner commit can succeed while the outer order later fails, which is exactly the dual-write problem the transactional outbox exists to avoid on the write side.", ev: "transactions", evk: "requires-new", t: { slug: "transaction", step: 4 }, p: { file: "src/main/java/com/example/bookstore/service/StockService.java", from: 27, to: 30, note: "REQUIRES_NEW always runs in its own transaction, suspended or not." } },
    { d: "Spring_Boot_Transactions", n: "rollback", q: "A @Transactional service method declares throws IOException and lets it escape. No rollbackFor is configured. What does Spring do?", opts: ["The transaction commits, because checked exceptions do not trigger rollback under the default rules", "The transaction rolls back, because every exception should roll back", "The transaction rolls back only if the IOException has also been logged", "The interceptor marks the transaction rollback-only, so the caller gets UnexpectedRollbackException"], a: 0, e: "By default Spring rolls back only on RuntimeException and Error, so a checked IOException is committed and simply propagates to the caller. There is no rule that rolls back on every exception and no logging condition involved; you would add rollbackFor = Exception.class to change this, and rollback-only marking happens when a nested transaction participates." },
    { d: "Spring_Boot_Transactions", n: "outer", q: "A method annotated @Transactional(propagation = Propagation.NOT_SUPPORTED) is called from a method that already holds a REQUIRED transaction. What happens?", opts: ["It joins the caller's transaction, because only REQUIRES_NEW needs a second connection", "Spring fails at startup, because NOT_SUPPORTED cannot appear inside a transactional call", "The caller's transaction is marked rollback-only", "The caller's transaction is suspended, the method runs with no transaction bound to the thread, and the caller's transaction resumes afterwards"], a: 3, e: "NOT_SUPPORTED suspends the existing transaction for the duration of the call, so the work runs non-transactionally and the outer transaction resumes when it returns. It never joins the caller's transaction, which is REQUIRED's job, and the propagation is perfectly legal inside a transactional call." },
    { d: "Spring_Boot_Transactions", n: "commit", q: "An event is published inside a transaction with @TransactionalEventListener(phase = AFTER_COMMIT), and the transaction later rolls back. What happens?", opts: ["The listener never runs, because AFTER_COMMIT callbacks fire only after a successful commit", "The listener runs immediately when publishEvent is called", "The listener runs during the rollback so it can undo the change", "Spring throws at startup, because the event source must be a separate bean"], a: 0, e: "AFTER_COMMIT listeners are registered as a synchronization callback and fire only after a successful commit, so a rollback discards them silently unless fallbackExecution is enabled. The listener is not invoked at publish time and cannot run inside the rollback path, and publishing from a transactional method is exactly the supported setup." },

  ],
  troubleshooting: [
    { s: "java.net.BindException: Web server failed to start. Port 8080 was already in use.", cause: "Another process on the host holds the socket - typically a previous run of the same app, a leftover java.exe, or a container publishing the same host port.", fix: "Find the holder with netstat -ano | findstr :8080 and stop that PID, or change the port with server.port. In tests use server.port=0 and inject the actual port so parallel builds never collide.", d: ["Spring_Boot_Startup", "Spring_Boot_Deployment"], tags: ["startup", "ports"] },
    { s: "Description: No qualifying bean of type 'com.acme.OrderService' available: expected at least 1 bean.", cause: "No bean of that type is registered - the class is not a stereotype (@Service or @Component), or it sits outside the package tree scanned by your @SpringBootApplication.", fix: "Move the class into or below the application class's package and annotate it with @Service; if it is an interface, add an implementation bean. Set logging.level.org.springframework.beans.factory.support=TRACE to see the packages actually scanned.", d: ["Spring_Boot_Startup"], tags: ["startup", "wiring", "component-scan"] },
    { s: "NoUniqueBeanDefinitionException: expected single matching bean but found 2: smtpMailSender, sesMailSender", cause: "Two beans of the same type exist and the injection point does not say which one it wants.", fix: "Mark the preferred bean @Primary, or qualify the injection point with @Qualifier('smtpMailSender'). If the choice is per environment, use @Profile on each implementation instead of a qualifier.", d: ["Spring_Boot_Startup", "Spring_Boot_AntiPatterns"], tags: ["startup", "wiring"] },
    { s: "Parameter 0 of constructor in com.acme.PaymentService required a bean of type 'com.acme.PaymentClient' that could not be found", cause: "The constructor dependency has no implementation bean: a missing @Service stereotype, a package outside the component-scan root, or a @Bean method disabled by a condition or an inactive profile.", fix: "Check in order: the stereotype on the implementation, the package relative to your @SpringBootApplication class, whether the bean method's @ConditionalOn.../@Profile matches the active environment, and finally whether the client library is a declared dependency.", d: ["Spring_Boot_Startup", "Spring_Boot_AutoConfiguration"], tags: ["startup", "wiring", "conditional"] },
    { s: "BeanCurrentlyInCreationException: Error creating bean with name 'a': Requested bean is currently in creation: Is there an unresolvable circular reference?", cause: "Two or more beans depend on each other through constructors, so neither can be constructed first.", fix: "Break the cycle by extracting the shared behaviour into a third bean. If one dependency is genuinely optional, mark it @Lazy so the injected proxy defers construction, or use setter injection for the side that can tolerate it.", d: ["Spring_Boot_Startup", "Spring_Boot_Bean_Lifecycle"], tags: ["startup", "wiring", "circular-dependency"] },
    { s: "Failed to configure a DataSource: 'url' attribute is not specified and no embedded datasource could be configured.", cause: "DataSourceAutoConfiguration is a candidate but no JDBC starter is on the classpath, or spring.datasource.url is unset - for example because it only exists in an application-dev.properties file while another profile is active.", fix: "Add spring-boot-starter-jdbc (or the JPA starter) and set spring.datasource.url; verify the active profile. Remember that environment variables outrank properties files, so a stale SPRING_DATASOURCE_URL will change the failure you see.", d: ["Spring_Boot_AutoConfiguration", "Spring_Boot_Config_Properties"], tags: ["startup", "database", "configuration"] },
    { s: "org.springframework.jdbc.CannotGetJdbcConnectionException: Could not create connection to database server / Caused by: java.lang.ClassNotFoundException: org.h2.Driver", cause: "The JDBC driver is not on the runtime classpath - a common result of H2 being a provided-scope or test-only dependency, or of a test that assumes H2 while production runs PostgreSQL or MySQL.", fix: "Add the driver with runtime (or compile) scope, or point tests at the engine you actually run in production using Testcontainers. H2's compatibility mode is not the same database, so an H2-only test suite proves very little about your real SQL and DDL.", d: ["Spring_Boot_Testing_Slices", "Spring_Boot_Migration_3"], tags: ["database", "testing", "classpath"] },
    { s: "org.postgresql.util.PSQLException: FATAL: too many connections for role 'app'", cause: "Total connections exceed the server limit. Typically every replica opens its own Hikari pool (default maximum-pool-size 10) and the count is multiplied by replicas, plus dev tools and monitoring - or a leak where connections are never returned.", fix: "Size the pool per replica so replicas x pool size stays well under max_connections with headroom for admin and migration sessions, set minimumIdle below maximumPoolSize, and enable Hikari's leakDetectionThreshold to find code that holds a connection outside a transaction.", d: ["Spring_Boot_AutoConfiguration", "Spring_Boot_Transactions"], tags: ["database", "performance", "pooling"] },
    { s: "HikariPool-1 - Connection is not available, request timed out after 30000ms. Total connections: 10, active: 10, idle: 0", cause: "Every pooled connection is checked out and never returned. Usual causes are long transactions with slow I/O inside them, REQUIRES_NEW nesting that needs a second connection, or a leak of raw connections or EntityManagers.", fix: "Move remote calls and file I/O outside the transaction, avoid REQUIRES_NEW in hot paths, and enable leakDetectionThreshold (above your slowest legitimate checkout) to get the leaking stack trace named. Raising maximum-pool-size only postpones the failure and can overload the database instead.", d: ["Spring_Boot_Transactions", "Spring_Boot_AntiPatterns"], tags: ["database", "performance", "pooling", "transactions"] },
    { s: "org.hibernate.LazyInitializationException: could not initialize proxy - no Session and current thread is not associated with this Hibernate Session", cause: "A lazy association is dereferenced after the transaction and session have closed - typically while Jackson serialises an entity returned from a service method.", fix: "Return a DTO built inside the transaction, or fetch what you need with @EntityGraph, a join fetch or a projection. Keep spring.jpa.open-in-view=false in production; enabling it hides the symptom while holding a database connection for the entire request.", d: ["Spring_Boot_Nplus1", "Spring_Boot_Transactions", "Spring_Boot_Layers"], tags: ["jpa", "lazy-loading", "osiv"] },
    { s: "WARNING: spring.jpa.open-in-view is enabled by default. Therefore, database queries may be performed during view rendering.", cause: "Open Session in View is on by default, so the EntityManager stays open for the whole HTTP request in order to allow lazy loading during serialisation.", fix: "Set spring.jpa.open-in-view=false and remove the lazy loading with DTOs, fetch joins or projections. Leaving it enabled means one pooled connection per in-flight request for the entire rendering, and queries appear in logs from code that never touched a repository.", d: ["Spring_Boot_Nplus1", "Spring_Boot_Transactions"], tags: ["jpa", "performance", "osiv"] },
    { s: "org.hibernate.exception.SQLGrammarException: could not extract ResultSet; nested cause PSQLException: ERROR: relation 'book' does not exist", cause: "The physical table name does not match the mapping - the naming strategy produced a different name, migrations never ran against this schema, or the entity is mapped to another schema.", fix: "Print the expected schema (temporarily set spring.jpa.hibernate.ddl-auto=create with SQL logging, or inspect a Flyway-generated migration) to learn the exact name, then align @Table or the naming strategy and ensure the migration creates it. Quote reserved words such as order explicitly.", d: ["Spring_Boot_Data_Model", "Spring_Boot_Migration_3"], tags: ["jpa", "sql", "schema"] },
    { s: "org.springframework.orm.jpa.JpaSystemException: could not execute statement [duplicate key value violates unique constraint 'uk_order_reference']", cause: "A uniqueness rule in the database is violated - a retried non-idempotent operation, two concurrent requests claiming the same reference, or the constraint was added after duplicates already existed.", fix: "Make the operation idempotent (insert-if-not-exists, or INSERT ... ON CONFLICT DO NOTHING) and let the database be the arbiter instead of a read in application code. Where the operation is safe to repeat, catch the unique violation and treat it as success, and backfill before adding the constraint.", d: ["Spring_Boot_Data_Model", "Spring_Boot_Transactions"], tags: ["database", "concurrency", "idempotency"] },
    { s: "org.springframework.transaction.UnexpectedRollbackException: Transaction silently rolled back because it has been marked as rollback-only", cause: "An inner @Transactional method (propagation REQUIRED) threw, the outer method caught the exception and carried on, but the shared transaction was already poisoned - or a rollback-only transaction escaped a non-transactional callback.", fix: "Either let the exception propagate and translate it to your API contract above the transaction boundary, or make the inner operation genuinely independent with REQUIRES_NEW (accepting the second connection). Also check for @Transactional methods called via this, which bypass the proxy and lose their annotation entirely.", d: ["Spring_Boot_Transactions", "Spring_Boot_AOP_Proxy"], tags: ["transactions", "error-handling"] },
    { s: "InvalidDataAccessApiUsageException: Executing an update/delete query", cause: "A modifying operation ran with no active transaction - the @Transactional was lost (an override without the annotation, a self-invocation, a final method, or a call from a non-transactional component) or the write happened in a read-only transaction.", fix: "Put @Transactional on the service method that performs the write, and verify it is public, on a non-final class, and invoked through the proxy rather than with a this call. For bulk operations use @Modifying with clearAutomatically and flushAutomatically so the persistence context does not serve stale entities.", d: ["Spring_Boot_Transactions", "Spring_Boot_AOP_Proxy"], tags: ["transactions", "jpa", "proxy"] },
    { s: "java.lang.OutOfMemoryError: Java heap space (logs also show 'GC overhead limit exceeded')", cause: "Either a genuine leak - unbounded caches, static collections, streams never closed, or listeners that accumulate - or a single operation materialising far more rows than intended, or simply too small a heap for the working set.", fix: "Capture a heap dump at the moment of failure (-XX:+HeapDumpOnOutOfMemoryError or jcmd <pid> GC.heap_dump) and diff two dumps to find what grows. Fix the largest retainer - usually a cache without a maximum size or an accidental cartesian join - before raising the heap, and prefer MaxRAMPercentage in containers.", d: ["Spring_Boot_Caching", "Spring_Boot_Deployment"], tags: ["memory", "performance", "caching"] },
    { s: "Container status CrashLoopBackOff; the log ends with java.lang.OutOfMemoryError: unable to create new native thread, or the pod is killed with exit code 137 and no Java error at all", cause: "Either thread exhaustion - an unbounded @Async executor, a runaway scheduled loop, or a per-request pool created inside a singleton - or the cgroup memory limit was consumed by heap plus metaspace, direct buffers and thread stacks.", fix: "Define a ThreadPoolTaskExecutor with a fixed core and max size, a bounded queue and an explicit rejection policy, then size the JVM with -XX:MaxRAMPercentage leaving headroom for native memory, and cap the Hikari pool so replica scaling cannot multiply connections.", d: ["Spring_Boot_Async_Scheduling", "Spring_Boot_Deployment"], tags: ["memory", "threads", "containers", "async"] },
    { s: "401 {\"error\":\"invalid_token\"} on requests that worked before a key rotation, and clock skew is suspected", cause: "The JWK set is cached by the resource server, so a rotated signing key is not picked up immediately; or issuer/nbf validation is failing because the clocks differ by more than the allowed skew.", fix: "Configure the resource server with spring.security.oauth2.resourceserver.jwt.jwk-set-uri so the Nimbus decoder refreshes keys, shorten the JWK cache TTL if rotation is frequent, and verify NTP synchronisation on both hosts. Also confirm the token was signed by the key the issuer currently publishes, not the retired one.", d: ["Spring_Boot_Security_JWT"], tags: ["security", "jwt", "auth"] },
    { s: "403 on a browser form POST, while the same call with curl and a Bearer token succeeds", cause: "CSRF protection is enabled by default for browser clients. A form POST carries the session cookie automatically, so the request is rejected for a missing or invalid CSRF token; a request authenticated only by the Authorization header is not subject to it.", fix: "Keep CSRF enabled for cookie or session based clients and send the token as the _csrf form field, the X-CSRF-TOKEN header, or via CookieCsrfTokenRepository.withHttpOnlyFalse. Disable CSRF only for a genuinely stateless bearer-token API, where no ambient credential can be ridden on.", d: ["Spring_Boot_Security_JWT"], tags: ["security", "csrf", "http"] },
    { s: "HTTP 415 Unsupported Media Type on a POST that works from Postman but not from the browser", cause: "The Content-Type of the request body does not match what the handler can consume - typically a form-encoded body sent to a @RequestBody endpoint, or a missing content type on a fetch call.", fix: "Send application/json and make sure the JSON is what the DTO expects; if you deliberately support both, declare consumes = {MediaType.APPLICATION_JSON_VALUE, MediaType.APPLICATION_FORM_URLENCODED_VALUE} or add a second handler. Check the response body for the list of supported media types, which the error usually includes.", d: ["Spring_Boot_Layers", "Spring_Boot_Request_Path"], tags: ["http", "json", "content-negotiation"] },
    { s: "InvalidDefinitionException: Java 8 date/time type java.time.LocalDate not supported by default: add Module 'com.fasterxml.jackson.datatype:jackson-datatype-jsr310' to get supported", cause: "The JSR-310 module is not registered, so Jackson cannot map java.time types. It is usually present transitively but excluded, or auto-configuration was disabled.", fix: "Check the spring-boot-starter-json and jackson-datatype-jsr310 dependencies and exclude whatever is shadowing them, and make sure Jackson auto-configuration is not switched off. The same root cause produces silently string-formatted dates once it is working, so configure the date format explicitly rather than relying on defaults.", d: ["Spring_Boot_Testing_Slices", "Spring_Boot_Layers"], tags: ["json", "classpath", "serialization"] },
    { s: "A single query takes 30 seconds and EXPLAIN shows a sequential scan on a table with a few million rows", cause: "A missing or unusable index - the column in the predicate or join is not indexed, or the index exists but the query shape prevents its use (a function applied to the column, a leading wildcard, or a type mismatch).", fix: "Read the execution plan, add the index that matches the actual predicate and join, and remove anything that makes the column non-sargable such as to_char(), DATE(col) = or LIKE '%x'. Keep the pool sized for the concurrency the index enables, because a faster query changes the load profile rather than the bottleneck.", d: ["Spring_Boot_Nplus1", "Spring_Boot_Data_Model"], tags: ["performance", "sql", "database"] },
    { s: "401 on every endpoint immediately after adding spring-boot-starter-security to an existing internal API", cause: "The security starter auto-configures a default filter chain that requires authentication for every URL and logs a generated password; no application SecurityFilterChain bean was declared to replace it.", fix: "Declare your own SecurityFilterChain bean permitting the genuinely public paths (actuator health, login, docs) and authenticating the rest, or exclude the starter entirely for an internal service on a trusted network. Remember the auto-configured chain applies to every path until you define your own bean.", d: ["Spring_Boot_Security_JWT", "Spring_Boot_AutoConfiguration"], tags: ["security", "http", "auto-configuration"] },
    { s: "404 Not Found for a path that clearly has a matching @GetMapping", cause: "The request never reached a handler: the URI does not match (trailing slash, case, or a PathPattern versus suffix-pattern difference), a context path or proxy prefix was added, or a request matcher returned 404 for an unauthenticated request instead of 401.", fix: "Set logging.level.org.springframework.web.servlet.mvc.method.annotation.RequestMappingHandlerMapping=TRACE to list the mappings actually registered and compare with the exact request URI. Then check server.servlet.context-path, prefix handling in the reverse proxy, and whether request matchers run before permitAll.", d: ["Spring_Boot_Request_Path", "Spring_Boot_Security_JWT"], tags: ["http", "routing", "debugging"] },
    { s: "RequestMappingHandlerMapping: Ambiguous handler methods mapped for '/orders/{id}'", cause: "Two or more mappings match the same request - typically overlapping patterns such as /orders/{id} versus /orders/new, or a duplicate mapping inherited from an abstract base class.", fix: "Make the specific mapping unambiguous: constrain the variable with a regex ({id:[0-9]+}), move the static segment to a distinct path, or remove the overlapping inherited mapping. The same TRACE logging prints the competing patterns so you can see the collision directly.", d: ["Spring_Boot_Request_Path"], tags: ["http", "routing", "startup"] },
    { s: "HTTP 400 with HttpMessageNotReadableException: JSON parse error: Unexpected character ('}' ...) for a body that looks correct", cause: "The body is not valid JSON for the target type - a trailing comma, a double-encoded payload, an empty body on a required @RequestBody parameter, or a client sending form-encoded data to a JSON endpoint.", fix: "Log the raw body once (mindfully, it may contain secrets) and fix the client; make genuinely optional bodies @RequestBody(required = false) or Optional; and add an @ExceptionHandler(HttpMessageNotReadableException.class) that returns a clean problem response instead of a stack trace.", d: ["Spring_Boot_Layers"], tags: ["http", "json", "validation"] },
    { s: "MethodArgumentNotValidException on a POST where the JSON looks valid, or a jakarta.validation constraint that never fires", cause: "Bean validation failed on a nested object that was not annotated with @Valid, so its constraints were never evaluated; or validation groups were configured inconsistently between the DTO and the controller.", fix: "Read the BindingResult field errors, which name the exact field, and annotate nested DTOs with @Valid so the cascade works. Remember @Valid validates at the web boundary while @Validated on a class is what enables method-level constraints on a service, and both are needed only for their own layer.", d: ["Spring_Boot_Layers", "Spring_Boot_Testing_Slices"], tags: ["validation", "http"] },
    { s: "java.lang.ClassNotFoundException: javax.servlet.http.HttpServlet, or NoClassDefFoundError: javax/xml/bind/DatatypeConverter on Java 17", cause: "A pre-Jakarta dependency still references the javax APIs, and the servlet and JAXB modules that were bundled with the JDK before Java 9 are no longer present - the classic symptom of running a Boot 2 library inside a Boot 3 application.", fix: "Migrate the dependency to its Jakarta-based release rather than adding JAXB back to the classpath, and use jdeps or the compiler errors to find every remaining javax reference. The alternative is pinning that service to Java 11 and Boot 2, which is a legitimate architectural decision but should be explicit.", d: ["Spring_Boot_Migration_3"], tags: ["migration", "classpath", "java"] },
    { s: "The application starts but is not reachable from outside the container or from a Kubernetes service", cause: "The server bound to a specific interface, the container port is not published, the containerPort is not declared, or a context path is missing from the URL being called.", fix: "Check the startup line for the bound address and port, set server.address=0.0.0.0 if you have overridden it, publish or declare the port, and include the context path in the request. Test from inside the pod with curl before blaming the network.", d: ["Spring_Boot_Deployment", "Spring_Boot_Startup"], tags: ["deployment", "containers", "networking"] },
    { s: "Liveness probe fails with 503 and the pod restarts repeatedly, roughly when the database is slow", cause: "The liveness group is including the database (or another shared dependency) health indicator, so a dependency blip restarts every replica and turns a partial outage into a total one.", fix: "Separate the health groups: liveness includes only livenessState, readiness includes readinessState plus db or your composite. Confirm what is registered at /actuator/health/readiness and /actuator/health/liveness, and remember that the probes group only exists automatically on Kubernetes or when explicitly enabled.", d: ["Spring_Boot_Observability", "Spring_Boot_Deployment"], tags: ["observability", "deployment", "health"] },
    { s: "Readiness probe fails during a rolling deploy even though the new pods work once traffic arrives", cause: "The new pod is not yet serving - the context is still starting, or a migration is holding a lock - while the terminating pod has already been removed from the endpoints, so the service has no ready backends.", fix: "Add a startup probe for slow starts, keep readiness false until the application is genuinely ready, run migrations as a separate step rather than in application startup, and widen terminationGracePeriodSeconds with a preStop sleep so in-flight requests finish.", d: ["Spring_Boot_Deployment", "Spring_Boot_Observability"], tags: ["deployment", "observability", "reliability"] },
    { s: "Spring Boot 3 migration: an old property such as spring.redis.host is ignored and a connection is attempted against localhost", cause: "Property namespaces moved between major versions (for example spring.redis.* to spring.data.redis.*) and unmapped keys are silently ignored rather than rejected.", fix: "Diff the effective configuration between versions using the configprops endpoint or an environment dump, enable strict binding during the migration so unknown keys fail fast, and update the deployment manifests and secret keys at the same time as the code.", d: ["Spring_Boot_Migration_3", "Spring_Boot_Config_Properties"], tags: ["migration", "configuration", "release"] },
    { s: "org.springframework.boot.actuate.autoconfigure.security.servlet.ManagementWebSecurityAutoConfiguration conflicts with your own rules, or /actuator/health returns 401", cause: "Actuator has its own management context path and, when Spring Security is present, its own security rules - so an application rule that permits all paths may not cover the management endpoints, and vice versa.", fix: "Use management.endpoints.web.base-path deliberately, add explicit matchers for the actuator paths in your SecurityFilterChain (ordering matters), and prefer binding management server to a separate port (management.server.port) so probes and metrics can be exposed on a different network surface than the API.", d: ["Spring_Boot_Observability", "Spring_Boot_Security_JWT"], tags: ["observability", "security", "http"] },
    { s: "Tests pass locally but fail in CI, with data missing after one test method", cause: "@DataJpaTest rolls back between methods, but the test opened its own transaction (REQUIRES_NEW, or TestTransaction) so its writes were committed and never cleaned up, contaminating later tests; or the dev database was used instead of a fresh one.", fix: "Keep one transaction per test method and avoid REQUIRES_NEW, or wrap the whole test in a cleanup strategy. Pin the test datasource with @ServiceConnection Testcontainers or an in-memory database, and never point tests at a shared developer database.", d: ["Spring_Boot_Testing_Slices"], tags: ["testing", "transactions", "database"] },
    { s: "Could not find a valid Docker environment (Testcontainers) in the build", cause: "The Docker daemon socket is not available to the test process: a remote or rootless daemon without DOCKER_HOST, a CI runner without a docker service, or Docker Desktop not running.", fix: "Point the client at the daemon with DOCKER_HOST and DOCKER_TLS_VERIFY, add a docker service to the CI job, or fall back to a GitHub Actions service container. Keep a fast, embedded-database suite for local development so the whole suite is not blocked on Docker.", d: ["Spring_Boot_Testing_Slices", "Spring_Boot_Deployment"], tags: ["testing", "containers", "ci"] },
    { s: "Scheduled job fires on every replica and downstream data is duplicated, or the same job silently stops running", cause: "Each replica runs the same @Scheduled method, and there is no distributed lock; separately, a single-threaded scheduler means one long-running job blocks every other job indefinitely.", fix: "Guard the job with a distributed lock (ShedLock on a shared store) or move it to a single-worker deployment, give the scheduler a pool, and alert on job completion. Make the job itself idempotent, because a lock alone does not protect against a crash between doing the work and recording it.", d: ["Spring_Boot_Async_Scheduling", "Spring_Boot_Deployment"], tags: ["async", "deployment", "concurrency"] },
    { s: "Logs from an async task contain a different traceId, and SecurityContextHolder returns an anonymous user inside the task", cause: "Thread-locals are not inherited by pool threads, so MDC, the SecurityContext and the servlet request context are empty or stale on the worker.", fix: "Add a TaskDecorator (or Micrometer context propagation with a ContextSnapshot) that captures and replays the context and clears it in a finally block so pooled threads do not leak state into the next task, and pass required data explicitly as method arguments where possible.", d: ["Spring_Boot_Async_Scheduling", "Spring_Boot_Observability"], tags: ["async", "observability", "threading"] },
    { s: "GET /actuator/prometheus returns 404, or the endpoint is missing entirely", cause: "No metrics registry is on the classpath, or the endpoint is not exposed over the web - exposure defaults to health and info only, and a non-web application has no HTTP endpoint at all.", fix: "Add micrometer-registry-prometheus, add prometheus to management.endpoints.web.exposure.include, and confirm the endpoint path with the management base path. Check /actuator to list what is actually exposed before changing anything else.", d: ["Spring_Boot_Observability"], tags: ["observability", "metrics", "actuator"] },
    { s: "Slow requests and a wall of nearly identical SELECT statements in the log, one per row", cause: "An N+1 select problem: a list is fetched with one query and each row's lazy association triggers another, usually during iteration or during JSON serialization.", fix: "Fetch what the response needs - @EntityGraph, join fetch, or a projection into a DTO - or enable batch fetching with hibernate.default_batch_fetch_size. Turn on statement logging briefly to confirm the pattern, and remember that a second to-many fetch needs a Set or a second query.", d: ["Spring_Boot_Nplus1"], tags: ["performance", "jpa", "sql"] },
    { s: "Answers are correct on one instance and stale on another; a cache eviction on one replica does not affect the rest", cause: "A local cache manager (Caffeine or ConcurrentMapCacheManager) keeps entries per JVM, so replicas have independent caches and independent eviction timing.", fix: "Move to a shared cache manager such as Redis, or accept bounded staleness with a short TTL and make the UI tolerate it. Whichever you pick, record it, because 'works on instance 2' is not a bug report anyone can act on.", d: ["Spring_Boot_Caching"], tags: ["caching", "scaling", "consistency"] },
    { s: "@CacheEvict and @Async annotations appear to be ignored on some methods", cause: "Both are proxy-based advice, and those methods are called internally with this or invoked on a class you instantiated yourself, so no proxy is involved.", fix: "Move the annotated methods to another bean, or self-inject the proxy (ObjectProvider or a lazy self reference) and call through it. Audit for new this-calls when a new cross-cutting annotation is added - it is the most common cause of silently inert advice.", d: ["Spring_Boot_Caching", "Spring_Boot_Async_Scheduling", "Spring_Boot_AOP_Proxy"], tags: ["aop", "caching", "proxy"] },
    { s: "With spring-boot-starter-web and spring-boot-starter-webflux both present, requests behave as blocking MVC and throughput is flat", cause: "WebApplicationType deduction prefers SERVLET when the servlet classes are on the classpath, so the reactive stack is silently unused - typically because a transitive dependency pulled in spring-boot-starter-web.", fix: "Find the culprit with a dependency tree and exclude the MVC starter, or set spring.main.web-application-type=reactive to make the choice explicit. Then verify the server startup line no longer reports Tomcat, and check that no blocking database call is on the event loop.", d: ["Spring_Boot_WebFlux"], tags: ["webflux", "classpath", "performance"] },
    { s: "Timestamps in the log are out of order and one request's lines are interleaved with another's", cause: "Concurrent request processing plus asynchronous and reactive execution, so a chronological sort of the log is not a valid way to reconstruct a request.", fix: "Put the correlation identifiers in the log - traceId and spanId from Micrometer, plus your own request id - and group by them in your log backend rather than by timestamp. This is also the fastest way to see the wall-clock cost of a request end to end.", d: ["Spring_Boot_Observability"], tags: ["observability", "logs", "debugging"] },
    { s: "A message-driven flow loses or duplicates side effects: the order is rolled back but the notification still went out, or the same notification arrives twice", cause: "The dual-write problem: the message was published inside a transaction, so it can be sent before the commit (the consumer sees no data) or survive a rollback; and at-least-once delivery redelivers on failure or rebalance.", fix: "Use the transactional outbox - order plus an intent row committed together, published by a separate relay - and make the consumer idempotent with a unique constraint on the message or business key written in the same transaction as the effect.", d: ["Spring_Boot_Messaging"], tags: ["messaging", "reliability", "transactions"] },
    { s: "The same @Scheduled job runs on every replica and duplicates work, or jobs run minutes late", cause: "Each replica executes the schedule independently, and the default scheduler is single-threaded so one slow job delays all the others.", fix: "Guard the job with a distributed lock or move it to a single-worker deployment, give the scheduler a pool, and make the job idempotent because a lock does not protect against a crash after the work. Monitor job duration and last-success time, not just that the job exists.", d: ["Spring_Boot_Async_Scheduling", "Spring_Boot_Deployment"], tags: ["async", "deployment", "concurrency"] },
    { s: "Deployments cause a burst of 502 or connection reset responses even though the pods are healthy", cause: "The termination signal arrives while requests are still in flight, and the pod leaves the endpoints and starts closing the connector at the same time.", fix: "Enable graceful shutdown with a bounded per-phase timeout, add a preStop sleep so endpoint removal propagates before the kill, and make terminationGracePeriodSeconds longer than your slowest request. Scale up before draining so there is always spare capacity.", d: ["Spring_Boot_Deployment"], tags: ["deployment", "reliability", "http"] },
    { s: "The application ignores your configuration file entirely after a refactor, or picks up a different value than expected", cause: "Configuration precedence: command line arguments and environment variables outrank profile-specific and packaged property files, and property namespaces moved between major Boot versions so old keys are silently ignored.", fix: "Print the effective configuration (the configprops endpoint, or an environment dump at startup) and compare it with the file, check the active profile, and remove stale environment variables from the deployment manifests. In tests, @TestPropertySource and inlined properties outrank everything else, which is its own surprise.", d: ["Spring_Boot_Config_Properties", "Spring_Boot_Migration_3"], tags: ["configuration", "deployment", "debugging"] },
  ],
  interview: [
    { q: "What is Spring Boot, and what does it actually give you over plain Spring Framework?", a: "Spring Boot is a set of auto-configuration, starter dependencies and embedded runtime conventions on top of Spring Framework. Mechanism: it detects classes on the classpath, imports matching auto-configurations, binds configuration to typed properties, and starts an embedded server. Tradeoff: magic means surprises - a default you did not know about can change behaviour, so you read the auto-configuration report. When it bites: when a bean is missing or a default binds unexpectedly, and the fix is usually the condition report rather than a guess.", level: "junior", d: ["Spring_Boot_AutoConfiguration", "Spring_Boot_Roadmap"] },
    { q: "Explain dependency injection and constructor injection. Why is one form preferred?", a: "DI means the container supplies a collaborator rather than the class constructing it, which decouples the service from its dependency and makes the dependency explicit. Constructor injection makes the dependency part of the type's signature, allows final fields, and fails fast at startup when it cannot be satisfied. Field injection hides dependencies and requires a container or reflection to test. It bites whenever someone refactors a class and silently adds a field injection nobody reviewed.", level: "junior", d: ["Spring_Boot_Startup", "Spring_Boot_Layers"] },
    { q: "What is the ApplicationContext, and how does it differ from a plain BeanFactory?", a: "The ApplicationContext is the central interface that extends BeanFactory with enterprise features: internationalisation, event publishing, resource loading, and automatic detection of annotated components. Mechanism: it holds bean definitions, instantiates singletons through BeanPostProcessors, and publishes lifecycle events. Tradeoff: the extra features make it a service locator if you inject it everywhere. It bites when a class holds the context to look beans up dynamically, which is the service-locator anti-pattern in disguise.", level: "junior", d: ["Spring_Boot_Startup", "Spring_Boot_Bean_Lifecycle"] },
    { q: "What happens between pressing run and the first accepted HTTP request in a Spring Boot application?", a: "The main method calls SpringApplication.run, which prepares the environment, creates the context, applies auto-configuration, refreshes the context - instantiating and wiring singletons - and starts the embedded web server, finishing with ApplicationReadyEvent. Any failure during refresh aborts startup with a BeanCreationException. The trade-off is that most errors appear at startup rather than at first use, which is good, but a failure in a BeanPostProcessor or a condition can produce a very indirect message. It bites when a database migration is run during startup and every replica races for DDL locks.", level: "junior", d: ["Spring_Boot_Startup"] },
    { q: "How does a request get from the browser to your database and back? Name each hop.", a: "The browser sends the request to the connector, which builds the servlet filter chain, so authentication, logging and CORS filters run first. The DispatcherServlet then finds a handler with a HandlerMapping, invokes it through a HandlerAdapter with argument resolvers, and the controller delegates to a service, which goes through the transaction proxy to a repository and the database. The response travels back up the same chain, with serialization by Jackson. It bites when you put logic in the wrong layer: a lazy field touched during serialization, after the transaction has closed, is the classic LazyInitializationException.", level: "junior", d: ["Spring_Boot_Request_Path", "Spring_Boot_Layers"] },
    { q: "What is auto-configuration, and how would you override one bean without excluding the whole auto-configuration?", a: "Auto-configuration is a conditional bean definition supplied by a starter: it activates when the relevant classes are present, and backs off when you define the bean yourself. Mechanism: candidates come from AutoConfiguration.imports, and @ConditionalOnMissingBean is the back-off signal. So defining a bean of the same type in your configuration is enough - the auto-config steps aside. Tradeoff: because conditions are evaluated at parse time, ordering between auto-configurations is expressed with @AutoConfigureBefore/After, and blindly using @ConditionalOnBean on your own beans is fragile. It bites when a starter is missing entirely, so no candidate ever runs.", level: "mid", d: ["Spring_Boot_AutoConfiguration"] },
    { q: "How does @ConfigurationProperties binding work, and why is it better than @Value?", a: "The Environment is queried using relaxed binding rules: canonical kebab-case names map to env vars, system properties, YAML and profile-specific files, and the result is bound to a typed object with conversion, default values and JSR-380 validation. @Value is a single placeholder with no validation, no defaults beyond the placeholder, and poor error messages. Tradeoff: binding validates at startup, which means a missing variable fails deployment instead of production - usually what you want. It bites on naming, where APP_REGION resolves to app.region but DATASOURCE_URL does not resolve to spring.datasource.url.", level: "mid", d: ["Spring_Boot_Config_Properties"] },
    { q: "What is a Spring bean lifecycle callback, and in what order do the callbacks run?", a: "The container instantiates the bean, populates its properties through dependency injection, invokes Aware callbacks, then runs @PostConstruct, InitializingBean.afterPropertiesSet and a custom init-method in that order; on shutdown it runs @PreDestroy, DisposableBean.destroy and the custom destroy-method. Mechanism: BeanPostProcessors drive most of these, which is why a proxy is already in place when @PostConstruct runs. Tradeoff: initialisation order is a frequent source of surprise for resources acquired in init methods. It bites when @PostConstruct touches a lazy proxy that is not yet usable, or when init code calls a method that other beans have not finished building.", level: "mid", d: ["Spring_Boot_Bean_Lifecycle"] },
    { q: "Explain @Transactional: what does the annotation actually cause, and where does the boundary sit?", a: "The annotation is advice on a proxy; when a call arrives through the proxy, the transaction manager begins a transaction on the current thread, binds a connection to it, runs the method, then commits or rolls back and unbinds. The boundary is the annotated public method on a proxied bean. Tradeoff: the database gives you isolation, and you choose the scope - too wide wastes locks and connections, too narrow loses atomicity. It bites in three classic ways: self-invocation bypasses the proxy, private or final methods cannot be advised, and checked exceptions do not roll back by default.", level: "mid", d: ["Spring_Boot_Transactions", "Spring_Boot_AOP_Proxy"] },
    { q: "What are transaction propagation levels, and when would you use each one?", a: "REQUIRED (the default) joins the current transaction or creates one; REQUIRES_NEW suspends it and starts a genuinely independent transaction on a second connection; NESTED uses a savepoint inside the current transaction; NOT_SUPPORTED and READ_ONLY suspend or relax the current transaction. Mechanism: the transaction manager looks at the current transaction state through TransactionSynchronizationManager and binds a new one. Use REQUIRES_NEW for records that must survive the outer failure - audit rows, error logs - and NESTED for partial rollback within one unit of work. It bites with pool exhaustion, because a suspended transaction still holds its connection while the new one checks out another.", level: "mid", d: ["Spring_Boot_Transactions"] },
    { q: "Why does UnexpectedRollbackException appear even though the exception was caught, and what are your options?", a: "The inner call joined the outer transaction, so the failure marked the shared transaction rollback-only; catching the exception in application code does not clear that flag, and the commit attempt at the end fails loudly. Options: let the exception propagate, rethrow a translated exception above the boundary, or isolate the inner work with REQUIRES_NEW if it must survive. It bites hardest in flows that try to be resilient - partial success handling - where the developer reasonably believes the failure was handled.", level: "mid", d: ["Spring_Boot_Transactions"] },
    { q: "What is the N+1 select problem, and what are the remedies in order of preference?", a: "It is one query to fetch a list plus one query per row to initialise a lazy association, so the query count scales with the result set. Remedies: fetch what you need with a join fetch or @EntityGraph, project straight into a DTO, enable batch fetching (hibernate.default_batch_fetch_size), or map one collection as a Set. Preference order matters: a projection is often better than a join fetch, because it avoids loading entities you never use. It bites hardest with pagination, where in-memory pagination over a fetch-joined collection silently returns wrong page sizes.", level: "mid", d: ["Spring_Boot_Nplus1"] },
    { q: "How does Spring's @Cacheable work, and what are the invalidation strategies?", a: "Cache abstraction sits between your method and its logic: a CacheInterceptor looks up a Cache from the CacheManager, returns the stored value on a hit, and on a miss invokes the method and stores the result. That is cache-aside. Invalidation is evict-on-write with @CacheEvict, update-in-place with @CachePut, or time-based expiry; for lists, allEntries eviction or versioned keys. Tradeoff: caches hide staleness and make debugging harder, so a short TTL plus explicit eviction is safer than clever invalidation. It bites with multi-instance deployments, where a local cache means each replica has its own eviction timing.", level: "mid", d: ["Spring_Boot_Caching"] },
    { q: "How does Spring Security handle a request, and what is the role of the filter chain?", a: "Spring Security is built on the servlet filter chain: SecurityFilterChain implementations form a FilterChainProxy that runs filters in a defined order, with authentication filters populating a SecurityContext and authorization filters deciding access, followed by exception translation that distinguishes unauthenticated (entry point) from unauthorized (denied). Mechanism: the SecurityContextHolder is a thread-local, which is why it is cleared per request. Tradeoff: the whole security model is expressed as filters and matchers, which is powerful and easy to mis-order. It bites when a rule is declared on a path that is never actually requested, or when an exception is thrown before the exception translation filter runs.", level: "mid", d: ["Spring_Boot_Security_JWT"] },
    { q: "How does a stateless JWT API authenticate a request, and what security decisions are involved?", a: "The resource server filter parses the bearer token, validates its signature against keys fetched from the issuer's JWKS, checks issuer, audience and expiry, and maps claims into authorities; the result becomes an Authentication in the SecurityContext for that request only. Decisions: which signing keys are trusted, where roles come from, and whether the API is behind TLS. It bites with clock skew, key rotation and with a permissive default that treats any successful signature as full access.", level: "mid", d: ["Spring_Boot_Security_JWT"] },
    { q: "Why is field injection with @Autowired considered an anti-pattern?", a: "Because it makes dependencies invisible, allows objects to exist with null fields, and forces tests to use a container or reflection instead of a constructor. Constructor injection makes the dependency list part of the type, permits final fields, and gives a compile-time guarantee. Tradeoff: constructor injection can make classes with many dependencies look awkward, which is a design signal rather than an argument for the alternative. It bites in refactorings, when dependencies are added without changing any signature and nobody reviews the diff.", level: "junior", d: ["Spring_Boot_AntiPatterns"] },
    { q: "What does @Async do, and why is the proxy requirement important?", a: "@Async is advice that hands the invocation to a TaskExecutor and returns immediately, optionally with a CompletableFuture. Because it is proxy-based, the call must arrive through the proxy: a this call or a private method is never intercepted and runs synchronously, which is the usual reason an async method seems not to work. Tradeoff: you lose the thread's context, so MDC, the SecurityContext and the transaction are absent on the worker. It bites with an unbounded default executor, which turns a traffic spike into an out-of-memory error.", level: "mid", d: ["Spring_Boot_Async_Scheduling"] },
    { q: "How do you make logs, traces and security context follow an async task?", a: "Thread-locals do not propagate, so you must copy them explicitly: a TaskDecorator for @Async and scheduled tasks, Micrometer's context-propagation library with ContextSnapshot for arbitrary reactive and imperative boundaries, and a TaskDecorator for schedulers so MDC, SecurityContext and RequestContextHolder are captured and always cleared. Tradeoff: propagation must be bounded, otherwise a long-lived request context is retained on a pool thread. It bites most visibly in observability, when every async log line looks like a separate incident.", level: "senior", d: ["Spring_Boot_Async_Scheduling", "Spring_Boot_Observability"] },
    { q: "How would you design a system that publishes an event reliably after committing an order?", a: "Use the transactional outbox: write the order and an outbox row in one database transaction, then have a separate relay publish to the broker and mark rows as sent, with retries and a dead-letter path. The honest delivery guarantee is at-least-once, so consumers dedupe using a unique constraint written in the same transaction as the effect. Tradeoff: added latency from polling and operational complexity, in exchange for never losing a message. It bites in the ordering and duplicate handling, not in the publishing.", level: "senior", d: ["Spring_Boot_Messaging"] },
    { q: "What are the guarantees of a message broker, and how do you make a consumer idempotent?", a: "Most brokers give at-least-once delivery per consumer: messages can be redelivered after a rebalance, a restart or a processing failure, and ordering is only guaranteed within a partition. Idempotency comes from the consumer side - a unique constraint on a message id or business key, written atomically with the effect, or an inbox table - so a duplicate insert fails harmlessly. Tradeoff: exactly-once processing needs deduplication plus idempotent effects, not just a broker setting. It bites when the deduplication record and the effect are in different transactions, which reintroduces the duplicate.", level: "senior", d: ["Spring_Boot_Messaging"] },
    { q: "What are Micrometer, the actuator and OpenTelemetry, and how do they relate?", a: "Actuator exposes operational endpoints, Micrometer is the metrics facade that records meters, timers and distributions and publishes them to a registry, and OpenTelemetry supplies distributed tracing and context propagation. In Spring Boot, Micrometer Observation is the instrumenting API, and Micrometer Tracing bridges it to a tracer such as the OTel SDK, which then exports over OTLP. Tradeoff: each layer is useful alone, and adding all three means learning three vocabularies. It bites with cardinality explosion in metrics and with sampling that hides the errors you need.", level: "senior", d: ["Spring_Boot_Observability"] },
    { q: "How do liveness and readiness probes differ, and why does mixing them cause outages?", a: "Liveness asks whether the process should be restarted, so it must only check things a restart fixes; readiness asks whether the process should receive traffic, so it may include database connectivity, cache warm-up and downstream dependencies. Mixing them means a database blip restarts every replica simultaneously and turns a dependency outage into a full outage. In Boot you express this with health groups under the probes group. Tradeoff: stricter readiness means fewer bad requests but also fewer healthy pods during partial degradation.", level: "senior", d: ["Spring_Boot_Observability", "Spring_Boot_Deployment"] },
    { q: "How do you size a connection pool for a containerised service?", a: "Work from the database's capacity: total connections across all replicas must fit under the server's limit with headroom for admin, migrations and monitoring, so pool size per replica is a division, not a guess. Then keep transactions short so connections are returned quickly, and use a bounded pool for @Async work separately. Tradeoff: a larger pool improves per-instance throughput but can exhaust the database and increase contention. It bites under autoscaling, when a spike in replicas multiplies the connection count at exactly the moment the database is already struggling.", level: "senior", d: ["Spring_Boot_AutoConfiguration", "Spring_Boot_Deployment"] },
    { q: "Platform threads versus virtual threads: when does each make sense in a Spring Boot service?", a: "Platform threads are expensive to create and hold an OS stack, so throughput is bounded by the pool size; virtual threads (Java 21, enabled with spring.threads.virtual.enabled) are cheap and let blocking code scale, provided the real resource - the database pool, a downstream rate limit - is not the constraint. With virtual threads you still need pool-like limits on the scarce resource, and pinning or synchronized blocks can negate the benefit. Tradeoff: virtual threads simplify blocking-heavy services, but reactive stacks are still the better fit for very high concurrency per instance.", level: "senior", d: ["Spring_Boot_Async_Scheduling", "Spring_Boot_WebFlux"] },
    { q: "What is graceful shutdown, and what does a zero-downtime deployment need besides it?", a: "Graceful shutdown stops accepting new requests, lets in-flight requests finish within a timeout, and closes the context and the pool. For a rolling update you also need readiness to turn false before termination, a preStop delay so endpoint removal propagates, and a termination grace period longer than your slowest request. Tradeoff: a longer grace period makes rollouts slower and leaves a pod draining for that time. It bites when in-flight requests are longer than the grace period, which silently becomes a truncated response.", level: "mid", d: ["Spring_Boot_Deployment"] },
    { q: "Why do you deploy a database migration as a separate step rather than from application startup?", a: "Schema changes and application rollout have different failure modes and different rollback semantics: once data has been transformed, rolling the code back may be impossible, so the schema must be backward compatible first, then the code, then the cleanup. Running migrations at startup couples them to pod lifecycle, makes concurrent replicas race for DDL locks, and turns a slow migration into a failing rollout. Tradeoff: a separate migration step is an extra pipeline stage and needs its own permissions and audit. It bites when the change is not backward compatible and the old version is still serving traffic during a rolling deploy.", level: "senior", d: ["Spring_Boot_Deployment", "Spring_Boot_Migration_3"] },
    { q: "What are the main layers in a Spring Boot web application, and what belongs in each?", a: "Browser, then servlet filters (security, logging, CORS), the DispatcherServlet, controller, DTO, service, and then the persistence stack - repository, JPA/Hibernate, database - with cross-cutting concerns such as transactions and AOP around the service. Controllers speak HTTP and validate; services own use cases and transaction boundaries; repositories speak persistence. The layering matters because it lets the persistence model change without breaking the API, and it keeps transaction scope in one place. It bites when a controller returns entities directly, which couples the database schema to your public contract and moves lazy loading into serialisation.", level: "junior", d: ["Spring_Boot_Layers"] },
    { q: "How would you design a REST API's error handling in Spring Boot?", a: "A @RestControllerAdvice with specific @ExceptionHandler methods per exception family, mapping each to a status and a consistent problem body (type, title, status, detail, plus a trace identifier), with validation errors reported field by field. Reserve the catch-all for genuinely unexpected failures, log it with the cause, and return a generic body. Tradeoff: a rich error contract is a real API surface that clients depend on, so it is worth versioning deliberately. It bites when a catch-all flattens everything to 500, which silently breaks clients that branch on 400 or 404.", level: "mid", d: ["Spring_Boot_Layers", "Spring_Boot_AntiPatterns"] },
    { q: "What are DTOs and why do you map between entities and DTOs?", a: "A DTO is a data shape defined for a use case, decoupled from both the database schema and the internal model. Mapping gives you control over which fields are exposed, where validation lives, and how you version an API without a migration. Tradeoff: mapping code is boilerplate, and hand-written mappers drift; that is why records, MapStruct and interface-based mappers are popular. It bites with high-traffic paths where per-request allocation and reflection cost shows up, and with bidirectional entity graphs that would serialise infinitely if you returned them.", level: "junior", d: ["Spring_Boot_Layers", "Spring_Boot_Data_Model"] },
    { q: "What is the difference between @Valid and @Validated, and where does each belong?", a: "@Valid is the specification-driven annotation the web layer uses to trigger cascading validation of a request object; @Validated is Spring's annotation that adds method-level validation (constraint annotations directly on parameters) and groups support, so it belongs on a service class. Mechanism: both are processed by the same Bean Validation engine, but the trigger points differ. Tradeoff: knowing which one you needed saves a long debugging session. It bites when a service constraint is written without @Validated, so it is silently never evaluated.", level: "junior", d: ["Spring_Boot_Layers"] },
    { q: "How do you design a JPA entity model for a typical commerce domain?", a: "Entities own their columns and relationships; a parent owns the collection only as a mappedBy inverse view, while the child carries the foreign key and the owning side. Use an embedded composite key where the identity is genuinely composite, a business key or a surrogate id deliberately, and string enums so the database is readable. Tradeoff: bidirectional associations are convenient and produce infinite or N+1 problems on serialisation; unidirectional ones with explicit joins are boring and safe. It bites when the inverse side is treated as writable, or when equals/hashCode uses a generated id and objects vanish from sets after flush.", level: "mid", d: ["Spring_Boot_Data_Model"] },
    { q: "What is LAZY versus EAGER, and what are the JPA defaults?", a: "EAGER loads the association as part of the owning query; LAZY returns a proxy that loads on first access. The defaults are asymmetric: @ManyToOne is EAGER and @OneToMany is LAZY, which is why an entity with several eager associations produces a cartesian-join explosion. Tradeoff: lazy is not free - access after the session closes throws LazyInitializationException, and access inside a loop produces N+1. The right question is which shape each use case needs, expressed with fetch joins or entity graphs. It bites when someone flips one association to LAZY to fix a query and creates a worse problem somewhere else.", level: "mid", d: ["Spring_Boot_Data_Model", "Spring_Boot_Nplus1"] },
    { q: "What is the persistence context, and what does Open Session in View do?", a: "The EntityManager maintains a first-level cache within a transaction or request, so loading the same entity twice returns the same instance and dirty checking works on managed objects. Open Session in View keeps that session bound to the thread for the entire HTTP request so lazy loading still works during serialisation. Tradeoff: OSIV trades resource usage for convenience - one pooled connection per in-flight request for the whole rendering, and queries that appear from code that never touched a repository. The modern default is OSIV off plus DTOs. It bites hardest under load, where the connection pool exhausts for reasons that look unrelated to the database.", level: "senior", d: ["Spring_Boot_Nplus1", "Spring_Boot_Transactions"] },
    { q: "How do you fetch exactly the data a screen needs?", a: "Choose deliberately: a projection query or JPQL constructor expression straight into a DTO for read paths, a join fetch or @EntityGraph for entity graphs, and batch fetching as a fallback for several small loads. Tradeoff: projections are the most efficient and the least flexible - no lazy loading, no persistence semantics, and you write out every column. It bites with paging over a fetch-joined collection, where the join happens in memory and the page size is wrong.", level: "senior", d: ["Spring_Boot_Nplus1"] },
    { q: "How does Spring AOP work, and what are its limits?", a: "Spring AOP is proxy-based: the container wraps the bean in a JDK dynamic proxy (when interfaces are used) or a CGLIB subclass, and the advice runs when calls arrive through that proxy. Limits follow directly: no self-invocation, no private or final methods, and no interception of objects the container does not manage. Tradeoff: proxy-based advice is unobtrusive and requires no bytecode weaving, which is exactly why it is invisible until you hit one of those limits. It bites with @Transactional, @Async, @Cacheable and @Retryable, all of which fail silently rather than loudly.", level: "mid", d: ["Spring_Boot_AOP_Proxy"] },
    { q: "How do you measure and control database connection usage?", a: "Bound the pool per instance (Hikari by default), keep it small enough that replicas x pool size stays under the database limit, keep transactions short so connections are returned promptly, and use leakDetectionThreshold to catch connections held outside a transaction. Tradeoff: a bigger pool improves per-instance throughput but increases contention and can exhaust the server, so sizing is a function of the database's capacity, not of the framework. It bites under autoscaling, when the connection count multiplies exactly when the database is already loaded.", level: "senior", d: ["Spring_Boot_AutoConfiguration", "Spring_Boot_Transactions"] },
    { q: "What is the difference between JPA and R2DBC, and when would you use each?", a: "JPA is a blocking, specification-rich object-relational mapper with first- and second-level caching, dirty checking and a mature query language; R2DBC is a non-blocking Reactive Streams driver that leaves mapping, repositories and transactions to you. Choose JPA for the write-heavy, logic-heavy core where entity semantics pay off, and R2DBC where concurrency per instance dominates and everything in the path can be non-blocking. Tradeoff: mixing them means a reactive request thread blocking on JDBC, which is the worst of both. It bites when a service is reactive but one repository is JPA, and throughput stays flat at low CPU.", level: "senior", d: ["Spring_Boot_WebFlux"] },
    { q: "What problem does WebFlux solve, and when is it the wrong choice?", a: "WebFlux lets a thread handle many concurrent requests by never blocking - a few event loops drive non-blocking I/O, so throughput scales with the number of connections rather than the number of threads. It is the wrong choice for CPU-bound work, for services dominated by JDBC access, or when a large part of the stack has no non-blocking client. Tradeoff: it imposes reactive types and operator-composition expertise throughout the code. It bites the moment a blocking library is called on the event loop, and the symptom - high latency at low CPU - is easy to misdiagnose.", level: "senior", d: ["Spring_Boot_WebFlux"] },
    { q: "What are the test slices in Spring Boot, and how do you choose between them?", a: "There is a unit level with no Spring, a @JsonTest for serialisation, a @WebMvcTest for the web layer with mocked collaborators, a @DataJpaTest for repositories on an embedded database, a @RestClientTest for HTTP clients against a mock server, and a @SpringBootTest with Testcontainers for real integration. Choose the narrowest slice that can fail for the reason you care about, and pay for a full context only when the failure mode is wiring. Tradeoff: narrow slices are fast and precise but can mock away the very thing that breaks. It bites with @WebMvcTest - it does not load your services, so a broken service contract passes until integration tests.", level: "mid", d: ["Spring_Boot_Testing_Slices"] },
    { q: "What are mocks for, and what should you never mock?", a: "Mock at your own boundaries - network clients, clocks, message brokers, third-party SDKs - so tests are fast, deterministic and independent. Never mock the thing whose behaviour you are trying to verify: your repositories, the framework, or your own collaborators whose contract is in question. Tradeoff: a test full of mocks asserts your own assumptions instead of reality. It bites with over-verified interactions, where renaming a private method breaks a test that was checking the implementation rather than the outcome.", level: "mid", d: ["Spring_Boot_Testing_Slices", "Spring_Boot_AntiPatterns"] },
    { q: "What is Testcontainers for, and what does it change about your test strategy?", a: "It starts real dependencies - database, broker, cache - as Docker containers for the lifetime of the test, wiring them through @ServiceConnection so Boot uses them automatically. The payoff is fidelity: real dialect, real locking, real migrations, so a test cannot pass on H2 and fail in production. Tradeoff: containers need Docker and add seconds to startup, so they belong in a small integration suite while fast unit and slice tests run on embedded substitutes. It bites when the whole suite depends on Docker and local development slows to a crawl.", level: "mid", d: ["Spring_Boot_Testing_Slices"] },
    { q: "What is a backward-compatible schema change, and why does it matter for rolling deployments?", a: "A change the previous application version can keep running against - add a nullable column, add a table, stop writing a column before you start relying on it, backfill in batches, and only then enforce constraints. During a rolling update both versions serve traffic, so anything destructive breaks the old pods. Tradeoff: the expand-migrate-contract sequence takes longer and leaves temporary code. It bites when a rename or a NOT NULL addition is deployed in the same release as the code that depends on it, and the rollout is stuck halfway.", level: "senior", d: ["Spring_Boot_Migration_3", "Spring_Boot_Deployment"] },
    { q: "What does migrating from Spring Boot 2 to 3 actually involve?", a: "Move to Java 17 and Spring Framework 6, switch javax to jakarta across persistence, validation, servlet and annotations, rebuild dependencies against the new namespace, adapt Spring Security 6 to the lambda DSL, update moved property namespaces, and expect Hibernate 6 differences in naming and type handling. The compiler is your friend for the namespace work; the failure mode to fear is silent - an unmapped property or a changed default. Tradeoff: a staged migration with both versions running side by side is more work but far safer. It bites in third-party libraries that have not been rebuilt, and in tests relying on H2 or dialect behaviour that changed.", level: "senior", d: ["Spring_Boot_Migration_3"] },
    { q: "How do you make a Spring Boot application observable in production?", a: "Expose health, metrics and structured logs through the actuator, publish metrics via Micrometer to a Prometheus-compatible registry, instrument with Micrometer Observation so HTTP, JDBC and messaging produce spans, export traces over OTLP, and put trace and span identifiers in every log line. Tradeoff: instrumentation has a cost and cardinality has a limit, so name and label deliberately. It bites when a metric has a user id in a tag, which is the fastest way to take down a metrics backend.", level: "senior", d: ["Spring_Boot_Observability"] },
    { q: "Why can a long transaction hurt a database, and what is the guideline?", a: "A transaction holds locks and a pooled connection for its whole duration, so a long one increases lock waits, blocks concurrent work, delays vacuum or log flushing, and can exhaust the connection pool. Guideline: keep the transaction as short as possible, containing only the state change, and do remote calls, file I/O and message publishing outside it, using compensation rather than one big atomic block. Tradeoff: splitting the transaction means partial failure is possible and must be designed for. It bites most visibly when a slow third-party call is inside @Transactional and every concurrent request queues behind it.", level: "senior", d: ["Spring_Boot_Transactions", "Spring_Boot_AntiPatterns"] },
    { q: "How do you make a scheduled job safe to run in a horizontally scaled application?", a: "Ensure exactly-once-effect semantics: use a distributed lock such as ShedLock against a shared store, or move the job to a single-worker deployment or a leader-elected consumer, and make the job itself idempotent. Also give the scheduler a pool so one slow job does not delay others, and monitor last-success time. Tradeoff: a lock needs a shared, highly available store and does not protect against a crash after the work but before the record. It bites when the job is not idempotent, so even a correctly working lock occasionally duplicates work.", level: "senior", d: ["Spring_Boot_Async_Scheduling"] },
    { q: "What is the difference between servlet Filters and HandlerInterceptors, and when do you use each?", a: "Filters are part of the servlet specification and run around the whole DispatcherServlet, so they can wrap the request and response, touch security context, CORS or request logging, and apply to static resources. Interceptors are Spring MVC's hook, running after handler mapping and able to read handler metadata and post-handle information such as the model and view. Use filters for cross-cutting transport concerns and interceptors for MVC-specific ones. It bites when you put a filter in the wrong place, or omit it for a URL that the DispatcherServlet never serves.", level: "mid", d: ["Spring_Boot_Request_Path"] },
    { q: "How do you choose between pessimistic and optimistic locking in JPA?", a: "Optimistic locking with @Version checks the version on update and throws OptimisticLockException, so it suits read-mostly workloads with rare contention. Pessimistic locking with SELECT ... FOR UPDATE or a lock timeout suits hot rows where you need the read and the write to be indivisible, at the cost of holding locks for the transaction's duration. Tradeoff: optimistic gives better concurrency and worse retry behaviour; pessimistic gives fewer conflicts and more blocking. It bites when an application retries a conflict without re-reading, or when a lost update is possible because the entity was detached and re-saved without a version check.", level: "senior", d: ["Spring_Boot_Transactions", "Spring_Boot_Data_Model"] },
    { q: "What is a virtual thread, and how does it change Spring Boot capacity planning?", a: "Virtual threads are JVM-managed, lightweight threads that unmount from the carrier platform thread when they block, so millions can exist and blocking calls are cheap again. In Spring Boot, spring.threads.virtual.enabled=true (Java 21) makes the embedded server and executor use them, and you then stop sizing request threads and start sizing the scarce resources - the database pool, downstream rate limits, CPU. Tradeoff: you lose per-thread thread-local guarantees in some places and must propagate context explicitly. It bites when a virtual-thread service sits in front of a database pool of ten, where throughput is unchanged but memory grows.", level: "senior", d: ["Spring_Boot_Async_Scheduling", "Spring_Boot_Deployment"] },
    { q: "What happens during a graceful shutdown of a Spring Boot application?", a: "With server.shutdown=graceful, the connector stops accepting new requests, the web server drains in-flight exchanges up to spring.lifecycle.timeout-per-shutdown-phase, then beans are destroyed in reverse dependency order via @PreDestroy, DisposableBean and custom destroy methods, and the data sources and executors close. Tradeoff: the drain period lengthens pod termination, and a long-running request can exceed the timeout and be cut off. It bites when shutdown hooks do real work - draining queues, calling remote services - with no timeout budget, and the pod is killed mid-hook.", level: "mid", d: ["Spring_Boot_Deployment", "Spring_Boot_Bean_Lifecycle"] },
    { q: "How do you make an external HTTP call safely from a Spring Boot service?", a: "Wrap the client with explicit connect and read timeouts, a bounded retry policy with backoff and jitter, a circuit breaker and a concurrency bulkhead, and log or metric the outcome. Use a shared, properly configured RestClient or WebClient rather than constructing a new client per request, so pools and timeouts are uniform. Tradeoff: retries can amplify load on a struggling dependency, so they must be budgeted. It bites hardest when there is no timeout at all: one slow partner pins every request thread and the service falls over without the partner being visibly unhealthy.", level: "senior", d: ["Spring_Boot_AntiPatterns", "Spring_Boot_Async_Scheduling"] },
    { q: "What is idempotency, and how do you implement it in a Spring Boot service?", a: "An idempotent operation produces the same result whether it is applied once or many times, which is what makes retries and redeliveries safe. Implement it by accepting a client-supplied idempotency key, storing it with the result under a unique constraint, and returning the stored result on a repeat; for consumers, dedupe on the message id or business key in the same transaction as the effect. Tradeoff: it requires storage and a defined retention window, and it only helps if every writer goes through the same path. It bites when a key is scoped per request but the effect spans requests, so a retry creates a second order.", level: "senior", d: ["Spring_Boot_Messaging", "Spring_Boot_Data_Model"] },
    { q: "What is a BeanPostProcessor, and why does it matter that Boot registers some of them very early?", a: "A BeanPostProcessor gets every bean before and after its own initialisation callbacks, which is how @Autowired injection, annotation processing and proxying are implemented. Boot registers infrastructure post-processors such as the auto-configuration and configuration-property ones before your beans are created. Mechanism: registering them early means they see every bean, including the infrastructure beans, so ordering matters - PriorityOrdered post-processors run in a second, earlier pass. It bites when a custom post-processor silently does not apply to the beans you expected.", level: "mid", d: ["Spring_Boot_Bean_Lifecycle", "Spring_Boot_Startup"] },
    { q: "How do you validate configuration at startup, and what do you gain?", a: "Put jakarta.validation constraints on a @ConfigurationProperties class, register it with @ConfigurationPropertiesScan or @EnableConfigurationProperties, and make sure the validation is applied so binding fails fast. You also want constructor binding with a record or a single constructor, plus @NotNull, @Min and @Pattern constraints, and an assertion message that names the property. The gain is that a missing or malformed variable stops the deployment rather than the business. It bites when the properties class is only registered by a component scan that does not pick up plain @Component classes.", level: "mid", d: ["Spring_Boot_Config_Properties"] },
    { q: "Two beans of the same type exist and an injection point cannot choose. How do you resolve it cleanly?", a: "Mark the intended default with @Primary when one implementation is the norm, and use @Qualifier on the injection point when the choice is per-consumer. If the choice is per-environment, express it with @Profile on the implementations instead. Tradeoff: qualifiers everywhere are noise, so prefer profiles or distinct types when the variants are genuinely different things. It bites when a third-party starter adds a bean of a type you also define and your application suddenly fails to start on a version bump.", level: "junior", d: ["Spring_Boot_Startup", "Spring_Boot_AOP_Proxy"] },
    { q: "What is the Condition Evaluation Report, and when is it the fastest way to solve a startup problem?", a: "Started with --debug or debug=true, the report lists every auto-configuration considered, which conditions matched or did not, and why. It is the fastest route when a bean you expect is missing, because it distinguishes 'the auto-configuration was never imported' from 'it was imported but a condition failed'. Tradeoff: it is verbose and only covers conditions, not component scanning, so a missing @Service will not appear there. It bites when you read it the wrong way round and conclude a matching auto-configuration must have created your bean.", level: "mid", d: ["Spring_Boot_AutoConfiguration", "Spring_Boot_Startup"] },
    { q: "How do you manage configuration across environments - dev, staging, production?", a: "Keep one immutable artifact, feed it configuration at runtime, and use profiles to select overlays rather than to hold secrets. Sensible defaults live in the properties class, environment-specific values come from environment variables, mounted files or a config server via spring.config.import, and secrets are injected by the platform. Tradeoff: this means more up-front discipline because nothing is baked in. It bites when someone bakes a profile-specific file into the image, which makes every environment change a rebuild and a full rollout.", level: "junior", d: ["Spring_Boot_Config_Properties", "Spring_Boot_Deployment"] },
    { q: "When do you use @ResponseStatus, and when do you prefer an exception handler?", a: "@ResponseStatus is for a simple, stable mapping between one exception type and one status code, and it keeps the mapping on the exception itself. An @ExceptionHandler in an advice class is for everything else: validation errors with a field list, domain errors with a body, and anything that needs logging or context. Tradeoff: the handler is more powerful and also more global, so it is easy to centralise too much logic. It bites when a catch-all handler hides a status code a client depends on.", level: "junior", d: ["Spring_Boot_Layers", "Spring_Boot_AntiPatterns"] },
    { q: "What does @SpringBootTest do, and when is it the right level of test?", a: "It boots the real application context - all auto-configuration, all beans, the full filter chain - optionally with a real web server when webEnvironment is RANDOM_PORT or DEFINED_PORT. Use it when the failure you care about is wiring, a property, a security rule or a real SQL statement. Tradeoff: it is the slowest and the least diagnosable, so keep the number small and combine it with Testcontainers for anything the embedded database cannot represent. It bites when it becomes the only kind of test, because a suite that takes ten minutes stops being run.", level: "mid", d: ["Spring_Boot_Testing_Slices"] },
    { q: "What does spring.jpa.hibernate.ddl-auto do in development and in production, and why?", a: "It controls schema management by Hibernate: create, create-drop, update, validate or none. In development create-drop is convenient; in production you want validate or none, with Flyway or Liquibase owning the schema, because update performs unversioned, unpredictable DDL and nobody can review or roll it back. Tradeoff: validate fails startup on drift, which is exactly the point. It bites when update has quietly altered a production table and the change is not in any migration file.", level: "mid", d: ["Spring_Boot_Migration_3", "Spring_Boot_Deployment"] },
    { q: "How do you trace a slow request from end to end?", a: "Start with a trace: read the latency of the endpoint from Micrometer, find the slowest span in the tracing backend, and drill into the child spans for the database, cache and remote calls. Then correlate with structured logs carrying the same trace id, and confirm the hypothesis with a query plan or a profiler. Tradeoff: this is a lot of tooling, which is why spending effort on correlation up front pays off during an incident. It bites when metrics tell you the endpoint is slow but nothing tells you which of its fifty internal steps is responsible.", level: "senior", d: ["Spring_Boot_Observability"] },
    { q: "What is the difference between @RequestBody and @RequestParam, and when does each apply?", a: "@RequestParam binds a single value from the query string, form field or path-adjacent parameter, with a required flag and a default; @RequestBody deserialises the whole request body once through a message converter, which is where JSON DTOs, validation and content negotiation apply. Use parameters for filters, pagination and simple flags, and a body for anything with structure. Tradeoff: mixing them in one handler is legal and confusing. It bites when a large query object is spread across twenty parameters and nothing validates them together.", level: "junior", d: ["Spring_Boot_Layers", "Spring_Boot_Request_Path"] },
    { q: "How do you paginate a large table efficiently?", a: "Use keyset (seek) pagination for deep pages - order by a unique, indexed column and continue from the last key seen - because OFFSET makes the database generate and discard every skipped row. Reserve offset paging for shallow pages where the UI needs absolute page numbers, and make the sort column part of an index. Tradeoff: keyset pagination cannot jump to an arbitrary page, so the user interface has to be infinite scroll or next/previous. It bites with fetch joins, where in-memory pagination silently returns a page whose size is the number of joined rows.", level: "mid", d: ["Spring_Boot_Data_Model", "Spring_Boot_Nplus1"] },
    { q: "How do you read rows into DTOs efficiently, and when is it better than loading entities?", a: "Use a JPQL constructor expression or an interface-based projection, selecting only the columns the screen needs, so no entity is managed, no lazy loading is possible and no dirty checking happens. For aggregation, a single grouped query beats loading rows into memory. Tradeoff: projections are verbose, and if the same shape is needed in twenty places a mapper over fetched entities may be simpler. It bites when a projection is introduced to fix one slow screen and then hand-written SQL spreads through the repository layer.", level: "mid", d: ["Spring_Boot_Nplus1", "Spring_Boot_Data_Model"] },
    { q: "What is a retry storm, and how do you prevent one?", a: "A retry storm is a feedback loop: a dependency slows down, clients time out and retry, the added load slows it further, and the failure amplifies instead of recovering. Prevent it with exponential backoff and jitter, a strict retry budget or a circuit breaker that stops sending requests entirely, and a bulkhead so one dependency cannot consume the whole thread pool. Tradeoff: retries improve resilience for short blips and are actively harmful during a sustained outage. It bites when a timeout is added to a client that already retries three times, giving nine attempts per request with no backoff.", level: "senior", d: ["Spring_Boot_AntiPatterns", "Spring_Boot_Deployment"] },
    { q: "How do you rate limit an endpoint, and what do you have to decide first?", a: "Decide the key (user, API key or IP), the algorithm (token bucket or leaky bucket) and where the state lives - in-memory per instance, or shared in Redis for a fleet. Return 429 with a Retry-After header, and reject early in the filter chain so you do not consume a request thread per rejected call. Tradeoff: local counters are cheap and approximate across replicas; shared counters are accurate and add a network hop. It bites with in-memory state behind a load balancer, where the effective limit is the per-instance limit multiplied by the replica count.", level: "mid", d: ["Spring_Boot_Security_JWT", "Spring_Boot_Request_Path"] },
    { q: "What is a circuit breaker, and when does it beat retries?", a: "A circuit breaker trips after a threshold of failures and fails fast without calling the dependency, then probes periodically to see whether it has recovered. It is the right tool for a sustained outage, where retries only add load. Combine it with a bulkhead so the failing dependency cannot exhaust your pool, and keep short retries for the blip case. Tradeoff: fast failure means fast errors for clients, so it needs a fallback or a degraded response, otherwise you have replaced a slow outage with a loud one.", level: "senior", d: ["Spring_Boot_AntiPatterns", "Spring_Boot_Deployment"] },
    { q: "How do you design a service to degrade gracefully instead of failing completely?", a: "Classify each dependency by whether the feature can survive without it, then supply a fallback: a cached value, a default, a reduced response or an explicit error. Return partial results rather than throwing when the API allows it, and make readiness reflect only what is truly required to serve traffic. Tradeoff: fallbacks hide degradation from monitoring unless you metric them separately, and stale data has business consequences. It bites when a fallback returns empty data that clients interpret as 'no orders' rather than 'unknown'.", level: "senior", d: ["Spring_Boot_Caching", "Spring_Boot_Observability"] },
    { q: "What is the difference between authentication and authorization, and where does each belong in Spring Security?", a: "Authentication establishes who the caller is and produces an Authentication in the SecurityContext; authorization decides what that identity may do, expressed as request matchers for URLs and @PreAuthorize for use cases. Both are enforced in the filter chain, with method security covering calls that have no HTTP entry point. Tradeoff: URL rules are coarse and easy to get wrong as the API grows, so prefer method security for the rules that matter. It bites when a new endpoint is added and is covered by a broad permitAll matcher.", level: "junior", d: ["Spring_Boot_Security_JWT"] },
    { q: "How do you secure the actuator endpoints in a container platform?", a: "Bind the management server to a separate port, or keep the base path but restrict every management matcher to authenticated roles or to the pod network, and expose only the endpoints the platform needs (health, prometheus, info). Never expose env, configprops, heapdump or shutdown publicly. Tradeoff: a separate port means a second surface to secure and to open in network policies. It bites when the readiness probe and the metrics scraper end up on the public application port because the default path was never changed.", level: "mid", d: ["Spring_Boot_Observability", "Spring_Boot_Security_JWT"] },
    { q: "Which transaction manager should you use, and when does the choice matter?", a: "JpaTransactionManager for a pure JPA/Hibernate application, DataSourceTransactionManager for plain JDBC, and a JTA manager when several resource managers must join one transaction. The distinction matters for NESTED propagation and for whether JDBC-level operations and JPA share one unit of work, and it explains what happens when you mix JDBC writes into a JPA transaction. Tradeoff: the JPA manager is convenient and hides the boundary; knowing where it ends makes surprises explainable. It bites with read-modify-write logic that mixes a native query with a JPA flush.", level: "senior", d: ["Spring_Boot_Transactions", "Spring_Boot_Data_Model"] },
    { q: "What does a read-only transaction do, and is it worth using?", a: "A transaction marked readOnly tells the persistence provider it may skip dirty checking, avoid flushing and, depending on the database, route the connection to a read replica. Spring Data also applies the hint to derived queries. Tradeoff: it is an optimisation that is easy to misuse - writing through a read-only transaction fails, and routing to a replica introduces replication lag that will surface as 'the data I just wrote is missing'. It bites when someone adds readOnly = true to a method that is only conceptually a read.", level: "mid", d: ["Spring_Boot_Transactions"] },
    { q: "How do you evolve a public API without breaking clients?", a: "Treat the contract as versioned and additive: new optional fields, tolerant readers that ignore unknown fields, and deprecation with a measured removal date rather than an immediate change. Keep the DTO separate from the entity so the schema can move underneath, and use content negotiation or a version segment only when you truly need a parallel version. Tradeoff: backward compatibility is a constraint, not a virtue - a rename that improves the code can break a client that cannot be changed. It bites when a database column rename is coupled to a JSON field rename in the same release.", level: "mid", d: ["Spring_Boot_Layers", "Spring_Boot_Migration_3"] },
    { q: "What are the options for packaging a Spring Boot application as a container image, and what does each trade?", a: "A fat jar with a JRE base is the simplest; an exploded or layered jar on a minimal base gives better layer caching and a smaller attack surface; bootBuildImage produces an OCI image with the same layering from Maven or Gradle. In all cases run as a non-root user and pass JVM options through JAVA_TOOL_OPTIONS or an entrypoint. Tradeoff: a minimal base is harder to debug because there is no shell. It bites with an image that runs as root, which quietly breaks pod security policies and widens the blast radius of a container escape.", level: "mid", d: ["Spring_Boot_Deployment"] },
    { q: "In what order should a beginner learn Spring Boot, and why that order?", a: "Start with the vocabulary everything else leans on - annotations, the IoC container, dependency injection and what a bean actually is - because none of that needs Spring Boot and every later topic assumes it. Then Boot basics: start.spring.io, @SpringBootApplication, application.properties, and what auto-configuration did for you before you learn to replace it. Only after that web and REST, then data and transactions, then the advanced parts (AOP, security, caching, profiles), and finally testing and packaging. When it bites: people who jump straight to endpoints can ship code but cannot explain why a bean is missing or why a transaction did not roll back.", level: "junior", d: ["Spring_Boot_Roadmap"] },
    { q: "What is a join table, and why does the book store need book_category?", a: "A join table is a table whose only job is to link two entities: one foreign key per side and usually a composite primary key made of both. Book and Category are many-to-many in both directions, so neither table can carry the foreign key, and book_category does it instead, declared once with @JoinTable on the owning side. Tradeoff: declaring @ManyToMany on both entities leaves Hibernate unsure which side writes the link and inserts break, while promoting the link to its own entity is the right move as soon as the link carries data such as a display position. When it bites: navigating the collection triggers an extra select per row, which is exactly where N+1 problems start.", level: "junior", d: ["Spring_Boot_Data_Model"] },
    { q: "Your controller returns a DTO - what has to happen before the bytes leave the server?", a: "After your handler returns, DispatcherServlet hands the value to the HttpMessageConverter chain: content negotiation reads the Accept header, picks MappingJackson2HttpMessageConverter, and the configured ObjectMapper serialises the DTO to bytes, which are written back through the response wrapper the filters created. An Accept header no converter can satisfy produces 406 instead of a partial body, which is the visible sign that this step exists. Tradeoff: returning a JPA entity instead of a DTO moves lazy loading, recursion and date formats into serialization, far away from the code that made the decision. When it bites: a lazy association touched here is loaded after the service method returned, so the transaction may already be closed and you get a LazyInitializationException.", level: "junior", d: ["Spring_Boot_Request_Path"] },
    { q: "How many threads does a Spring MVC request use, and what happens when the database is slow?", a: "One servlet thread owns the request from the filter chain to the final write of the response - Tomcat's default pool is 200 threads - and it holds that thread for the whole duration, including while the database call blocks. So capacity is bounded by the thread pool rather than by CPU, and a slow query turns into queued requests at the connector rather than into higher CPU. Tradeoff: one-thread-per-request is easy to reason about and perfectly fine for typical CRUD, and the honest fixes are a faster query, a bounded pool with timeouts, or moving slow work off the request thread. When it bites: you raise the pool size to fix latency, exhaust the database connection pool instead, and the outage just moves one layer down.", level: "junior", d: ["Spring_Boot_Request_Path", "Spring_Boot_WebFlux"] },
    { q: "What is the difference between a bean definition and the bean itself?", a: "A BeanDefinition is metadata only - bean name, class, scope, property values and injection points - produced by component scanning or an @Bean method while the context refreshes, and at that point no object exists. The bean is the instance that gets built when the container walks those definitions: constructed, dependency-populated, initialised, then cached if it is a singleton. Tradeoff: definitions are cheap and reusable, so prototype scope means one definition producing many objects, while a singleton is created once and handed out for the life of the context. When it bites: infrastructure that runs at definition time - conditions, BeanFactoryPostProcessors - tries to use a live, fully wired object and gets either a half-built context or a null dependency.", level: "junior", d: ["Spring_Boot_Bean_Lifecycle"] },
    { q: "Why is @PostConstruct not the same place as the constructor?", a: "The constructor runs at instantiation, when anything injected by field or setter is still null; @PostConstruct runs later, after dependency population and the Aware callbacks, so the bean is fully wired by the time it executes. With constructor injection both points can see the collaborators, which is exactly why constructor injection removes the window where the object is only half valid. Tradeoff: @PostConstruct only runs for beans the container created, never for objects you new yourself, and it should not need other beans - use constructor injection or @DependsOn for that. When it bites: start-up code in a constructor quietly depends on a field injection that has not happened yet, or a @PostConstruct touches a collaborator that is still initialising.", level: "junior", d: ["Spring_Boot_Bean_Lifecycle"] },
    { q: "From the caller's point of view, what is the difference between a cache hit and a cache miss?", a: "None - the method returns the same value either way, and the controller above it never learns a cache exists. Mechanism: the proxy asks the CacheManager for the named cache, computes the key, and on a hit returns the stored value without invoking your method at all - no service logic, no repository call, no database round trip. Tradeoff: the hit is cheaper but older, so the answer you serve can predate a write that happened after it was stored. When it bites: when the cached value contains anything request- or user-specific, because the value outlives the request and will be handed to the next caller.", level: "junior", d: ["Spring_Boot_Caching"] },
    { q: "Why does calling a @Cacheable method from inside the same class skip the cache?", a: "The cache lookup lives in an interceptor on the proxy that wraps the service, so only calls that arrive through that proxy are ever checked against the cache. A method calling this.otherCachedMethod() never leaves the target object, the interceptor is never entered, and the database query runs every time - silently, with no error and no log line. Tradeoff: proxy-based caching is transparent and needs no bytecode weaving, which is precisely why the failure is invisible instead of loud. When it bites: a helper method inside the service, or a cached method that only performs correctly when a controller calls it.", level: "junior", d: ["Spring_Boot_Caching", "Spring_Boot_AOP_Proxy"] },
    { q: "What is relaxed binding, and why does Spring Boot accept three spellings of the same property?", a: "Relaxed binding normalises the key before matching it, so app.datasource-url, app.datasourceUrl and APP_DATASOURCE_URL all resolve to one logical property, and dots, dashes, underscores and case inside a name fold together. That is what lets a Java field named dataSourceUrl be set from an environment variable with no mapping code, and it applies across system properties, command-line args, YAML and profile files. Tradeoff: the leniency is also the trap - a misspelled key is not an error, it simply never matches and you keep the default, and @Value reads the literal key so it gets none of this. When it bites: an environment variable that almost matches, so the application starts happily against the wrong database URL.", level: "junior", d: ["Spring_Boot_Config_Properties"] },
    { q: "What does a Spring Boot starter actually contain?", a: "Mostly metadata: a build module that pulls in a curated, version-managed set of transitive dependencies, plus the auto-configuration classes it enables, listed in that jar under META-INF/spring/org.springframework.boot.autoconfigure.AutoConfiguration.imports. It contains no application code of its own - the behaviour comes from the jars it drags in and from the conditions Boot evaluates against the resulting classpath. Tradeoff: one extra dependency can silently enable an entire subsystem, because the classpath, not your code, decides what gets auto-configured. When it bites: a starter you barely need brings in a connection pool, a security filter chain or a metrics registry you then have to find and switch off.", level: "junior", d: ["Spring_Boot_AutoConfiguration", "Spring_Boot_Roadmap"] },
    { q: "You add spring-boot-starter-web and write no configuration - what is now running that you did not write?", a: "An embedded Tomcat, the DispatcherServlet mapped to /, Jackson message converters, validation, format providers, the default error handling, and the MVC auto-configuration that registers the HandlerMappings and HandlerAdapters your controllers need. Mechanism: the classes those jars put on the classpath satisfy the conditions in the matching auto-configurations, so the beans are registered with zero code from you. Tradeoff: the same mechanism means an unused starter can add beans, filters and endpoints you never asked for. When it bites: an unexpected 404 or a filter you did not write appears, and the auto-configuration condition report is the only place that explains which configuration put it there.", level: "junior", d: ["Spring_Boot_AutoConfiguration", "Spring_Boot_Request_Path"] },
    { q: "What is the difference between a unit test and an integration test in a Spring Boot project?", a: "A unit test is plain JUnit with Mockito - no Spring context, no container, milliseconds per test - so it can only fail because your logic is wrong. An integration test boots real wiring, either a slice such as @DataJpaTest or a full @SpringBootTest backed by Testcontainers, so it can fail because a bean is missing, a property is misnamed or the SQL does not match the dialect, but it costs seconds. Tradeoff: integration tests catch the classes of failure unit tests structurally cannot, while unit tests give you the volume and speed that make refactoring safe. When it bites: when the fast suite only proves your mocks agree with you, or the slow suite grows until nobody runs it.", level: "junior", d: ["Spring_Boot_Testing_Slices"] },
    { q: "What is the difference between calling another service over REST and publishing a message to a broker?", a: "A REST call is synchronous and coupled: the caller waits, the callee must be up, and a failure has to be dealt with at that moment or the request fails. Publishing to a broker is a hand-off - you record that something happened, it is acknowledged, and a consumer deals with it later at its own pace, even if the other side is down for an hour. Tradeoff: you gain decoupling and retries for free and you give up immediacy - nobody can tell you whether the consumer has processed the message yet. When it bites: when the caller needs a definite answer, because with at-least-once delivery the honest answer is 'probably, possibly twice'.", level: "junior", d: ["Spring_Boot_Messaging"] },
    { q: "Why might an API return 201 Created before the confirmation email has actually been sent?", a: "Because the contract is the order, not the side effect: the order row and the intent to notify are committed together, and the HTTP response must not wait for an SMTP server on another continent. Mechanism: in the outbox pattern the service writes the order and an outbox row in one transaction; after commit a relay moves that row to the broker, and only then does a consumer send the mail. Tradeoff: the client gets a fast, reliable 201 and accepts eventual delivery, and a crash between publishing and marking the row sent produces a duplicate rather than a lost message. When it bites: when you try to make it exactly-once by holding the transaction open across the broker publish, because now the database has a distributed-systems problem it cannot solve.", level: "junior", d: ["Spring_Boot_Messaging"] },
    { q: "Spring Boot 3 defaults to CGLIB proxies rather than JDK dynamic proxies - what does that actually change?", a: "Boot sets spring.aop.proxy-target-class=true, so Spring subclasses your class with CGLIB instead of generating an interface-based proxy, which means the injected reference is assignable to the concrete type even when the bean has no interface at all. Tradeoff: no interface is required, so single-implementation services stay clean, but the class and everything it advises must not be final, because the proxy has to override those methods to run the interceptors. When it bites: a final method is simply not advised, so @Transactional on it is silently ignored, while a final class fails outright when Spring tries to subclass it. Flip to JDK proxies with spring.aop.proxy-target-class=false and every injection point must be typed to the interface, or the context fails to start.", level: "mid", d: ["Spring_Boot_AOP_Proxy"] },
    { q: "If @Transactional and @Cacheable sit on the same method, which advice runs first and why does it matter?", a: "Both are advisors on the same proxy and the chain runs outside-in: whichever advisor has the lower order value is outermost and sees the call first, and Spring does not promise a default order between the transaction and cache advisors - both sit at lowest precedence until you order them explicitly. Tradeoff: cache outside the transaction is what you usually want, because a hit returns before any connection or transaction is touched, but then a stale value can only be repaired by evicting after commit. Transaction outside the cache is simpler to reason about, but a hit still pays for a transaction, and a miss stores the computed value before the transaction commits - so a rollback leaves a value in the cache that was never written. When it bites: a rolled-back request quietly poisons a hot key, and every subsequent reader gets the poisoned value.", level: "mid", d: ["Spring_Boot_AOP_Proxy", "Spring_Boot_Caching"] },
    { q: "During the bean lifecycle, when is the AOP proxy created, and what does that imply inside @PostConstruct?", a: "The proxy is created after initialisation: a BeanPostProcessor's postProcessAfterInitialization wraps the fully initialised target and returns the proxy, and that proxy is what the context publishes and what every other bean injects. So inside @PostConstruct you are still looking at the raw object - this is not proxied and no advice exists yet - even though the collaborators injected around it already point at proxies. Tradeoff: this is why the target class must be subclassable, and why the proxying phase is one of the last things that can still fail the refresh. When it bites: an @PostConstruct that kicks off async or transactional work through this runs with no advice at all, and the failure is as silent as any other self-invocation.", level: "mid", d: ["Spring_Boot_AOP_Proxy", "Spring_Boot_Bean_Lifecycle"] },
    { q: "What happens to @PreDestroy when the bean is prototype-scoped?", a: "Nothing: the container runs instantiation, population and @PostConstruct, hands the object over and steps out, so @PreDestroy, DisposableBean.destroy and any custom destroy method are never called by the container. The object lives until whoever holds it drops it, which means Spring has no idea when a connection, scheduler or file handle owned by that bean should be released. Tradeoff: prototype scope buys a fresh object per use at the cost of taking over the whole lifetime of that object. When it bites: a prototype bean wrapping a resource leaks silently, and the fix is either to keep the resource in a singleton and inject it, or to let the caller close it explicitly.", level: "mid", d: ["Spring_Boot_Bean_Lifecycle"] },
    { q: "What is a cache stampede, and how do you prevent it?", a: "A stampede happens when a popular key expires and many concurrent callers all miss at the same instant, so they all run the expensive query together and the database absorbs the full burst instead of one request. Mechanism: on a miss the interceptor simply invokes your method, so nothing serialises the callers - the usual fix is single-flight, letting one thread recompute while the others wait on a lock, or refreshing ahead of expiry so the key never lapses. Tradeoff: locking adds latency and a failure mode of its own, while a shorter TTL reduces staleness but makes the stampede more likely. When it bites: right after a hot key expires under load, which looks like a random database spike with no deploy to explain it.", level: "mid", d: ["Spring_Boot_Caching"] },
    { q: "What makes a good cache key, and give an example of one that quietly leaks data between users?", a: "The key must contain every input that changes the result and nothing less: Spring's default is a SimpleKey over the method arguments, so a method taking a category id and the current user only gets a safe key if both are parameters or part of a custom key generator. A key built only from the category id on a method that also filters by the logged-in user serves one user's personalised result to the next caller who hits that category. Tradeoff: rich keys with user, tenant and locale are correct but fragment the cache and cut the hit rate, while coarse keys buy reuse at the cost of correctness. When it bites: multi-tenant or personalised endpoints, where a key that looks fine in development is a data leak in production.", level: "mid", d: ["Spring_Boot_Caching"] },
    { q: "How do Kafka partitions and consumer groups decide ordering and parallelism?", a: "A partition is the unit of both: messages with the same key land in the same partition and are read in order, while a consumer group spreads partitions across its members so at most one member reads a given partition at a time. Scale by adding instances to the group - up to the partition count - or by adding consumer threads to the listener container, and a rebalance then moves partitions between members mid-run. Tradeoff: more partitions buy more parallelism but are also more ordering scopes, more files on the broker and slower, more frequent rebalances. When it bites: messages keyed on a random UUID so ordering means nothing, or consumers added beyond the partition count that sit idle forever.", level: "mid", d: ["Spring_Boot_Messaging"] },
    { q: "Why must an external side effect such as an email or a payment call stay outside the database transaction?", a: "A transaction only promises atomicity over your own tables: an email already sent cannot be unsent, and a card already charged cannot be refunded by a rollback, so a side effect performed inside the boundary is a promise you cannot keep. Commit first, then perform the effect - ideally by writing an outbox row in the same commit and letting a relay publish after it, with the consumer doing the work. Tradeoff: the effect now happens after the commit, so the system is genuinely eventually consistent, and the window between commit and effect is a state your monitoring has to cover. When it bites: you call the payment gateway inside @Transactional, the transaction times out and rolls back after the gateway has already taken the money.", level: "mid", d: ["Spring_Boot_Messaging"] },
    { q: "In what order does Spring Boot resolve configuration, from highest to lowest precedence?", a: "Highest first: command-line arguments, then SPRING_APPLICATION_JSON, then Java system properties, then OS environment variables, then profile-specific files such as application-prod.yml, then the plain application.properties or application.yml inside and outside the jar, and finally the framework's built-in defaults. Mechanism: these become one Environment as an ordered list of PropertySources and the first source containing the key wins - it is a lookup, not a merge of values. Tradeoff: that ordering is what lets one immutable image run everywhere, because deployment config always sits above anything committed to git. When it bites: a value someone baked into a committed profile file that silently beats the environment variable the platform injected, and nobody can see why.", level: "mid", d: ["Spring_Boot_Config_Properties"] },
    { q: "What does spring.config.import give you, and what do you have to watch in the ordering?", a: "It pulls another property source into the current one, so a large codebase can keep a single shared base file and let each service import it instead of copying defaults into twenty repositories. An imported file is read at the point the import appears, so a later import, or your own application.properties, wins over an earlier one - precedence follows the order you wrote. Tradeoff: the optional: prefix makes a missing file non-fatal, which is convenient for a shared config that may not exist in tests and dangerous in production, because a typo then means you silently ran on defaults. When it bites: an import chain nobody can trace by reading one file, which is why developers end up at the env endpoint to find out where a key actually came from.", level: "mid", d: ["Spring_Boot_Config_Properties"] },
    { q: "What is the difference between component scanning and auto-configuration?", a: "Component scanning is yours: @SpringBootApplication walks the packages beneath your application class and registers every @Component, @Service, @Repository and @Controller it finds, so the bean exists because you wrote the annotation. Auto-configuration is the framework's: candidates are listed in each jar's AutoConfiguration.imports, filtered by conditions on classpath, web application type and properties, and only the survivors define beans such as DataSource, Jackson and DispatcherServlet. Tradeoff: your own beans are the signal that makes an auto-configuration back off, which is exactly how defining a DataSource of your own skips the default one. When it bites: a bean you expected is missing and the cause is a failed condition, not a scanning path - only the condition report distinguishes the two.", level: "mid", d: ["Spring_Boot_AutoConfiguration"] },
    { q: "What does @ConditionalOnProperty do, and what does matchIfMissing change?", a: "It registers the bean only when the resolved property matches the expected value, which is how a subsystem can exist on the classpath but stay dormant until someone configures it. havingValue sets what counts as a match, and matchIfMissing flips the default: with matchIfMissing = true the bean is created unless the property is explicitly set to false, so you can ship a feature that is on by default but switchable. Tradeoff: the condition reads the resolved property, so relaxed binding applies and a default nobody documented becomes invisible behaviour. When it bites: a typo in the key or an inactive profile means the property is simply absent, the condition fails and the bean never appears - with no error anywhere.", level: "mid", d: ["Spring_Boot_AutoConfiguration"] },
    { q: "What are Mono and Flux, and what does it mean that they are lazy?", a: "Mono carries zero or one value and Flux zero or many, and both are descriptions of a computation rather than the computation itself: building the chain only registers operators. Mechanism: nothing runs until something subscribes, which is what WebFlux does when it returns your type to the client, and each operator is a stage that may hop to another scheduler. Tradeoff: laziness is what makes cancellation and back-pressure possible - you can stop a Flux nobody wants - but it also means code with no subscriber is a silent no-op. When it bites: you build a query, log 'about to run', and the log appears after the response, or a Mono returned from a method nobody subscribes to never touches the database.", level: "mid", d: ["Spring_Boot_WebFlux"] },
    { q: "A WebFlux handler calls a blocking JDBC query. What actually happens, and what are your options?", a: "The call parks the thread it runs on; if that is an event-loop thread, every other request sharing that loop waits behind it, which shows up as high latency at low CPU - the classic reactive misdiagnosis. Your options are to use R2DBC for a genuinely non-blocking path, to wrap the call in Mono.fromCallable(...).subscribeOn(Schedulers.boundedElastic()) so it runs on the bounded pool Reactor reserves for blocking work, or to keep that endpoint on Spring MVC. Tradeoff: boundedElastic protects the event loop but is still a thread pool you have to size, and mixing JPA into a reactive stream gives you the worst of both stacks. When it bites: one repository method that quietly blocks turns a service that should hold thousands of connections into one that degrades on a handful.", level: "mid", d: ["Spring_Boot_WebFlux"] },
    { q: "If the annotations look identical, what is actually different between Spring MVC and WebFlux?", a: "The dispatcher: DispatcherServlet and its HandlerAdapter chain on a servlet container with one thread per request is replaced by DispatcherHandler on Reactor Netty's event loops, with the same @RestController and @RequestMapping annotations above it. Everything downstream changes with it - handlers return Mono and Flux instead of values, error handling moves from an error page to ErrorWebExceptionHandler, and sessions, security filters and converters need their reactive counterparts. Tradeoff: a controller can look exactly like the MVC version while its threading contract is completely different, which makes copying a blocking method across trivially easy. When it bites: a filter, a security chain or a JPA repository written for MVC lands in a reactive application and blocks the event loop.", level: "mid", d: ["Spring_Boot_WebFlux"] },
    { q: "What exactly does @WebMvcTest load, and what do you have to provide yourself?", a: "It loads the MVC slice: your @Controller and @ControllerAdvice classes, message converters, validators, format providers, filters and WebMvcConfigurer beans, while @Component, @Service and @Repository beans are deliberately left out of the context. You supply the missing collaborators with @MockBean (or @MockitoBean on newer Boot versions) plus @Import for configuration the slice does not scan, and you drive requests through the MockMvc the slice installs. Tradeoff: you get real serialisation, validation and status handling in about a second, at the cost of never exercising your service or repository. When it bites: a mock is stubbed with the wrong signature or return contract and the test still passes, because the mock was never checked against the real bean.", level: "mid", d: ["Spring_Boot_Testing_Slices"] },
    { q: "What does @DataJpaTest give you that a plain repository test does not, and where does it mislead you?", a: "It boots JPA for real - entities, mappings, derived queries, constraints and the generated repository proxies - with each test wrapped in a transaction that rolls back so tests never contaminate each other, which is what a hand-rolled repository test cannot give you. It also swaps your DataSource for an embedded database by default, for speed and isolation from your local configuration. Tradeoff: H2 speaks a different dialect from PostgreSQL, so a query can pass the slice and fail in production; use @AutoConfigureTestDatabase(replace = NONE) with a Testcontainers database when the SQL matters. When it bites: on a database-specific function, on lock behaviour, or on a migration that has never actually been applied to the schema the test used.", level: "mid", d: ["Spring_Boot_Testing_Slices"] },
    { q: "How do you test a class that calls an external HTTP API?", a: "Test the client in isolation with @RestClientTest, which loads only the outbound client infrastructure and pairs it with MockRestServiceServer, so you assert the exact URL, method, headers and body that go on the wire. That catches a renamed field or a broken URL on your side in milliseconds, without a network. Tradeoff: it proves nothing about whether the remote API still sends what you expect, so a thin contract test against the real service or a recorded stub has to cover the other half. When it bites: you mock your own wrapper class instead of the wire, and the test passes while the actual request is malformed.", level: "mid", d: ["Spring_Boot_Testing_Slices"] },
    { q: "What is the difference between standaloneSetup MockMvc and @WebMvcTest?", a: "standaloneSetup builds the MVC infrastructure around a controller you construct yourself, with no Spring context at all - you add converters and validators by hand and each test runs in milliseconds. @WebMvcTest boots a real application slice, so your @ControllerAdvice, filters, WebMvcConfigurer beans and the auto-configured MVC defaults are present, and collaborators outside the slice are mocked for you. Tradeoff: standalone is fast and focused but blind to anything the container would have wired, while the slice is closer to production but slower and still cannot see your services. When it bites: a validation rule or converter registered by auto-configuration runs in the slice and never runs in the standalone test, so the two disagree in CI.", level: "mid", d: ["Spring_Boot_Testing_Slices"] },
    { q: "Why is the unit price stored on the order line instead of read from the Book?", a: "An order line is a historical record: it must state what the customer paid at that moment, independent of what the book costs next week. Copy the price onto OrderItem when the line is created and the order total becomes a sum over lines that can never be recomputed into a different number. Tradeoff: the value is duplicated across rows, and a deliberate correction to a book's price will not change history - which is exactly the point. When it bites: someone simplifies the model by reading Book.price at invoice time, and last month's invoice silently changes.", level: "mid", d: ["Spring_Boot_Data_Model"] },
    { q: "Why is Payment a separate entity rather than a few columns on Order?", a: "Payment has its own lifecycle and status machine - authorised, captured, failed, refunded - plus provider identifiers and timestamps that do not belong on an order header. Modelling it as a one-to-one association with the owning side on Payment keeps Order as a transaction record while payment concerns, retries and webhooks evolve in their own table. Tradeoff: you now have two aggregates to keep consistent, so the payment update needs its own transaction boundary instead of riding along with the order. When it bites: a failed payment has to roll back or compensate the order, and if the provider call sits inside one big transaction you are holding database locks across a network call.", level: "mid", d: ["Spring_Boot_Data_Model"] },
    { q: "Why does Order carry a total field instead of computing a SUM at read time?", a: "The total is part of the order's contract, so it is stored with the order: one read gives you the header and its amount, no aggregation query runs, and the number cannot change when a book price or a discount rule changes afterwards. It is computed once in the service, inside the transaction that creates the order, from the line items - never taken from a value the client sent. Tradeoff: a stored total can drift from the sum of its lines if someone updates a line without recomputing, so the calculation must live in exactly one place. When it bites: a discount is applied in the controller instead of the service, and the stored total disagrees with the lines.", level: "mid", d: ["Spring_Boot_Data_Model"] },
    { q: "If you have no @ControllerAdvice, what happens to an exception thrown from your service method?", a: "It propagates out of the controller, through the interceptor chain and DispatcherServlet, to the servlet container, which forwards the request to Boot's error handling - the BasicErrorController at /error - and you get a 500 with a JSON body containing status, error, path and timestamp. Nothing about your domain exception survives: no field-level detail, no stable error code, no distinction between a bad request and a real fault. Tradeoff: the default is safe and never leaks internals, which makes it fine for an internal service and inadequate for a public API. When it bites: clients start parsing that default body, so adding a @ControllerAdvice later changes the shape of every error response - a breaking contract change you never intended.", level: "mid", d: ["Spring_Boot_Request_Path"] },
    { q: "What happens between DispatcherServlet choosing your handler method and the first line of that method executing?", a: "HandlerAdapter drives it: each parameter is resolved by a HandlerMethodArgumentResolvers chain, with @RequestBody converted by an HttpMessageConverter and validated when it carries @Valid, while @PathVariable and @RequestParam are pulled from the URI template and query string. Conversion failures never reach your code - malformed JSON raises HttpMessageNotReadableException and a constraint violation raises MethodArgumentNotValidException, both before line one runs. Tradeoff: this is why the framework can enforce the contract without your method seeing invalid input, and why exception handling has to cover argument-resolution errors and not just domain errors. When it bites: those exceptions go through the HandlerExceptionResolvers, so if no advice maps them the request falls through to generic error handling with a status you did not choose.", level: "mid", d: ["Spring_Boot_Request_Path"] },
    { q: "Where do Spring Boot bugs most often come from in practice, and why?", a: "Data and transactions, by a distance: propagation rules, rollback-only marking, self-invocation that silently skips @Transactional, and N+1 queries all produce code that works in the demo and fails under load or on an exception path. The reason is that the semantics are invisible - a transaction boundary is an annotation, a generated proxy and a thread-bound resource, so nothing in the call stack looks wrong when it is. Tradeoff: Boot's defaults are forgiving enough that the failure is deferred to production, where the exception is far from its cause. When it bites: an exception caught and swallowed inside a service marks the transaction rollback-only, and the caller later fails with UnexpectedRollbackException having never thrown anything itself.", level: "mid", d: ["Spring_Boot_Roadmap"] },
    { q: "Why does Spring Boot refuse a circular dependency between two constructor-injected beans?", a: "Since Spring Boot 2.6, and therefore 3.x, circular references are rejected by default, so two beans that need each other fail at startup with a BeanCurrentlyInCreationException instead of being resolved quietly. Field or setter injection would previously have let one bean finish holding a reference to a half-built other bean; Boot turns that off too, and spring.main.allow-circular-references=true only restores the old, fragile behaviour. The real fix is structural: extract the shared concern into a third bean, invert one direction behind an interface, or break the cycle with @Lazy so the dependency is created on first use. When it bites: a service that calls back into its caller - the cycle is a design smell, not a wiring accident.", level: "mid", d: ["Spring_Boot_Bean_Lifecycle"] },
    { q: "A checked exception escapes a @Transactional method and the data is still committed. What rule is Spring applying, and what would you change?", a: "Mechanism: the default rollback rules only cover RuntimeException and Error, so a checked exception is treated as normal completion and the transaction commits even though the caller sees a failure. Tradeoff: setting rollbackFor = Exception.class fixes it in one line but also rolls back for checked exceptions you may want to survive, so the sharper fix is to stop pushing checked exceptions across the transaction boundary. When it bites: JDBC, Jakarta Persistence and HTTP client wrappers surface IOException or ServletException out of a service method, and you only find the inconsistency when a reconciliation job compares the API response with the table.", level: "mid", d: ["Spring_Boot_AntiPatterns", "Spring_Boot_Transactions"] },
    { q: "When does lazy initialization actually help, and what does it cost you?", a: "Mechanism: @Lazy, or spring.main.lazy-initialization=true, defers bean creation until first access, so context refresh skips building beans that this particular deployment never uses. Tradeoff: you move construction failures from deploy time to first use, so a broken bean becomes a runtime error instead of a failed rollout, and the first request pays the whole cost at once. When it bites: @Scheduled and @Async registrations only happen when the bean is instantiated, so a lazily created scheduler bean can sit idle forever while readiness reports green.", level: "mid", d: ["Spring_Boot_Startup"] },
    { q: "Why would a service depend on its own repository interface instead of JpaRepository directly, and when is that not worth it?", a: "Mechanism: taking a port as a dependency keeps JpaRepository, paging and specification types out of the service signature, so the unit of work reads in domain terms and you can test a rule with a hand-written fake instead of booting a context. Tradeoff: one implementation behind one interface buys you little beyond a file and an extra jump in the IDE, while a fake can silently disagree with real JPQL and real lock behaviour until a Testcontainers run exposes it. When it bites: teams abstract everything, then discover the interesting behaviour lives in queries and lock modes, so the interface becomes a pass-through that hides the query a reviewer should have seen.", level: "mid", d: ["Spring_Boot_Layers"] },
    { q: "How do you add a health check for a dependency, and what belongs in liveness versus readiness?", a: "Mechanism: define a HealthIndicator bean, its name becomes the component key, return Health.Builder().up() or .down() with details, then decide membership with management.endpoint.health.group.readiness.include and liveness.include. Tradeoff: an indicator that really calls the dependency gives you honest readiness but multiplies load, because the orchestrator polls every few seconds from every pod. When it bites: a downstream outage wired into liveness makes the platform restart pods that were perfectly capable of recovering, while a cold cache wired into readiness keeps the entire fleet out of the load balancer during a deploy.", level: "mid", d: ["Spring_Boot_Observability"] },
    { q: "How do you stop a cache eviction or a cache fill from racing the transaction that owns the data?", a: "Mechanism: cache operations run where the method runs, not when the transaction commits, so an eviction inside a transactional method can be observed by another thread before commit; that thread re-reads the old row and caches it, undoing your eviction for the whole TTL. Tradeoff: Spring's TransactionAwareCacheDecorator defers puts and evicts until afterCompletion, which is correct but only applies if your CacheManager is wrapped, and it makes eviction timing harder to reason about. When it bites: checkout evicts pricing inside the order transaction, a concurrent request repopulates the stale price, and users keep seeing the old price long after the database is already correct.", level: "mid", d: ["Spring_Boot_Caching", "Spring_Boot_Transactions"] },
    { q: "A stateless JWT API cannot revoke a token. How would you design session lifetime anyway?", a: "Mechanism: keep the access token short, five to fifteen minutes, and put a refresh token behind it with rotation, so each refresh issues a fresh pair and a replayed old token reveals the theft. Tradeoff: rotation needs server-side state, a token family in Redis for reuse detection, which is exactly the statelessness you were avoiding, and logout either waits for the TTL or costs a denylist lookup on every request. When it bites: two devices refreshing at the same moment trip reuse detection and log the user out unless you allow a grace window, and a twenty-four hour token means a revoked employee keeps working until it expires.", level: "mid", d: ["Spring_Boot_Security_JWT"] },
    { q: "When is ApplicationEvent the right tool, and when do you need a broker?", a: "Mechanism: @EventListener runs inline in the caller's thread and transaction, and @TransactionalEventListener moves the work to afterCommit, so both are free, fast and need no infrastructure, but they only reach code in the same deployable. Tradeoff: a broker costs schema versioning, at-least-once semantics and an operations surface, and buys independent failure, independent scaling, replay and consumers you have not written yet. When it bites: an AFTER_COMMIT listener that sends an email drops that email if the pod dies between commit and listener, which is why payments, audit and anything with an SLA goes through an outbox a relay drains onto the broker.", level: "mid", d: ["Spring_Boot_Messaging", "Spring_Boot_Transactions"] },
    { q: "fixedRate, fixedDelay and cron - what does each guarantee when a job overruns?", a: "Mechanism: Spring arms one ReschedulingRunnable per method and re-arms it after the run finishes, so the same scheduled method never runs concurrently with itself. Tradeoff: fixedDelay measures from completion, so the gap is always real and the cadence slips quietly; fixedRate keeps a fixed nominal schedule, so once a run overruns the period the next fires as soon as the current run finishes and the job goes back-to-back; cron fires at the next matching time and simply skips occurrences it missed. When it bites: a fixedRate of one second with a 1.5 second run never sleeps again, while a nightly cron with a two hour job quietly loses work on the days it overruns.", level: "mid", d: ["Spring_Boot_Async_Scheduling"] },
    { q: "@EntityGraph and JOIN FETCH both fetch associations in one query. When do you pick one over the other?", a: "Mechanism: JOIN FETCH is written in JPQL and is explicit about which collections it joins, while @EntityGraph is metadata on an entity or repository method that Hibernate turns into a fetch plan, so it works on derived query methods where you have no JPQL to edit. Tradeoff: an entity graph is reusable and typed, but it is declared once per method, two graphs cannot be combined on a single call, and subgraphs you forgot to mention are simply not fetched. When it bites: a graph that pulls in three collections produces a cartesian product you never wrote, and where the graph conflicts with the mapping Hibernate quietly falls back to extra selects, handing you back the N+1 you were trying to remove.", level: "mid", d: ["Spring_Boot_Nplus1"] },
    { q: "We are moving to Boot 3 and our security configuration no longer compiles. What do you rewrite?", a: "Mechanism: WebSecurityConfigurerAdapter is gone, so you declare a SecurityFilterChain bean, requestMatchers replaces antMatchers, and the lambda DSL replaces the chained and() calls, for example http.csrf(c -> c.disable()). Tradeoff: rules inside a chain are evaluated in declaration order and the first match wins, so a broad permitAll matcher placed at the top silently overrides everything below it, and your chain takes precedence over Boot's generated default chain. When it bites: a team rewrites only the syntax, keeps a stateless setup with session handling they never intended, and method security stops enforcing anything because @EnableGlobalMethodSecurity became @EnableMethodSecurity.", level: "mid", d: ["Spring_Boot_Migration_3", "Spring_Boot_Security_JWT"] },
    { q: "Compare rolling, blue-green and canary deployments for a Spring Boot service - what must the app support for each?", a: "Mechanism: rolling replaces pods gradually behind the load balancer, blue-green runs two full environments and flips traffic at once, canary routes a small percentage of requests to the new version before committing. Tradeoff: rolling needs surge capacity and a backward-compatible schema because two versions share one database, blue-green doubles capacity and gives an instant rollback but still shares that database, canary needs per-version routing and trustworthy SLO signals but limits blast radius to a few percent. When it bites: a rolling deploy with sticky sessions drops in-flight work, and a canary with no per-version dashboards tells you nothing until the error budget is already spent.", level: "mid", d: ["Spring_Boot_Deployment"] },
    { q: "What is a fat controller, and how do you recognise one before it becomes unmaintainable?", a: "Mechanism: a controller has gone fat when it contains business rules, loops over entities, talks to repositories, opens @Transactional, or assembles responses with logic that a scheduled job or a Kafka consumer will eventually need too. Tradeoff: moving everything into a service class just creates a two thousand line God service, so the real test is whether you can unit-test the rule without MockMvc and whether the same rule can be reused from a non-HTTP entry point. When it bites: the transaction then spans serialization and logging, the rule gets copy-pasted into the batch job, and a controller that was easy to write becomes the only place anyone dares to change anything.", level: "mid", d: ["Spring_Boot_AntiPatterns", "Spring_Boot_Layers"] },
    { q: "How do you size JVM memory and CPU flags for a Spring Boot app in Kubernetes, and what goes wrong when you get it wrong?", a: "Mechanism: the JVM sizes itself from the container limit only with container support enabled, so you set -XX:MaxRAMPercentage and -XX:InitialRAMPercentage instead of a fixed -Xmx, and you either let it read the CPU quota or pin it with -XX:ActiveProcessorCount. Tradeoff: heap is only part of the footprint - metaspace, thread stacks, code cache, direct buffers and native allocations all sit on top of it, so a heap at 75 percent of the limit plus the rest easily exceeds the limit. When it bites: you get an OOMKilled pod whose heap dump shows plenty of free memory, or a container limited to 500 milli-cores while the JVM spawns GC and JIT threads sized for the host's 64 cores, turning every latency graph into sawtooth spikes under throttling.", level: "senior", d: ["Spring_Boot_Deployment"] },
    { q: "What actually dominates Spring Boot startup time, and what are the levers to cut it?", a: "Mechanism: context refresh does the work - scanning and instantiating beans, CGLIB proxying, condition evaluation, then Hibernate building and validating its metamodel before Tomcat binds the port. Tradeoff: the honest levers are fewer beans, excluding auto-configuration you do not use, moving DDL and connection warm-up out of startup, and lazy initialization, which shortens boot only by hiding construction cost until first use. When it bites: autoscaling and rollouts are sensitive to a twelve second start because readiness stays false for the whole window, and a team that answers it with lazy initialization has also hidden a broken bean until the first user finds it.", level: "senior", d: ["Spring_Boot_Startup", "Spring_Boot_Deployment"] },
    { q: "What does @Configuration(proxyBeanMethods = false) change, and how can it bite you?", a: "Mechanism: with proxyBeanMethods true, a @Bean method calling another @Bean method goes through the container and returns the registered singleton; with false, it is an ordinary Java call and the caller gets a second, unmanaged instance. Tradeoff: lite mode skips a CGLIB subclass per configuration class, which is why Boot uses it on most auto-configuration, but anything the container applies to the registered bean - lifecycle callbacks, AOP proxies, validation - is missing from the copy the internal caller holds. When it bites: the same class behaves differently depending on which reference you have, because one of them never went through the container, and the bug only shows on the path that uses the internal call.", level: "senior", d: ["Spring_Boot_Startup"] },
    { q: "How do you make a 100k row insert fast with JPA, and where does it fall apart?", a: "Mechanism: you need all three of hibernate.jdbc.batch_size together with order_inserts, a flush and clear every few hundred rows so the persistence context does not hold a hundred thousand managed entities, and an id generation strategy that allows batching at all. Tradeoff: IDENTITY generation forces a getGeneratedKeys round trip per insert and effectively disables batching, while a pooled or sequence generator keeps it, and clearing the context detaches everything you loaded earlier. When it bites: the insert is fine with fifty rows in dev, then spends production time on one statement per row because MySQL needs rewriteBatchedStatements=true in the JDBC URL to combine them at all.", level: "senior", d: ["Spring_Boot_Transactions"] },
    { q: "What happens when a transaction holds a lock for five minutes, and how do you bound it?", a: "Mechanism: the connection stays checked out for the whole transaction, row locks stay held, and every waiter queues behind it - the database enforces this through statement_timeout, lock_timeout or innodb_lock_wait_timeout, while the pool enforces it through connectionTimeout and maxLifetime. Tradeoff: @Transactional(timeout = ...) states your intent, but the database-side timeout is what actually aborts a stuck session, and aggressive timeouts turn a slow report into an error while lenient ones let a single bad query drain the pool. When it bites: one runaway statement exhausts Hikari, the next requests fail with connection is not available after 30000 milliseconds, retries multiply the load, and the service collapses while the database itself is still healthy.", level: "senior", d: ["Spring_Boot_Transactions", "Spring_Boot_AntiPatterns"] },
    { q: "A colleague says @Async is not running asynchronously. What do you check, in order?", a: "Mechanism: check self-invocation first, because a call from inside the same bean never crosses the proxy, then that the method is public and neither class nor method is final, then which executor the call actually landed on. Tradeoff: a void @Async hands the caller nothing and routes exceptions to AsyncUncaughtExceptionHandler, which only logs by default, so a silent failure looks exactly like success. When it bites: the happy path works, the caller assumes an ordering that does not exist, and three months later you find the failure sitting in a log nobody reads.", level: "senior", d: ["Spring_Boot_AntiPatterns", "Spring_Boot_Async_Scheduling"] },
    { q: "What happens when your @Async executor queue fills up?", a: "Mechanism: Boot's auto-configured applicationTaskExecutor has eight core threads and an unbounded queue by default, so the queue never fills - an unbounded capacity makes max-size irrelevant and tasks simply accumulate on the heap. Tradeoff: bound the queue and you must pick a rejection policy, and CallerRunsPolicy is seductive because it never drops work, but it makes the submitting thread, often a Tomcat request thread, execute the job itself. When it bites: an unbounded queue looks perfectly healthy in metrics until an OOM, while CallerRunsPolicy under load drags background work into the HTTP path and takes the API down with the batch job.", level: "senior", d: ["Spring_Boot_AntiPatterns", "Spring_Boot_Async_Scheduling"] },
    { q: "What happens when a @Scheduled method throws, and what would you change?", a: "Mechanism: the scheduler catches the throwable, hands it to an error handler that logs it, and re-arms the trigger, so the job keeps firing and nothing outside the log file notices. Tradeoff: unlike an HTTP endpoint there is no status code and no caller to fail, so you have to add the signal yourself - a failure counter, a last-success gauge, an alert - and decide whether a partially applied run is idempotent before it fires again. When it bites: a nightly job that has been failing for six weeks looks identical to a healthy one, and the first complaint arrives when a downstream report comes up empty.", level: "senior", d: ["Spring_Boot_Async_Scheduling", "Spring_Boot_Observability"] },
    { q: "In Spring Kafka a message fails on every attempt. What happens by default, and how should you handle it?", a: "Mechanism: the listener container's error handler retries on the consumer thread with a backoff, so the partition is blocked until the retry budget is exhausted, and only then does a DeadLetterPublishingRecoverer publish the record to a dead-letter topic and let the container move on. Tradeoff: retries preserve ordering but stall every message behind the poison record, while skipping straight to the DLQ keeps the stream moving at the cost of reordering work that must stay ordered. When it bites: one record that violates a newly deployed schema version blocks a partition for an hour, lag alerts fire long before anyone reads the retry log, and the fix is a schema change deployed before the producer that wrote the bad record.", level: "senior", d: ["Spring_Boot_Messaging", "Spring_Boot_Transactions"] },
    { q: "How do you version messages so that a consumer can be deployed before its producer?", a: "Mechanism: put an explicit schema version or type on the payload and evolve additively - new optional fields, never renamed or repurposed ones - so a consumer can default what it needs and ignore what it does not recognise. Tradeoff: a topic per version makes migration explicit but multiplies topics and consumer groups, while one topic with versioned payloads is simpler but means old and new formats coexist for as long as retention runs. When it bites: the producer goes first and consumers start failing on a required field, or a consumer reads a legacy record during a replay and cannot tell it apart from a corrupt one.", level: "senior", d: ["Spring_Boot_Messaging", "Spring_Boot_Deployment"] },
    { q: "How does trace context survive a REST call and a Kafka message?", a: "Mechanism: the tracing integration injects W3C traceparent and baggage headers into outgoing HTTP requests and reads them back in the security filter chain, and for messaging it carries the same context as record headers so one trace spans producer, broker and listener. Tradeoff: propagation only happens when the call goes through an instrumented client or template, so a hand-built HttpClient, an unobserved RestTemplate or a template without observation enabled starts a brand new trace. When it bites: you see two disconnected traces for one business operation and cannot answer where the time went, because the gap sits exactly where the manual client call is.", level: "senior", d: ["Spring_Boot_Observability", "Spring_Boot_Messaging"] },
    { q: "You set trace sampling to ten percent. What can you no longer answer, and what do you do about it?", a: "Mechanism: sampling is decided when the span starts, so a head-based sampler cannot know yet whether this request ends in a 500, and ninety percent of failing requests leave you a metric and a log line but no trace. Tradeoff: raising the probability costs storage and collector load on every request, so the usual compromise is a low global rate, an always-sample decision for your riskiest routes, and metrics with exemplars that jump from a spike to the few traces you kept. When it bites: someone reports a slow endpoint at 14:03, you have the latency graph, and the trace for that exact request was sampled out - which is why correlation ids in every log line are not optional.", level: "senior", d: ["Spring_Boot_Observability"] },
    { q: "What breaks when you tag metrics with a user id or a raw URL?", a: "Mechanism: every distinct tag combination creates a new time series, so a user id turns one metric into millions, and query time, memory and storage scale with that count rather than with your traffic. Tradeoff: dimensions must be bounded and low cardinality - route template, status class, region - while individual identities belong in logs and traces, which are indexed per event instead of per series. When it bites: Boot's http.server.requests already records the route template rather than the raw path, so the mistake is usually your own extra tag, and the symptom is a dashboard that gets slower every week until the scrape target starts dropping series.", level: "senior", d: ["Spring_Boot_Observability"] },
    { q: "You verify the signature on a JWT. What else must you check before trusting it?", a: "Mechanism: Spring Security's decoder already applies a timestamp validator for exp and nbf with a small clock skew, but issuer, audience, token type and the algorithm itself must be configured explicitly, for example with JwtValidators.createDefaultWithIssuer plus a JwtClaimValidator on aud. Tradeoff: accepting whatever algorithm the token declares invites the classic key confusion attack, so the decoder must be pinned to the algorithms your key actually supports, and a generous clock skew hides a clock drift problem until tokens start failing together. When it bites: a token minted for another audience or another environment validates perfectly and grants access, because your service only ever looked at the signature.", level: "senior", d: ["Spring_Boot_Security_JWT"] },
    { q: "How do you rotate a JWT signing key without restarting the service or logging everyone out?", a: "Mechanism: point the decoder at a JWKS URI instead of a local secret, publish the new key with a fresh kid alongside the old one, and the decoder resolves keys per token and refreshes the set on a short cache, so both old and new tokens validate during the overlap window. Tradeoff: with a shared symmetric secret there is no kid to look up, so rotation means restarting every instance within the token TTL, which is why asymmetric keys or an issuer-hosted JWK set are the practical choice. When it bites: the old key is removed while tokens signed with it are still live and every request returns 401, or the JWK set endpoint is unreachable when the cache expires and authentication fails globally.", level: "senior", d: ["Spring_Boot_Security_JWT"] },
    { q: "Where should authorization live in a Spring Boot API - the filter chain, an annotation, or the service?", a: "Mechanism: the SecurityFilterChain handles coarse URL rules, @PreAuthorize handles role and permission checks against the security context the JWT filter populated, and a domain check inside the service handles rules about the specific row you just loaded. Tradeoff: URL rules are easy to forget when a new endpoint appears, method security is only as complete as your coverage of entry points, and doing it only in the service leaves a route that still runs argument binding and validation before being rejected. When it bites: a new controller ships without a matcher, or the check happens before the ownership query so the data is read anyway, and authorization ends up as a scattershot of half-applied rules nobody can audit.", level: "senior", d: ["Spring_Boot_Security_JWT", "Spring_Boot_Layers"] },
    { q: "What goes wrong when a JPA entity is returned straight from a controller?", a: "Mechanism: the entity carries lazy proxies and open-in-view keeps the session alive, so Jackson walks the graph during serialization and fires the N+1 selects you never wrote, while bidirectional references can cycle or bloat the payload. Tradeoff: on top of that the entity has setters and generated ids, so binding a request body onto it lets a client set status, owner or createdAt, and dirty checking will apply changes whenever the session happens to be open. When it bites: a small internal endpoint becomes a multi-second query storm, or an order is created with an admin-chosen price because that field happened to be on the entity.", level: "senior", d: ["Spring_Boot_Layers", "Spring_Boot_AntiPatterns"] },
    { q: "Where should the transaction boundary sit - controller, service or repository?", a: "Mechanism: it belongs on the service method that defines the unit of work, because that is where the business rule that must succeed or fail together lives, while repository methods are already transactional through the Spring Data base classes, so annotating them adds a second, shorter transaction rather than a stronger guarantee. Tradeoff: a controller-level @Transactional spans serialization and logging and holds a connection for the whole HTTP exchange, while a boundary that is too fine commits partial states the rule required to be atomic. When it bites: an endpoint holds a connection while it renders a small JSON response, or two repository calls that looked like one unit of work commit separately and a failure between them leaves the account updated but the ledger empty.", level: "senior", d: ["Spring_Boot_Layers", "Spring_Boot_Transactions"] },
    { q: "URLs that matched before the Boot 3 upgrade now return 404. What changed in request mapping?", a: "Mechanism: Spring Framework 6 matches with PathPatternParser, which is stricter than the old AntPathMatcher - a wildcard only sits at the end of a pattern, catch-all capture is written as {*var}, and optional trailing slash matching was deprecated with its default flipped from true to false in 6.0. Tradeoff: you can switch trailing slash matching back on, but the guidance is to normalise at the proxy or filter instead, so the behaviour now depends on a setting that is already on its way out. When it bites: clients calling /orders/1/ or a gateway that strips a prefix suddenly get a 404 rather than a route, and the regression only shows up for a subset of callers.", level: "senior", d: ["Spring_Boot_Migration_3"] },
    { q: "Two pods start at the same time and both try to run the migrations. What happens, and how do you prevent it?", a: "Mechanism: migration tools serialise themselves - Liquibase through the DATABASECHANGELOGLOCK table, Flyway by taking a lock before it touches the history table - so one instance runs DDL while the other waits, and when the application is the runner that wait can outlast your startup probe. Tradeoff: migrating from application startup is convenient for a single instance but makes ordering, failure handling and rollback part of your boot path, so the usual design is a separate init job or CI step with the application only checking that the schema is at the version it expects. When it bites: a rolling deploy with a slow migration has pods failing readiness while they queue for the lock, and one failed migration leaves a lock or history row that blocks every pod after it.", level: "senior", d: ["Spring_Boot_Migration_3", "Spring_Boot_Deployment"] },
    { q: "What is a cache stampede in a Spring Boot service, and how do you stop it?", a: "Mechanism: the entry expires, every concurrent caller misses at the same instant and they all run the expensive query, so the cache that was protecting the database becomes a synchronised hit on it. Tradeoff: @Cacheable(sync = true) collapses concurrent misses for a key by running the loader once, Caffeine's refreshAfterWrite reloads in the background while still serving the stale value, and a distributed lock works across pods but adds a coordination round trip to your hottest path. When it bites: a popular key with a ten minute TTL produces a spike exactly every ten minutes, the database sees a periodic thundering herd, and your latency graph starts to look like a heartbeat.", level: "senior", d: ["Spring_Boot_Caching"] },
    { q: "You evicted a cache entry in one pod but users still see stale data. Why?", a: "Mechanism: a local cache lives per JVM, so @CacheEvict only cleared one pod's map while the others keep serving their copy until it expires. Tradeoff: the fixes are a shared cache such as Redis, a short TTL plus accepting bounded staleness, or publishing an invalidation event that every pod consumes and evicts locally, which keeps reads fast but adds a broadcast path you now have to keep alive. When it bites: a fleet of eight pods behind a load balancer shows a stale price for up to the full TTL after an admin edit, and scaling out makes the inconsistency window worse rather than better.", level: "senior", d: ["Spring_Boot_Caching", "Spring_Boot_Messaging"] },
    { q: "What are the failure modes of a badly designed @Cacheable key?", a: "Mechanism: the key is built from SpEL, so anything you leave out creates collisions - a key of only the method name returns the same entry for every argument - and anything unbounded you put in, such as a whole request object, grows the cache without limit. Tradeoff: capping size and TTL trades correctness for memory, which is why unless = '#result == null' is worth setting so an empty or failed lookup is never served as a permanent answer. When it bites: a tenant-scoped method keys only on the record id and serves one customer's data to another, or an unbounded key set evicts everything useful every few minutes.", level: "senior", d: ["Spring_Boot_Caching", "Spring_Boot_AntiPatterns"] },
    { q: "When is JOIN FETCH the wrong fix for N+1?", a: "Mechanism: joining a collection multiplies each parent row by the size of that collection, so Hibernate either returns duplicate parents or applies DISTINCT, and with pagination it frequently has to fetch the full result set before it can trim it in memory. Tradeoff: one round trip looks cheaper than N, but when the collection is wide the transfer and hydration cost exceeds N batched selects, which is why loading parent ids first and then children with an IN clause is often the better shape. When it bites: a list page of twenty orders with fifty line items each hydrates a thousand rows to render twenty, and a query that was instant on a small dev dataset brings production to its knees.", level: "senior", d: ["Spring_Boot_Nplus1"] },
    { q: "How do you catch an N+1 before it reaches production?", a: "Mechanism: the reliable version is a test that enables Hibernate statistics or counts statements through a logging datasource proxy, runs one service call, and fails if the query count crosses a threshold you set. Tradeoff: leaving hibernate.generate_statistics on in production means paying for it on every statement, while eyeballing show-sql in dev finds nothing because your fixture dataset has three rows. When it bites: the count is fine against tiny fixtures and explodes on real data, so the assertion needs a seeded dataset with a realistic number of children, not the three rows your fixture creator likes to use.", level: "senior", d: ["Spring_Boot_Nplus1", "Spring_Boot_Observability"] },
    { q: "Why does pagination fall apart when you add a collection fetch join, and what do you do instead?", a: "Mechanism: once a join fetch multiplies each logical row, setFirstResult and setMaxResults cannot be pushed down safely, so Hibernate either paginates a DISTINCT result in memory or the database rejects the query - Postgres refuses ORDER BY columns that are not in a SELECT DISTINCT list. Tradeoff: the standard escapes are paginating parent ids first and fetching children with an IN clause, a window function in a native query, or a projection that returns exactly the columns the screen needs. When it bites: an OFFSET of forty thousand on a joined result scans and discards far more rows than the page you asked for, so the query gets slower exactly as the user scrolls deeper.", level: "senior", d: ["Spring_Boot_Nplus1"] },
    { q: "What has to happen between SIGTERM and process exit so in-flight Kafka consumers do not lose work?", a: "Mechanism: listener containers are SmartLifecycle beans, so the context close stops polling and waits for the current records to finish, bounded by the lifecycle shutdown timeout, after which the consumer group rebalances onto another instance. Tradeoff: a long shutdown buys a clean handoff but the platform still SIGKILLs the pod if you exceed the grace period, while a short one cuts processing mid-record and relies on at-least-once redelivery after the rebalance. When it bites: an instance killed during a batch of side effects either duplicates them or drops them, which is exactly why the consumer must be idempotent no matter how carefully you tune the drain.", level: "senior", d: ["Spring_Boot_Deployment", "Spring_Boot_Messaging"] },
    { q: "How do you log authentication failures without turning your logs into a credential store?", a: "Mechanism: Spring Security publishes authentication success and failure events, so you log the outcome, the subject, the client address and a correlation id, and you deliberately keep the bearer token itself out of the message and out of any exception text. Tradeoff: hashing or truncating the token gives you enough to correlate repeated attempts without leaving something that can be replayed, but dropping it entirely means you cannot tie two log lines to the same credential. When it bites: a verbose DEBUG dump of the Authorization header during an incident review leaks a live token into a log aggregator with thirty day retention and read access for half the company.", level: "senior", d: ["Spring_Boot_Security_JWT", "Spring_Boot_Observability"] },
  ],
  glossary: [
    { term: "Auto-configuration", def: "A configuration class shipped by a library that defines beans when its conditions match what is on your classpath and what you have already defined. It backs off when you supply the bean yourself, which is the supported way to override it without excluding anything.", d: ["Spring_Boot_AutoConfiguration"] },
    { term: "Starter", def: "A dependency descriptor with no code of its own that pulls in a curated set of libraries for one job, such as spring-boot-starter-data-jpa. Starters are how auto-configuration gets onto the classpath in the first place.", d: ["Spring_Boot_AutoConfiguration", "Spring_Boot_Roadmap"] },
    { term: "@SpringBootApplication", def: "A convenience annotation combining @SpringBootConfiguration, @EnableAutoConfiguration and @ComponentScan, placed on the outermost class. Its package is the default component-scan root, which is why packages above it are invisible to the scan.", d: ["Spring_Boot_Startup"] },
    { term: "Bean", def: "An object managed by the container: the container creates it, injects its dependencies, controls its lifecycle and applies post-processing such as proxies. A plain new object is not a bean, and therefore gets no transactions, caching or validation.", d: ["Spring_Boot_Startup", "Spring_Boot_Bean_Lifecycle"] },
    { term: "ApplicationContext", def: "The central container interface, extending BeanFactory with component scanning, events, resource loading and internationalisation. It also owns the bean lifecycle and is what most application code should not depend on directly.", d: ["Spring_Boot_Startup"] },
    { term: "BeanFactory", def: "The minimal container interface for looking up beans by name or type. ApplicationContext adds the enterprise features on top, and in practice you interact with the context, not the bare factory.", d: ["Spring_Boot_Startup", "Spring_Boot_Bean_Lifecycle"] },
    { term: "Dependency injection", def: "Supplying a collaborator from outside rather than constructing it inside, which decouples the consumer from the implementation and makes the dependency explicit. In Spring this is constructor injection in almost all cases.", d: ["Spring_Boot_Layers", "Spring_Boot_Startup"] },
    { term: "Component scanning", def: "The container's discovery of @Component, @Service, @Repository and @Controller classes in the packages under the @SpringBootApplication class. It is separate from auto-configuration: your own classes are scanned, library configurations are imported.", d: ["Spring_Boot_Startup"] },
    { term: "@Configuration", def: "A class whose @Bean methods define beans. In Boot 2.2+ it defaults to proxyBeanMethods = false, so methods call each other directly instead of through an enhanced subclass of the configuration class.", d: ["Spring_Boot_AutoConfiguration"] },
    { term: "@Bean", def: "A method on a configuration class whose return value becomes a container-managed bean, with full lifecycle and post-processing. It is the imperative counterpart of stereotypes, and the way you adapt third-party classes.", d: ["Spring_Boot_Startup", "Spring_Boot_AutoConfiguration"] },
    { term: "@AutoConfiguration", def: "The Boot 3 marker for an auto-configuration class, implying @Configuration(proxyBeanMethods = false). Candidates are listed in META-INF/spring/org.springframework.boot.autoconfigure.AutoConfiguration.imports, which replaced the spring.factories entry point.", d: ["Spring_Boot_AutoConfiguration", "Spring_Boot_Migration_3"] },
    { term: "@ConditionalOnMissingBean", def: "A condition that registers the bean only if the application has not already defined that type, which is the standard back-off mechanism and the reason your own DataSource wins over the auto-configured one.", d: ["Spring_Boot_AutoConfiguration"] },
    { term: "@ConditionalOnProperty", def: "A condition that matches when a property equals an expected value; a missing property counts as no match unless matchIfMissing is set. It is how features are switched on by configuration.", d: ["Spring_Boot_AutoConfiguration"] },
    { term: "BeanPostProcessor", def: "An interface invoked around each bean's initialisation - before and after its own init callbacks - so that proxies, @Autowired injection of existing beans and annotation processing can happen. It is the mechanism behind nearly every cross-cutting feature.", d: ["Spring_Boot_Bean_Lifecycle", "Spring_Boot_AOP_Proxy"] },
    { term: "BeanFactoryPostProcessor", def: "Invoked before any bean is instantiated, allowing modification of bean definitions themselves - property placeholder resolution being the canonical example. It runs earlier than BeanPostProcessors, so it cannot touch bean instances.", d: ["Spring_Boot_Bean_Lifecycle"] },
    { term: "EnvironmentPostProcessor", def: "A Boot extension point that mutates the Environment during startup, before the context is created. It is how early configuration, such as a bootstrap phase or an additional property source, is installed.", d: ["Spring_Boot_Config_Properties", "Spring_Boot_Migration_3"] },
    { term: "@PostConstruct", def: "A jakarta.annotation callback invoked after dependency injection and before InitializingBean and any custom init method. Use it for starting resources the bean owns, not for work that needs other beans that may not be built yet.", d: ["Spring_Boot_Bean_Lifecycle"] },
    { term: "DisposableBean / @PreDestroy", def: "Shutdown callbacks invoked in the order @PreDestroy, DisposableBean.destroy, then a custom destroy-method, in reverse dependency order. Anything that holds a connection, a thread or a socket should release it here.", d: ["Spring_Boot_Bean_Lifecycle"] },
    { term: "@ConfigurationProperties", def: "An annotation that binds externalised configuration to a typed object using relaxed binding, with defaults and JSR-380 validation. It replaces scattering @Value placeholders through business classes.", d: ["Spring_Boot_Config_Properties"] },
    { term: "Relaxed binding", def: "The rule set that lets spring.datasource.url, SPRING_DATASOURCE_URL and the equivalent system property all refer to the same value, with kebab-case, camelCase and underscore forms accepted in the right places.", d: ["Spring_Boot_Config_Properties"] },
    { term: "Profile", def: "A named environment dimension that selects additional configuration documents and conditions beans, activated with spring.profiles.active. Profile-specific files overlay the non-specific ones key by key, not file by file.", d: ["Spring_Boot_Config_Properties"] },
    { term: "Config Data (spring.config.import)", def: "The Boot 2.4+ mechanism for importing additional property documents, optionally, with defined precedence. It is how external files and config servers are layered without rewriting the classic application.properties lookup.", d: ["Spring_Boot_Config_Properties"] },
    { term: "Property placeholder", def: "The ${...} syntax resolved against the Environment, with defaults written ${name:default}. It is useful for small values and awkward for anything a class should not hard-code.", d: ["Spring_Boot_Config_Properties"] },
    { term: "DispatcherServlet", def: "The Spring MVC front controller that maps a request to a handler, invokes it with argument resolvers, and renders the return value. Everything in Spring MVC happens inside it, which is why filters registered around it are the right place for transport-level concerns.", d: ["Spring_Boot_Request_Path", "Spring_Boot_Layers"] },
    { term: "@RestController", def: "@Controller plus @ResponseBody at class level, so handler return values are written to the response body as JSON rather than resolved as a view name.", d: ["Spring_Boot_Layers"] },
    { term: "@RestControllerAdvice", def: "A global exception handler applying @ExceptionHandler and @ResponseBody across all controllers, the natural home for mapping domain exceptions to status codes and a consistent problem body.", d: ["Spring_Boot_Layers", "Spring_Boot_AntiPatterns"] },
    { term: "@ExceptionHandler", def: "A method that handles a specific exception type for one controller or, inside an advice class, for all of them. It must not be private, and the exception it declares is the one that triggers it.", d: ["Spring_Boot_Layers"] },
    { term: "HandlerInterceptor", def: "Spring MVC's preHandle, postHandle and afterCompletion callbacks, running inside the DispatcherServlet around handler invocation. Unlike a filter it can see handler metadata and the model, but it cannot rewrite the request before mapping.", d: ["Spring_Boot_Request_Path"] },
    { term: "Filter", def: "A servlet-spec component in the container's chain that wraps requests and responses before and after the DispatcherServlet. It is the correct place for security context, CORS, request logging, rate limiting and MDC setup.", d: ["Spring_Boot_Request_Path", "Spring_Boot_Security_JWT"] },
    { term: "DTO", def: "A data object shaped for a use case or an API contract rather than for the database. Mapping between entity and DTO keeps the schema, the domain model and the public API independently changeable, and avoids serialising lazy associations.", d: ["Spring_Boot_Layers", "Spring_Boot_Data_Model"] },
    { term: "Bean Validation (jakarta.validation)", def: "Declarative constraints such as @NotNull, @Size and @Pattern on DTO fields, enforced at the web boundary and reported as field errors. Annotate nested objects with @Valid so constraints cascade.", d: ["Spring_Boot_Layers"] },
    { term: "Connection pool", def: "A bounded set of database connections reused across requests, managed by HikariCP by default in Spring Boot. It decouples concurrency from connection creation cost, which is why its size is a capacity decision about the database rather than about the application.", d: ["Spring_Boot_AutoConfiguration", "Spring_Boot_Transactions"] },
    { term: "@TransactionalEventListener", def: "Handles an application event after the surrounding transaction commits, so a listener cannot observe - or act on - data that is about to be rolled back. It is the in-process alternative to the transactional outbox when the consumer is in the same application.", d: ["Spring_Boot_Messaging", "Spring_Boot_Transactions"] },
    { term: "ApplicationEventPublisher", def: "Publishes application events that @EventListener and @TransactionalEventListener methods receive. The mechanism is synchronous by default and runs inside the publishing thread, unless you wrap it in @Async - which is a common source of 'my listener sometimes does not run' confusion during shutdown.", d: ["Spring_Boot_Startup", "Spring_Boot_Messaging"] },
    { term: "Micrometer Observation", def: "The vendor-neutral instrumenting API in Spring Boot that produces metrics and spans from one set of instrumentation across HTTP, JDBC, caching and messaging. It is what makes tracing and metrics consistent without instrumenting every call site by hand.", d: ["Spring_Boot_Observability"] },
    { term: "Connection pool leak detection", def: "A HikariCP setting (leakDetectionThreshold) that logs the stack trace of any connection held longer than the threshold. It is the fastest way to find code that acquires a connection outside a transaction or never returns it, which otherwise shows up only as pool exhaustion.", d: ["Spring_Boot_Transactions", "Spring_Boot_Deployment"] },
    { term: "Optimistic locking (@Version)", def: "A column holding a version number that Hibernate checks on every update, throwing an OptimisticLockException if the row changed underneath. It gives good concurrency with no held locks, at the cost of failed writes that must be retried with a fresh read.", d: ["Spring_Boot_Transactions", "Spring_Boot_Data_Model"] },
    { term: "Pessimistic locking", def: "Locking selected rows for the duration of the transaction with SELECT ... FOR UPDATE, so a read-modify-write sequence is indivisible. It suits hot rows at the cost of holding locks and increasing contention and deadlock risk.", d: ["Spring_Boot_Transactions"] },
    { term: "ddl-auto", def: "The Hibernate schema-management setting (create, create-drop, update, validate, none). Development may use create-drop, but production should use validate with Flyway or Liquibase owning the schema, because update performs unreviewed and unversioned DDL.", d: ["Spring_Boot_Migration_3", "Spring_Boot_Deployment"] },
    { term: "Condition Evaluation Report", def: "The startup report produced with --debug that lists every auto-configuration considered and the outcome of its conditions. It is the fastest way to find out whether a bean was never imported or was imported and then skipped by a condition.", d: ["Spring_Boot_AutoConfiguration", "Spring_Boot_Startup"] },
    { term: "Backpressure", def: "The mechanism by which a reactive consumer tells a producer to slow down, defined in the Reactive Streams contract. Without it, a fast database source with a slow consumer buffers without limit - which is how an unbounded queue turns a traffic spike into an out-of-memory failure.", d: ["Spring_Boot_WebFlux"] },
    { term: "Rolling update", def: "A deployment that replaces pods gradually while old and new versions serve traffic simultaneously. It requires backward compatible schema changes, graceful shutdown, and readiness gating, because for part of the rollout two different versions of the code are live.", d: ["Spring_Boot_Deployment", "Spring_Boot_Migration_3"] },
    { term: "Sidecar or init container", def: "Kubernetes patterns for supporting processes: an init container runs migrations or waits for a dependency before the app starts, and a sidecar runs alongside it. They exist because coordination inside a single JVM is impossible once the work is cross-cutting.", d: ["Spring_Boot_Deployment"] },
    { term: "Cucumber-style end-to-end test", def: "A test that exercises a running system the way a client does, over HTTP and through the real security chain. It is the highest-fidelity and slowest test, and it belongs at the boundaries where the wiring between components can only be verified by running them.", d: ["Spring_Boot_Testing_Slices", "Spring_Boot_Security_JWT"] },
    { term: "Micrometer context propagation", def: "A library that copies registered thread-local values (MDC, the SecurityContext, tracing context) across thread and Reactor boundaries, so an async or reactive hop keeps the same trace and user. It complements a TaskDecorator, which is the hook for imperative executors.", d: ["Spring_Boot_Async_Scheduling", "Spring_Boot_Observability"] },
    { term: "@Valid vs @Validated", def: "@Valid is the specification annotation used to trigger cascading validation of a request object; @Validated is Spring's annotation that enables method-level constraint validation on a class and supports validation groups. Using the wrong one in a service usually means the constraint is never evaluated.", d: ["Spring_Boot_Layers"] },
    { term: "Spring Data repository", def: "An interface extending CrudRepository or JpaRepository that the framework implements with a runtime proxy, deriving queries from method names, annotations or @Query. There is no generated class and no implementation to write.", d: ["Spring_Boot_Layers", "Spring_Boot_Data_Model"] },
    { term: "EntityManager / Hibernate Session", def: "The JPA unit-of-work object that holds the persistence context, manages the first-level cache, flushes changes and participates in the transaction. In a web request its lifetime is the transaction, unless Open Session in View extends it.", d: ["Spring_Boot_Transactions", "Spring_Boot_Nplus1"] },
    { term: "First-level cache (persistence context)", def: "The per-transaction identity map of managed entities, which guarantees identity within a transaction and drives dirty checking. It explains why loading the same entity twice gives one instance and one query.", d: ["Spring_Boot_Nplus1", "Spring_Boot_Transactions"] },
    { term: "Second-level cache", def: "A shared or cross-JVM entity cache configured with a region factory and @Cacheable on entities. It is off by default, invalidation is coarse, and it is rarely worth the operational cost in a service with several replicas.", d: ["Spring_Boot_Caching"] },
    { term: "N+1 select", def: "One query to load a list plus one query per row to initialise a lazy association. It is the most common performance defect in JPA applications and shows up as log volume that grows with the result size.", d: ["Spring_Boot_Nplus1"] },
    { term: "Join fetch / @EntityGraph", def: "Two declarative ways to fetch a related association in the same SQL statement instead of a second one. Both may produce duplicate rows for to-many associations and both need care with paging.", d: ["Spring_Boot_Nplus1"] },
    { term: "LAZY vs EAGER", def: "Whether an association is loaded with the owning query or through a proxy on first access. JPA defaults @ManyToOne to EAGER and @OneToMany to LAZY, an asymmetry that quietly shapes your query load.", d: ["Spring_Boot_Data_Model", "Spring_Boot_Nplus1"] },
    { term: "Open Session in View", def: "The Boot default that keeps the EntityManager bound to the request thread so lazy loading still works during response rendering. It hides LazyInitializationException at the cost of holding a pooled connection for the whole request.", d: ["Spring_Boot_Nplus1", "Spring_Boot_Transactions"] },
    { term: "Batch fetching", def: "Telling Hibernate to load collections or entities in batches with IN clauses via hibernate.default_batch_fetch_size or @BatchSize, which collapses an N+1 into a small fixed number of statements at the cost of memory.", d: ["Spring_Boot_Nplus1"] },
    { term: "Transaction (ACID)", def: "A unit of work whose changes commit atomically and either all become visible or none do, with isolation defining what concurrent transactions can see. In Spring it is managed by a PlatformTransactionManager bound to the thread.", d: ["Spring_Boot_Transactions"] },
    { term: "Propagation REQUIRED", def: "The default propagation: join the current transaction if one exists, otherwise create it. Commit and rollback happen at the outermost boundary, which is why an inner failure poisons the whole unit of work.", d: ["Spring_Boot_Transactions"] },
    { term: "Propagation REQUIRES_NEW", def: "Suspends the current transaction and starts an independent one on a second connection, committing even if the outer transaction later rolls back. Use it for records that must survive failure, and budget for the extra connection.", d: ["Spring_Boot_Transactions"] },
    { term: "Propagation NESTED", def: "Uses a JDBC savepoint inside the current transaction so the inner part can roll back independently without a second connection. It requires savepoint support from the driver and transaction manager, and it is not a real independent transaction.", d: ["Spring_Boot_Transactions"] },
    { term: "Rollback-only", def: "A flag marking a participating transaction as doomed, set when an inner participant fails. Catching the exception in application code does not clear it, and the eventual commit fails with UnexpectedRollbackException.", d: ["Spring_Boot_Transactions"] },
    { term: "Self-invocation", def: "Calling a method of the same object from inside that object, which bypasses any Spring proxy. It silently disables @Transactional, @Async, @Cacheable and @Retryable on the inner method, which is why those annotations must live on externally invoked public methods.", d: ["Spring_Boot_AOP_Proxy", "Spring_Boot_Transactions"] },
    { term: "JDK dynamic proxy vs CGLIB", def: "Two ways to build the AOP proxy: JDK proxies implement interfaces and cannot reach class members, CGLIB subclasses the target and can override non-final methods. Spring Boot defaults to CGLIB (proxyTargetClass = true), so final classes and methods silently lose their advice.", d: ["Spring_Boot_AOP_Proxy"] },
    { term: "Pointcut", def: "The expression selecting which join points advice applies to. Spring's AspectJ-style pointcuts match execution of methods, and the match is resolved at proxy creation time, which is why the target must be known when the proxy is built.", d: ["Spring_Boot_AOP_Proxy"] },
    { term: "Cache abstraction", def: "Spring's Cache and CacheManager interfaces that let @Cacheable work with Caffeine, Redis or any other backend. Separating the annotation from the implementation means a cache can be swapped without touching business code.", d: ["Spring_Boot_Caching"] },
    { term: "Caffeine", def: "The modern in-memory cache library Boot uses for a simple local cache, with size and expiry bounds that a naive ConcurrentMapCacheManager lacks. Because it is per-JVM, entries and evictions are not shared between replicas.", d: ["Spring_Boot_Caching"] },
    { term: "@Cacheable / @CacheEvict", def: "Annotations implemented as cache advice on a proxy: @Cacheable reads through the cache, @CachePut overwrites and @CacheEvict removes entries, all requiring that the method is invoked through the proxy. Values are stored only on successful return.", d: ["Spring_Boot_Caching"] },
    { term: "Cache-aside", def: "The default caching pattern: read from the cache, and on a miss query the database and populate the cache. The application owns invalidation, which is both the flexibility and the failure mode, since a missed eviction serves stale data until the TTL expires.", d: ["Spring_Boot_Caching"] },
    { term: "Flyway / Liquibase", def: "Schema migration tools that apply versioned SQL or changesets and record what has run. They should be a deployment step rather than application startup, so rolling deploys do not race for DDL locks.", d: ["Spring_Boot_Deployment", "Spring_Boot_Migration_3"] },
    { term: "HikariCP", def: "The connection pool Boot auto-configures, fast and well instrumented with Micrometer metrics and a leak detector. maximumPoolSize is a decision about total database capacity, not a performance knob to raise under pressure.", d: ["Spring_Boot_AutoConfiguration", "Spring_Boot_Deployment"] },
    { term: "Actuator", def: "The starter that adds production endpoints - health, info, metrics, env, loggers, prometheus, and more. Only health and info are exposed over HTTP by default; anything else must be enabled explicitly, ideally on a separate management port.", d: ["Spring_Boot_Observability"] },
    { term: "Micrometer", def: "The metrics facade behind Spring Boot's instrumentation, recording counters, timers, gauges and distributions into a MeterRegistry. It is vendor-neutral, and cardinality is the discipline it forces on you.", d: ["Spring_Boot_Observability"] },
    { term: "Prometheus / OpenMetrics", def: "The scrape-based metrics format and ecosystem most Spring Boot deployments use; adding micrometer-registry-prometheus exposes /actuator/prometheus for the scraper. Pull-based collection means the application does not need to know where the backend is.", d: ["Spring_Boot_Observability"] },
    { term: "OpenTelemetry", def: "A vendor-neutral standard for traces, metrics and logs, used in Spring Boot through Micrometer Tracing and an OTel SDK with an OTLP exporter. It brings context propagation so spans from different services join into one trace.", d: ["Spring_Boot_Observability"] },
    { term: "Span / trace", def: "A span is one timed operation within a trace; the trace is the whole request across services. Putting the trace and span identifiers in log lines is what connects a stack of messages to the actual call tree.", d: ["Spring_Boot_Observability"] },
    { term: "Graceful shutdown", def: "Stop accepting new requests, finish in-flight ones within a timeout, then destroy beans and close resources, configured with server.shutdown=graceful and spring.lifecycle.timeout-per-shutdown-phase. In Kubernetes it pairs with a preStop delay and a termination grace period.", d: ["Spring_Boot_Deployment", "Spring_Boot_Bean_Lifecycle"] },
    { term: "Liveness and readiness probes", def: "Liveness decides whether to restart a process and must only check things a restart fixes; readiness decides whether to send traffic and may check dependencies. Mixing them turns a database blip into a fleet-wide restart.", d: ["Spring_Boot_Observability", "Spring_Boot_Deployment"] },
    { term: "Virtual thread", def: "A lightweight JVM-managed thread (Java 21) that unmounts from its carrier when it blocks, enabled in Boot with spring.threads.virtual.enabled. Capacity planning shifts from thread counts to the genuinely scarce resources such as the database pool.", d: ["Spring_Boot_Async_Scheduling"] },
    { term: "TaskDecorator", def: "A hook that wraps task execution so you can capture and restore thread-local state - MDC, the SecurityContext, request attributes - and clear it afterwards. Without it, async and scheduled work runs with empty or stale context.", d: ["Spring_Boot_Async_Scheduling"] },
    { term: "@Async / TaskExecutor", def: "@Async is proxy advice that submits a call to an executor and returns immediately; the executor is what actually bounds concurrency. The default is uncapped, which is why production defines a ThreadPoolTaskExecutor with a bounded queue and a rejection policy.", d: ["Spring_Boot_Async_Scheduling"] },
    { term: "@Scheduled / TaskScheduler", def: "Annotations for cron and fixed-delay execution, driven by a TaskScheduler that is single-threaded by default, so one slow job delays all others. In a scaled deployment the job also needs a distributed lock or a single-worker design.", d: ["Spring_Boot_Async_Scheduling"] },
    { term: "Transactional outbox", def: "Writing a domain change and an intent-to-publish row in one database transaction, with a separate relay publishing to the broker. It removes the dual-write gap, at the cost of at-least-once delivery, a small delay and more moving parts.", d: ["Spring_Boot_Messaging"] },
    { term: "At-least-once delivery", def: "The realistic broker guarantee: a message may be delivered more than once after a failure, restart or rebalance. It is harmless only when consumers are idempotent, so deduplication belongs in the consumer's transaction.", d: ["Spring_Boot_Messaging"] },
    { term: "Idempotency", def: "The property that applying an operation repeatedly has the same effect as applying it once, usually implemented with a client-supplied key and a unique constraint. It is what makes retries, redeliveries and network timeouts safe to handle automatically.", d: ["Spring_Boot_Messaging", "Spring_Boot_Data_Model"] },
    { term: "Spring Security filter chain", def: "The ordered list of security filters wrapped by a FilterChainProxy, covering CSRF, authentication, authorization and exception translation. Because the whole model is filters and matchers, a rule on a path that is never requested is a rule that never runs.", d: ["Spring_Boot_Security_JWT"] },
    { term: "SecurityContext / SecurityContextHolder", def: "The holder for the current Authentication, kept per thread for the duration of a request and cleared afterwards. In a stateless API the context is rebuilt from the bearer token on every request, which is why it must never leak across pooled threads.", d: ["Spring_Boot_Security_JWT"] },
    { term: "CSRF", def: "Cross-site request forgery protection, enabled by default because browsers attach cookies automatically. It is unnecessary for a purely stateless bearer-token API and essential for anything that authenticates with a cookie.", d: ["Spring_Boot_Security_JWT"] },
    { term: "JWT", def: "A signed, self-contained token whose claims are verified by signature and expiry rather than by a session lookup. It removes per-request session state but requires careful key rotation, clock-skew handling and revocation strategy.", d: ["Spring_Boot_Security_JWT"] },
    { term: "OAuth2 resource server", def: "A service that validates tokens issued by someone else, configured in Boot with a jwk-set-uri or a public key plus issuer validation. It brings the standard filter chain and key refresh, and leaves claim-to-role mapping to you.", d: ["Spring_Boot_Security_JWT"] },
    { term: "Method security", def: "Declarative authorization inside the service layer with @PreAuthorize, @PostAuthorize and @EnableMethodSecurity, protecting use cases that have no HTTP entry point. It is proxy-based too, so self-invocation bypasses it just like @Transactional.", d: ["Spring_Boot_Security_JWT", "Spring_Boot_AOP_Proxy"] },
    { term: "Reactive Streams / Reactor", def: "The standard (Publisher, Subscriber, backpressure) and its Reactor implementation (Mono, Flux, operators) that WebFlux is built on. Backpressure is part of the contract, which is why collecting a Flux eagerly defeats the point.", d: ["Spring_Boot_WebFlux"] },
    { term: "Blocking the event loop", def: "Calling a blocking API from a non-reactive thread, which stalls every other request sharing that loop. The symptom is high latency at low CPU, and the fixes are R2DBC or an explicit hop to boundedElastic with a bounded pool.", d: ["Spring_Boot_WebFlux"] },
    { term: "WebFlux", def: "Spring's reactive web stack, built on Reactor Netty and non-blocking I/O. It is the right choice when concurrency per instance matters and every dependency can be non-blocking, and the wrong one when most work is CPU-bound or JDBC-based.", d: ["Spring_Boot_WebFlux"] },
    { term: "Jakarta EE", def: "The Java EE standard renamed to Jakarta, with the namespace moving from javax to jakarta in version 10 and the minimum Java version rising to 11. Spring Boot 3 targets Jakarta EE 9+ on Java 17, which is why every javax import must be migrated.", d: ["Spring_Boot_Migration_3"] },
    { term: "Expand-migrate-contract", def: "The safe schema evolution pattern: add compatible structures, migrate data in batches, then remove what is no longer needed once no old version runs. It is the foundation of a rolling deployment that can actually be rolled back.", d: ["Spring_Boot_Migration_3", "Spring_Boot_Deployment"] },
    { term: "Hibernate 6", def: "The JPA provider shipped with Spring Boot 3, with rewritten internals, new type handling and its own naming and schema tooling. It is stricter about what it accepts, so entity mappings and dialect-specific behaviour that worked under Hibernate 5 need re-checking after an upgrade.", d: ["Spring_Boot_Migration_3", "Spring_Boot_Data_Model"] },
    { term: "JVM container awareness", def: "The JVM's ability to size the heap from a cgroup memory limit, configured with -XX:MaxRAMPercentage. Native memory such as metaspace, direct buffers and thread stacks sits outside the heap, so a limit must leave headroom or the container is killed with exit code 137 and no Java error at all.", d: ["Spring_Boot_Deployment", "Spring_Boot_Async_Scheduling"] }
  ]
};
